-- Quizora sports expansion seed: 60 live sports quizzes (football, team sports, racket and combat, motorsport and winter, Olympics, countries and legends), 840 questions.
-- Idempotent: upserts games by slug and questions by (game_slug, item). Each line is one self-contained statement guarded by an md5 check; run the whole file or line by line in the Supabase SQL editor.
do $q$ declare d text := $d$[{"slug":"premier-league-legends","title":"Premier League Legends","tagline":"Invincibles, a 5,000-1 miracle and Golden Boots: top-flight drama from 1992 to 2023.","emoji":"\ud83e\udd81","gradient":["#7c3aed","#db2777"],"categories":["football","sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":310,"items":[{"k":"choice","i":"Which club won the very first Premier League title in 1992-93?","t":"Origins","e":"\ud83c\udfc6","f":"Aston Villa finished runners-up that season, ten points behind the champions.","o":["Aston Villa","Norwich City","Blackburn Rovers","Manchester United"],"s":{"index":3}},{"k":"truefalse","i":"The first Premier League season featured 22 clubs.","t":"Origins","e":"\ud83d\udd22","f":"The league was cut to 20 clubs from the 1995-96 season onwards.","a":true},{"k":"multi","i":"Select all the clubs that played in the first Premier League season (1992-93).","t":"Origins","e":"\ud83d\udccb","f":"Newcastle won the second tier that season and joined the Premier League for 1993-94.","o":["Leicester City","Wimbledon","Bolton Wanderers","Newcastle United","Oldham Athletic","Norwich City"],"s":{"indices":[1,4,5]}},{"k":"choice","i":"Who scored the first ever Premier League goal, in August 1992?","t":"Firsts","e":"\u26bd","f":"Deane headed it for Sheffield United in a 2\u20131 win over Manchester United.","o":["Brian Deane","Alan Shearer","Teddy Sheringham","Mark Hughes"],"s":{"index":0}},{"k":"choice","i":"Which club won the 1994-95 Premier League, its first top-flight title since 1914?","t":"Champions","e":"\ud83d\udc99","f":"They edged Manchester United by a single point on a tense final day.","o":["Newcastle United","Leeds United","Blackburn Rovers","Nottingham Forest"],"s":{"index":2}},{"k":"number","i":"Arsenal's unbeaten league run, which included the whole 2003-04 season, lasted how many matches?","t":"Invincibles","e":"\ud83d\udee1\ufe0f","f":"The run finally ended at Old Trafford in October 2004 with a 2\u20130 defeat to Manchester United.","s":{"value":49,"tolerance":0,"min":20,"max":70,"unit":"matches"}},{"k":"choice","i":"Who managed Chelsea to their first Premier League title in 2004-05?","t":"Managers","e":"\ud83e\udde5","f":"Chelsea conceded only 15 league goals that season and collected 95 points.","o":["Avram Grant","Jos\u00e9 Mourinho","Carlo Ancelotti","Guus Hiddink"],"s":{"index":1}},{"k":"text","i":"Which Italian manager guided Leicester City to the 2015-16 title?","t":"Managers","e":"\ud83e\udd8a","f":"Bookmakers had offered odds of 5,000-1 on Leicester winning the league before the season began.","s":{"accepted":["Claudio Ranieri","Ranieri"]}},{"k":"choice","i":"Which Leicester striker scored in 11 consecutive Premier League matches in 2015?","t":"Strikers","e":"\ud83d\udd25","f":"He was playing non-league football for Fleetwood Town as recently as 2012.","o":["Riyad Mahrez","Shinji Okazaki","Leonardo Ulloa","Jamie Vardy"],"s":{"index":3}},{"k":"order","i":"Order these players by the season they FIRST won the Premier League Golden Boot, from earliest to latest.","t":"Golden Boot","e":"\ud83d\udc5f","f":"Henry won the award four times, including three seasons in a row from 2003-04 to 2005-06.","o":["Alan Shearer","Michael Owen","Thierry Henry","Didier Drogba","Robin van Persie"]},{"k":"number","i":"How many points did Manchester City collect in the 2017-18 Premier League season?","t":"Champions","e":"\ud83d\udcaf","f":"Gabriel Jesus's stoppage-time winner at Southampton on the final day took them to the landmark total.","s":{"value":100,"tolerance":0,"min":75,"max":110,"unit":"points"}},{"k":"choice","i":"Sergio Ag\u00fcero's last-gasp goal that won Manchester City the 2011-12 title came against which club?","t":"Classic moments","e":"\u23f1\ufe0f","f":"City won 3\u20132 and took the title on goal difference over Manchester United.","o":["Queens Park Rangers","Sunderland","Stoke City","West Ham United"],"s":{"index":0}},{"k":"truefalse","i":"Steven Gerrard won the Premier League title with Liverpool.","t":"Legends","e":"\ud83d\udd34","f":"Liverpool's first Premier League title came in 2019-20, five years after Gerrard left Anfield.","a":false},{"k":"order","i":"Order these managers by their first Premier League title, from earliest to latest.","t":"Managers","e":"\ud83d\udcc8","f":"Wenger won the league and FA Cup double in his first full season in England, 1997-98.","o":["Alex Ferguson","Kenny Dalglish","Ars\u00e8ne Wenger","Roberto Mancini","J\u00fcrgen Klopp"]}]},{"slug":"nba-dynasties","title":"NBA Dynasty Dash","tagline":"From Russell's rings to Curry's splashes: how well do you know the NBA's great runs?","emoji":"\ud83d\udc51","gradient":["#6d28d9","#c2410c"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":311,"items":[{"k":"choice","i":"How many NBA championships did Bill Russell win as a player with the Boston Celtics?","t":"Celtics era","e":"\ud83d\udc8d","f":"Russell won his last two titles, in 1968 and 1969, while also serving as the Celtics' player-coach.","o":["8","9","11","13"],"s":{"index":2}},{"k":"multi","i":"Select all the franchises that have won at least three NBA titles in a row.","t":"Streaks","e":"\ud83d\udd01","f":"Boston's eight straight titles from 1959 to 1966 are the longest championship streak in NBA history.","o":["Boston Celtics","San Antonio Spurs","Chicago Bulls","Golden State Warriors","Miami Heat"],"s":{"indices":[0,2]}},{"k":"text","i":"Which Celtics coach famously lit a 'victory cigar' on the bench once a win was safe?","t":"Coaches","e":"\ud83d\udeac","f":"After retiring from coaching in 1966, he stayed on to run the Celtics as general manager and later team president.","s":{"accepted":["Red Auerbach","Auerbach","Arnold Auerbach","Arnold Red Auerbach"]}},{"k":"choice","i":"Which head coach led the 1980s 'Showtime' Lakers to four championships?","t":"Showtime","e":"\ud83d\udccb","f":"He later won a fifth title as a head coach with the Miami Heat in 2006.","o":["Pat Riley","Phil Jackson","Chuck Daly","Red Holzman"],"s":{"index":0}},{"k":"truefalse","i":"As a rookie, Magic Johnson was named NBA Finals MVP after starting at center in the title-clinching game.","t":"Showtime","e":"\u2728","f":"He scored 42 points in Game 6 of the 1980 Finals while Kareem Abdul-Jabbar was out injured.","a":true},{"k":"choice","i":"In the 1985 Finals, the Lakers finally beat which team after losing to them in all eight of their previous Finals meetings?","t":"Rivalries","e":"\u2694\ufe0f","f":"The Lakers clinched that series on the famous parquet floor of the Boston Garden.","o":["Philadelphia 76ers","Boston Celtics","Detroit Pistons","Houston Rockets"],"s":{"index":1}},{"k":"order","i":"Order these NBA dynasties by the year of their first championship, from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The Celtics' first title in 1957 came in Bill Russell's rookie season.","o":["Bill Russell's Celtics","The Showtime Lakers","Michael Jordan's Bulls","Tim Duncan's Spurs","Stephen Curry's Warriors"]},{"k":"number","i":"How many regular-season games did the 1995\u201396 Chicago Bulls win, an NBA record at the time?","t":"Bulls era","e":"\ud83d\udc02","f":"The 2015\u201316 Golden State Warriors went 73\u20139, but lost the Finals that season.","s":{"value":72,"tolerance":0,"min":50,"max":82,"unit":"wins"}},{"k":"multi","i":"Select all the teams the Chicago Bulls beat in the NBA Finals in the 1990s.","t":"Bulls era","e":"\ud83c\udfc6","f":"Michael Jordan was named Finals MVP in all six of those championship series.","o":["Los Angeles Lakers","Boston Celtics","Utah Jazz","New York Knicks","Phoenix Suns","Detroit Pistons"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Who was named NBA Finals MVP in 2000, 2001 and 2002 as the Lakers completed a three-peat?","t":"Lakers era","e":"\ud83c\udf1f","f":"Phil Jackson coached the Lakers to all three of those titles, and to two more in 2009 and 2010.","o":["Kobe Bryant","Derek Fisher","Robert Horry","Shaquille O'Neal"],"s":{"index":3}},{"k":"text","i":"Which coach guided the San Antonio Spurs to all five of their NBA titles, from 1999 to 2014?","t":"Coaches","e":"\ud83e\udde0","f":"He also coached the US men's team to Olympic gold at the Tokyo Games, held in 2021.","s":{"accepted":["Gregg Popovich","Popovich","Greg Popovich","Pop","Coach Pop"]}},{"k":"choice","i":"Who was named Finals MVP when the San Antonio Spurs won the 2014 NBA title?","t":"Spurs era","e":"\ud83e\udd20","f":"The Spurs beat the Miami Heat in five games, avenging their seven-game Finals defeat to Miami in 2013.","o":["Tim Duncan","Tony Parker","Manu Gin\u00f3bili","Kawhi Leonard"],"s":{"index":3}},{"k":"choice","i":"Which player was Finals MVP for the Golden State Warriors in both 2017 and 2018?","t":"Warriors era","e":"\ud83c\udf09","f":"Stephen Curry won his first Finals MVP award in 2022, when Golden State beat the Boston Celtics.","o":["Kevin Durant","Stephen Curry","Klay Thompson","Draymond Green"],"s":{"index":0}},{"k":"truefalse","i":"Steve Kerr, head coach of the Warriors' title teams, also won NBA championships as a player with Shaquille O'Neal's Lakers.","t":"Warriors era","e":"\ud83c\udfaf","f":"Kerr won five rings as a player: three with Michael Jordan's Chicago Bulls and two with the San Antonio Spurs.","a":false}]},{"slug":"grand-slam-greats","title":"Grand Slam Greats","tagline":"Calendar Slams, farewells and record runs: how well do you know tennis royalty?","emoji":"\ud83c\udfbe","gradient":["#0e7490","#1d4ed8"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":312,"items":[{"k":"choice","i":"Which Australian won the calendar-year Grand Slam in singles twice, in 1962 and 1969?","t":"Calendar Slams","e":"\ud83c\udfc6","f":"Laver's 1969 sweep came in the Open Era, when professionals and amateurs finally competed together.","o":["Ken Rosewall","Roy Emerson","John Newcombe","Rod Laver"],"s":{"index":3}},{"k":"choice","i":"In which year did tennis's Open Era begin, letting professionals play at the Grand Slams?","t":"Open Era","e":"\ud83d\udcc5","f":"The first Grand Slam of the Open Era was the 1968 French Open, won by Ken Rosewall.","o":["1959","1968","1974","1981"],"s":{"index":1}},{"k":"choice","i":"In 1988, Steffi Graf won all four majors plus the Olympic singles title. What is this feat called?","t":"Golden Moments","e":"\ud83e\udd47","f":"Tennis had just returned as a full Olympic medal sport at Seoul 1988, where Graf took the singles title.","o":["Golden Slam","Career Slam","Channel Slam","Triple Crown"],"s":{"index":0}},{"k":"multi","i":"Select all the Grand Slam singles titles Bj\u00f6rn Borg won during his career.","t":"Legends","e":"\ud83c\udfbe","f":"Borg reached four US Open finals but lost them all, and he played the Australian Open only once.","o":["French Open","Wimbledon","US Open","Australian Open"],"s":{"indices":[0,1]}},{"k":"choice","i":"Which American completed a career Grand Slam by winning the 1999 French Open?","t":"Career Slams","e":"\ud83e\uddf1","f":"He came from two sets down to beat Andrei Medvedev in the final, and his future wife Steffi Graf won the women's title that week.","o":["Jim Courier","Michael Chang","Andre Agassi","Pete Sampras"],"s":{"index":2}},{"k":"truefalse","i":"Pete Sampras won his last Grand Slam title at the 2002 US Open, beating Andre Agassi in the final.","t":"Farewells","e":"\ud83c\udfc1","f":"It turned out to be the final match of his career; he officially announced his retirement the following year.","a":true},{"k":"choice","i":"Martina Navratilova was born in which country before later becoming a US citizen?","t":"Roots","e":"\ud83c\udf0d","f":"She won 18 Grand Slam singles titles and 59 majors in total, counting women's doubles and mixed doubles.","o":["Hungary","Czechoslovakia","Poland","Yugoslavia"],"s":{"index":1}},{"k":"order","i":"Order these retired legends by Grand Slam singles titles won, from fewest to most.","t":"Title Counts","e":"\ud83d\udcca","f":"Federer's 20th and final major came at the 2018 Australian Open.","o":["Bj\u00f6rn Borg","Pete Sampras","Roger Federer","Serena Williams"]},{"k":"choice","i":"Which Grand Slam singles title did Pete Sampras never win?","t":"Legends","e":"\u2753","f":"His best run at Roland-Garros was a semi-final in 1996, while he won Wimbledon seven times.","o":["Wimbledon","US Open","Australian Open","French Open"],"s":{"index":3}},{"k":"choice","i":"In which city did Roger Federer play his farewell match, partnering Rafael Nadal at the 2022 Laver Cup?","t":"Farewells","e":"\ud83d\udc4b","f":"The doubles match at the O2 Arena ended in defeat, but it became one of tennis's most emotional nights.","o":["Basel","Geneva","London","Paris"],"s":{"index":2}},{"k":"truefalse","i":"Rafael Nadal won Olympic gold in men's singles at London 2012.","t":"Olympics","e":"\ud83e\udd47","f":"A knee injury kept him out of London 2012; his singles gold came at Beijing 2008, and he won doubles gold at Rio 2016.","a":false},{"k":"choice","i":"At which tournament did Serena Williams win her first Grand Slam singles title, in 1999?","t":"Breakthroughs","e":"\ud83d\uddfd","f":"She beat Martina Hingis in that final aged 17, and her last major came at the 2017 Australian Open.","o":["US Open","Wimbledon","Australian Open","French Open"],"s":{"index":0}},{"k":"text","i":"On which Spanish island was Rafael Nadal born and raised?","t":"Roots","e":"\ud83c\udfdd\ufe0f","f":"His hometown of Manacor is also home to the Rafa Nadal Academy, which opened in 2016.","s":{"accepted":["Mallorca","Majorca"]}},{"k":"order","i":"Order these players by the year of their first Grand Slam singles title, from earliest to latest.","t":"Breakthroughs","e":"\ud83d\udd70\ufe0f","f":"Federer's first major came at Wimbledon in 2003, about a month before his 22nd birthday.","o":["Rod Laver","Bj\u00f6rn Borg","Martina Navratilova","Steffi Graf","Roger Federer"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'f76935a24fffc4d1f3426ac818208d3f' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 1'; end $q$;
do $q$ declare d text := $d$[{"slug":"formula-one-history","title":"F1 Flashback","tagline":"Fangio, Senna, Schumacher and more: race through Formula One's glorious past.","emoji":"\ud83c\udfce\ufe0f","gradient":["#dc2626","#7f1d1d"],"categories":["sports","cars"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":313,"items":[{"k":"choice","i":"Which Italian driver won the very first World Championship race, at Silverstone in 1950, and went on to take that year's title?","t":"Origins","e":"\ud83c\udfc1","f":"King George VI and Queen Elizabeth were among the crowd at that first championship race on 13 May 1950.","o":["Giuseppe Farina","Alberto Ascari","Luigi Fagioli","Luigi Villoresi"],"s":{"index":0}},{"k":"text","i":"Which Argentine driver dominated the 1950s, winning world titles with Alfa Romeo, Mercedes, Ferrari and Maserati?","t":"Legends","e":"\ud83c\udfce\ufe0f","f":"He was already 40 years old when he won the first of his championships in 1951.","s":{"accepted":["Fangio","Juan Manuel Fangio","Juan Fangio"]}},{"k":"choice","i":"Which Scottish driver won his first world title with Lotus in 1963?","t":"Legends","e":"\ud83c\udfc6","f":"Clark also won the 1965 Indianapolis 500, driving a rear-engined Lotus.","o":["Jackie Stewart","Jim Clark","Graham Hill","John Surtees"],"s":{"index":1}},{"k":"choice","i":"Which Brazilian driver won his first world title in 1988, driving for McLaren?","t":"Legends","e":"\ud83c\udfce\ufe0f","f":"He won the Monaco Grand Prix six times, including five in a row from 1989 to 1993.","o":["Nelson Piquet","Emerson Fittipaldi","Ayrton Senna","Rubens Barrichello"],"s":{"index":2}},{"k":"text","i":"Which French driver, nicknamed 'The Professor', won world titles with both McLaren and Williams?","t":"Rivals","e":"\ud83e\udde0","f":"He retired at the end of 1993, bowing out as reigning champion after his final title with Williams.","s":{"accepted":["Prost","Alain Prost"]}},{"k":"number","i":"How many Formula One world titles did Michael Schumacher win?","t":"Champions","e":"\ud83c\udfc6","f":"He won two titles with Benetton, then five in a row with Ferrari from 2000 to 2004.","s":{"value":7,"tolerance":0,"min":1,"max":15,"unit":"titles"}},{"k":"choice","i":"Which flag warns a driver that a faster car is about to lap them?","t":"Flags","e":"\ud83d\udea9","f":"The most famous flag of all, the black-and-white chequered flag, is waved as the winner crosses the line.","o":["Yellow flag","White flag","Green flag","Blue flag"],"s":{"index":3}},{"k":"truefalse","i":"Refuelling during races has been banned in Formula One since the 2010 season.","t":"Pit stops","e":"\u26fd","f":"With no fuel to add, a pit stop is mostly a tyre change, which top crews can finish in two to three seconds.","a":true},{"k":"choice","i":"Which British driver won the Monaco Grand Prix five times in the 1960s and was nicknamed 'Mr Monaco'?","t":"Monaco","e":"\ud83d\udc51","f":"He also won the 1966 Indianapolis 500 and the 1972 24 Hours of Le Mans, motorsport's unofficial Triple Crown.","o":["Graham Hill","Stirling Moss","Jackie Stewart","John Surtees"],"s":{"index":0}},{"k":"order","i":"Order these drivers by their number of Formula One world titles, from fewest to most.","t":"Champions","e":"\ud83d\udd22","f":"Vettel won his titles in four straight seasons with Red Bull, from 2010 to 2013.","o":["James Hunt","Mika H\u00e4kkinen","Jackie Stewart","Sebastian Vettel"]},{"k":"order","i":"Order these drivers by the year they won their first world title, from earliest to latest.","t":"Champions","e":"\ud83d\udcc5","f":"Fittipaldi was 25 when he won in 1972, the youngest champion in F1 history at the time.","o":["Alberto Ascari","Jack Brabham","Emerson Fittipaldi","Nigel Mansell"]},{"k":"multi","i":"Select all the drivers who won a Formula One world title with Ferrari.","t":"Teams","e":"\ud83d\udc0e","f":"Kimi R\u00e4ikk\u00f6nen's 2007 title was decided by a single point over two McLaren drivers.","o":["Niki Lauda","Nelson Piquet","Alberto Ascari","Mika H\u00e4kkinen","Kimi R\u00e4ikk\u00f6nen","Jackie Stewart"],"s":{"indices":[0,2,4]}},{"k":"truefalse","i":"James Hunt returned to racing only about six weeks after suffering serious burns in a crash at the N\u00fcrburgring in 1976.","t":"Comebacks","e":"\ud83d\udd25","f":"It was Niki Lauda; he missed just two races, and Hunt pipped him to the 1976 title by a single point.","a":false},{"k":"choice","i":"Which team has taken part in every Formula One World Championship season since it began in 1950?","t":"Teams","e":"\ud83c\udfc1","f":"Ferrari skipped the very first championship race at Silverstone and made its debut at Monaco eight days later.","o":["McLaren","Ferrari","Williams","Lotus"],"s":{"index":1}}]},{"slug":"olympic-host-cities","title":"Summer Olympics City Tour","tagline":"From Athens 1896 to Brisbane 2032: follow the Summer Games around the globe.","emoji":"\ud83c\udfdf\ufe0f","gradient":["#0284c7","#c026d3"],"categories":["olympics","sports","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":314,"items":[{"k":"choice","i":"Which city hosted the 1900 Summer Olympics, held as part of a World's Fair?","t":"Early Games","e":"\ud83d\uddfc","f":"Tennis player Charlotte Cooper became the first individual female Olympic champion at these Games.","o":["London","St. Louis","Athens","Paris"],"s":{"index":3}},{"k":"choice","i":"The 1908 Summer Olympics were originally awarded to which city before moving to London?","t":"Early Games","e":"\ud83c\udf0b","f":"Italy withdrew, citing the cost of rebuilding after the 1906 eruption of Mount Vesuvius, and London stepped in at short notice.","o":["Rome","Berlin","Stockholm","Amsterdam"],"s":{"index":0}},{"k":"choice","i":"Which city hosted the 1968 Summer Olympics, the first Games held in Latin America?","t":"Firsts","e":"\ud83c\udfd4\ufe0f","f":"At about 2,240 m above sea level, its thin air helped athletes set a string of records in the sprints and jumps.","o":["Buenos Aires","Mexico City","S\u00e3o Paulo","Havana"],"s":{"index":1}},{"k":"text","i":"Which Belgian port city hosted the 1920 Summer Olympics?","t":"Early Games","e":"\ud83c\udde7\ud83c\uddea","f":"The Olympic flag with its five rings flew at a Games for the first time, and athletes took the Olympic oath for the first time.","s":{"accepted":["Antwerp","Antwerpen","Anvers"]}},{"k":"choice","i":"Which city hosted the 2000 Summer Olympics, where Cathy Freeman lit the cauldron and later won 400 m gold?","t":"Opening ceremonies","e":"\ud83d\udd25","f":"These Games were the first to include triathlon and taekwondo as full medal sports.","o":["Melbourne","Brisbane","Sydney","Auckland"],"s":{"index":2}},{"k":"choice","i":"What is the nickname of Beijing's National Stadium, the woven-steel centrepiece of the 2008 Olympics?","t":"Venues","e":"\ud83c\udfdf\ufe0f","f":"The Games opened on 8 August 2008 at 8:08 pm, because eight is a lucky number in Chinese culture.","o":["Water Cube","Dragon's Eye","Lotus Bowl","Bird's Nest"],"s":{"index":3}},{"k":"truefalse","i":"Beijing is the first city to have hosted both the Summer and the Winter Olympics.","t":"Host cities","e":"\u2744\ufe0f","f":"Beijing held the Summer Games in 2008 and the Winter Games in 2022, turning its swimming venue into a curling arena.","a":true},{"k":"choice","i":"Rio 2016, the first Summer Games in South America, held its opening ceremony in which famous stadium?","t":"Venues","e":"\u26bd","f":"The same stadium hosted the deciding match of the 1950 World Cup and the 2014 World Cup final.","o":["Maracan\u00e3","Morumbi","Mineir\u00e3o","Arena Corinthians"],"s":{"index":0}},{"k":"choice","i":"Which US city has been awarded the 2028 Summer Olympics?","t":"Future hosts","e":"\ud83d\uddd3\ufe0f","f":"It will be the city's third Games after 1932 and 1984; the 2024 and 2028 hosts were confirmed together in 2017.","o":["New York","Los Angeles","Chicago","Boston"],"s":{"index":1}},{"k":"text","i":"Which Australian city was awarded the 2032 Summer Olympics?","t":"Future hosts","e":"\ud83e\udd98","f":"Brisbane was confirmed as host in 2021, at an IOC Session held in Tokyo.","s":{"accepted":["Brisbane"]}},{"k":"order","i":"Order these Summer Olympic host cities from earliest to latest Games.","t":"Timeline","e":"\u23f3","f":"Amsterdam 1928 was the first Summer Games where an Olympic flame burned throughout.","o":["Amsterdam","Helsinki","Rome","Munich","Seoul"]},{"k":"number","i":"In what year did the Summer Olympics return to Athens, more than a century after the 1896 Games?","t":"Comebacks","e":"\ud83c\udfdb\ufe0f","f":"The 2004 shot put contests were held in the ancient stadium at Olympia, birthplace of the original Games.","s":{"value":2004,"tolerance":0,"min":1976,"max":2020,"unit":""}},{"k":"multi","i":"Select all the Summer Olympic host cities in the Southern Hemisphere.","t":"Geography","e":"\ud83c\udf0f","f":"Melbourne 1956 was the first Southern Hemisphere Games; its horse events took place in Stockholm due to quarantine rules.","o":["Melbourne","Mexico City","Rio de Janeiro","Seoul","Sydney"],"s":{"indices":[0,2,4]}},{"k":"truefalse","i":"After being postponed by a year, the Tokyo Olympics were renamed 'Tokyo 2021'.","t":"Host cities","e":"\ud83d\udcc5","f":"They were held in 2021 but kept the name 'Tokyo 2020'; they were the first Olympics ever postponed rather than cancelled.","a":false}]},{"slug":"magyar-sports-heroes","title":"Magyar Sporting Heroes","tagline":"From the Golden Team to the Iron Lady: how well do you know Hungary's champions?","emoji":"\ud83c\udded\ud83c\uddfa","gradient":["#b91c1c","#15803d"],"categories":["sports","history"],"countries":["HU"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":315,"items":[{"k":"choice","i":"By what score did Hungary's 'Golden Team' beat England at Wembley in November 1953?","t":"Golden Team","e":"\u26bd","f":"It was England's first home defeat by a team from outside the British Isles, and Hungary won the 1954 rematch in Budapest 7\u20131.","o":["6\u20133","4\u20132","3\u20131","5\u20134"],"s":{"index":0}},{"k":"text","i":"FIFA's yearly award for the most beautiful goal is named after which Hungarian striker?","t":"Awards","e":"\ud83c\udfc6","f":"First presented in 2009, the award honours a forward who scored 84 goals in 85 matches for Hungary.","s":{"accepted":["Pusk\u00e1s","Puskas","Ferenc Pusk\u00e1s","Ferenc Puskas","Pusk\u00e1s Ferenc","Puskas Ferenc"]}},{"k":"number","i":"How many Olympic gold medals had Hungary's men's water polo team won by 2024?","t":"Water polo","e":"\ud83e\udd3d","f":"Their first title came at Los Angeles 1932 and their most recent at Beijing 2008.","s":{"value":9,"tolerance":0,"min":0,"max":15,"unit":"golds"}},{"k":"truefalse","i":"Hungary's Golden Team won the 1954 World Cup in Switzerland.","t":"World Cup","e":"\ud83c\udfdf\ufe0f","f":"Despite beating West Germany 8\u20133 in the group stage, Hungary lost the final 3\u20132 to them in Bern.","a":false},{"k":"choice","i":"Who became the first boxer to win three Olympic gold medals, at the 1948, 1952 and 1956 Games?","t":"Boxing","e":"\ud83e\udd4a","f":"Papp took middleweight gold in London, then light-middleweight titles in Helsinki and Melbourne.","o":["Te\u00f3filo Stevenson","L\u00e1szl\u00f3 Papp","Floyd Patterson","F\u00e9lix Sav\u00f3n"],"s":{"index":1}},{"k":"truefalse","i":"Fencing great Alad\u00e1r Gerevich won his Olympic gold medals with the \u00e9p\u00e9e.","t":"Fencing","e":"\ud83e\udd3a","f":"Gerevich was a sabre fencer and won team gold at six different Olympics, from 1932 to 1960.","a":false},{"k":"choice","i":"Krisztina Egerszegi won three straight Olympic titles in the 200 m of which stroke?","t":"Swimming","e":"\ud83c\udfca","f":"She won her first Olympic gold at Seoul 1988 aged just 14, and was nicknamed 'Eg\u00e9rke', the little mouse.","o":["Butterfly","Breaststroke","Backstroke","Freestyle"],"s":{"index":2}},{"k":"choice","i":"Katinka Hossz\u00fa, a triple gold medallist at Rio 2016, was known by which nickname?","t":"Nicknames","e":"\ud83d\udcaa","f":"She earned the name by racing an unusually heavy schedule, often swimming several finals in one session.","o":["The Thorpedo","Madame Butterfly","The Albatross","The Iron Lady"],"s":{"index":3}},{"k":"multi","i":"Select all the events Katinka Hossz\u00fa won at the Rio 2016 Olympics.","t":"Rio 2016","e":"\ud83e\udd47","f":"She also took silver in the 200 m backstroke, and set a world record in the 400 m medley final.","o":["400 m individual medley","200 m butterfly","100 m backstroke","200 m individual medley","100 m freestyle"],"s":{"indices":[0,2,3]}},{"k":"choice","i":"Alfr\u00e9d Haj\u00f3s, Hungary's first Olympic champion, won his golds at Athens 1896 in which sport?","t":"Olympic history","e":"\ud83c\udfdb\ufe0f","f":"Haj\u00f3s was also an architect, and won an Olympic silver medal in the 1924 art competitions for a stadium design.","o":["Fencing","Athletics","Swimming","Wrestling"],"s":{"index":2}},{"k":"choice","i":"The Hungaroring, home of the Hungarian Grand Prix since 1986, lies just outside which city?","t":"Formula One","e":"\ud83c\udfce\ufe0f","f":"Won by Nelson Piquet, the 1986 race was the first Formula One Grand Prix held behind the Iron Curtain.","o":["Budapest","Debrecen","Szeged","Gy\u0151r"],"s":{"index":0}},{"k":"choice","i":"Hungarian gymnast Zolt\u00e1n Magyar, Olympic champion in 1976 and 1980, has two moves named after him on which apparatus?","t":"Gymnastics","e":"\ud83e\udd38","f":"Known as the 'Magyar travel' and the 'Magyar spindle', they helped him win Olympic gold in both Montreal and Moscow.","o":["Rings","Pommel horse","Parallel bars","Horizontal bar"],"s":{"index":1}},{"k":"truefalse","i":"Hungary's men's water polo team won three Olympic titles in a row, in 2000, 2004 and 2008.","t":"Water polo","e":"\ud83c\udf0a","f":"The hat-trick was masterminded by coach D\u00e9nes Kem\u00e9ny, with stars such as Tibor Benedek in the pool.","a":true},{"k":"order","i":"Order these Hungarian sporting moments from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Haj\u00f3s won in 1896, Gerevich in 1932, the Golden Team triumphed in 1953 and Egerszegi struck gold in 1988.","o":["Alfr\u00e9d Haj\u00f3s wins Hungary's first Olympic gold","Alad\u00e1r Gerevich wins his first Olympic gold","The Golden Team beats England at Wembley","Krisztina Egerszegi wins her first Olympic gold"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'f6e7b57e3998b3fd54b9d23ad78d3173' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 2'; end $q$;
do $q$ declare d text := $d$[{"slug":"champions-league-nights","title":"Champions League Nights","tagline":"Big finals, bigger comebacks and a famous anthem: the story of Europe's elite club cup.","emoji":"\u2b50","gradient":["#1e3a8a","#0891b2"],"categories":["football","sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":316,"items":[{"k":"number","i":"In what year was the first European Cup final played?","t":"Origins","e":"\ud83d\udcc5","f":"The final was played at the Parc des Princes in Paris, with French side Stade de Reims the beaten finalists.","s":{"value":1956,"tolerance":0,"min":1930,"max":1975,"unit":""}},{"k":"choice","i":"Which club won each of the first five European Cups?","t":"Dynasties","e":"\ud83d\udc51","f":"Their star Alfredo Di St\u00e9fano scored in all five of those finals.","o":["Benfica","AC Milan","Barcelona","Real Madrid"],"s":{"index":3}},{"k":"truefalse","i":"The European Cup was rebranded as the UEFA Champions League in 1992.","t":"Origins","e":"\ud83d\udd04","f":"The rebrand brought the famous starball logo and a specially composed anthem.","a":true},{"k":"choice","i":"Which club won the first final played under the 'Champions League' name, in 1993?","t":"Firsts","e":"\ud83d\udd35","f":"Basile Boli's header beat AC Milan 1\u20130 in the final in Munich.","o":["Marseille","AC Milan","Ajax","Barcelona"],"s":{"index":0}},{"k":"choice","i":"In the 2005 final in Istanbul, Liverpool came back from 3\u20130 down at half-time against which club?","t":"Classic finals","e":"\ud83d\udd25","f":"Liverpool levelled 3\u20133 with three goals in six minutes, then won the shoot-out 3\u20132.","o":["Juventus","AC Milan","Inter Milan","Chelsea"],"s":{"index":1}},{"k":"number","i":"How many penalties did Steaua Bucharest goalkeeper Helmuth Duckadam save in the 1986 final shoot-out?","t":"Classic finals","e":"\ud83e\udde4","f":"Barcelona failed to score a single spot-kick, and Steaua became the first Eastern European champions.","s":{"value":4,"tolerance":0,"min":0,"max":6,"unit":"penalties"}},{"k":"text","i":"The Champions League anthem is adapted from 'Zadok the Priest', written by which composer?","t":"Anthem","e":"\ud83c\udfbc","f":"Tony Britten arranged the anthem in 1992, and its lyrics mix English, French and German.","s":{"accepted":["Handel","George Frideric Handel","George Frederick Handel","Georg Friedrich Handel","Georg Friedrich H\u00e4ndel","H\u00e4ndel","Haendel"]}},{"k":"text","i":"The Champions League trophy is famous for its huge handles. What is its popular English nickname?","t":"Trophy","e":"\ud83c\udfc6","f":"In Spanish it is known as 'La Orejona', meaning 'the big-eared one'.","s":{"accepted":["Big Ears","Old Big Ears","The Big Ears","Big Ear"]}},{"k":"choice","i":"Manchester United scored twice in stoppage time to win the 1999 final against which club?","t":"Classic finals","e":"\u23f1\ufe0f","f":"Teddy Sheringham and Ole Gunnar Solskj\u00e6r struck at Camp Nou to complete a historic treble.","o":["Juventus","Borussia Dortmund","Bayern Munich","Valencia"],"s":{"index":2}},{"k":"choice","i":"In 1967, which club became the first from Britain to win the European Cup?","t":"Firsts","e":"\ud83c\udf40","f":"The 'Lisbon Lions' beat Inter Milan 2\u20131 in the Portuguese capital.","o":["Manchester United","Liverpool","Rangers","Celtic"],"s":{"index":3}},{"k":"multi","i":"Select all the clubs that won the European Cup three years in a row at some point between 1956 and 2024.","t":"Dynasties","e":"\ud83d\udd01","f":"Ajax did it from 1971 to 1973, and Bayern Munich followed straight after, from 1974 to 1976.","o":["Ajax","Liverpool","Bayern Munich","Real Madrid","AC Milan","Nottingham Forest"],"s":{"indices":[0,2,3]}},{"k":"order","i":"Order these clubs by their FIRST European Cup win, from earliest to latest.","t":"Firsts","e":"\ud83d\udcc8","f":"Barcelona's first came at Wembley in 1992, thanks to a Ronald Koeman free kick in extra time.","o":["Benfica","Ajax","Nottingham Forest","Barcelona","Chelsea"]},{"k":"truefalse","i":"Aston Villa won the European Cup in two consecutive seasons.","t":"Underdogs","e":"\ud83c\udf32","f":"Villa won it once, in 1982; their Midlands neighbours Nottingham Forest were the ones to win it back to back, in 1979 and 1980.","a":false},{"k":"choice","i":"Who scored a spectacular bicycle kick in the 2018 final against Liverpool in Kyiv?","t":"Classic finals","e":"\ud83d\udeb2","f":"He came off the bench and scored twice in a 3\u20131 win.","o":["Gareth Bale","Cristiano Ronaldo","Karim Benzema","Luka Modri\u0107"],"s":{"index":0}}]},{"slug":"hoops-hall-of-fame","title":"Hoops Hall of Fame","tagline":"Dream Teams, legendary rivalries and record nights: meet basketball's retired greats.","emoji":"\ud83c\udfc0","gradient":["#ea580c","#9f1239"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":317,"items":[{"k":"number","i":"How many points did Wilt Chamberlain score in a single NBA game on March 2, 1962?","t":"Record nights","e":"\ud83d\udcaf","f":"His Philadelphia Warriors beat the New York Knicks 169\u2013147 in Hershey, Pennsylvania.","s":{"value":100,"tolerance":0,"min":50,"max":120,"unit":"points"}},{"k":"truefalse","i":"Wilt Chamberlain once averaged more than 50 points per game over a full NBA season.","t":"Legends","e":"\ud83d\udcc8","f":"In 1961\u201362 he averaged 50.4 points and, thanks to overtime games, more than 48 minutes per game.","a":true},{"k":"choice","i":"Which signature shot made Kareem Abdul-Jabbar almost impossible to block?","t":"Signature moves","e":"\ud83e\ude9d","f":"Kareem won six NBA MVP awards, more than Michael Jordan or Bill Russell, who won five each.","o":["The fadeaway","The skyhook","The finger roll","The floater"],"s":{"index":1}},{"k":"text","i":"Kareem Abdul-Jabbar played his early career under which birth name?","t":"Legends","e":"\ud83d\udcdb","f":"He began using the name Kareem Abdul-Jabbar in 1971, the year he won his first NBA title with Milwaukee.","s":{"accepted":["Lew Alcindor","Alcindor","Lewis Alcindor","Ferdinand Lewis Alcindor","Lew Alcindor Jr"]}},{"k":"choice","i":"Magic Johnson and Larry Bird first met in the 1979 college championship game. Which university did Magic play for?","t":"Rivalries","e":"\ud83c\udf93","f":"Magic's team beat Larry Bird's Indiana State, which had gone unbeaten all season until that final.","o":["Indiana State","UCLA","Michigan State","North Carolina"],"s":{"index":2}},{"k":"truefalse","i":"Larry Bird won four NBA MVP awards in a row in the 1980s.","t":"Legends","e":"\ud83c\udfc5","f":"He won three in a row, from 1984 to 1986; only Bill Russell and Wilt Chamberlain had won it three seasons running before him.","a":false},{"k":"choice","i":"Which of these nicknames belonged to Larry Bird?","t":"Nicknames","e":"\ud83e\udd85","f":"Bird grew up in French Lick, Indiana, and was also called 'Larry Legend'. The other nicknames belonged to Karl Malone, David Robinson and Gary Payton.","o":["The Mailman","The Admiral","The Glove","The Hick from French Lick"],"s":{"index":3}},{"k":"number","i":"How many points did Kobe Bryant score against the Toronto Raptors on January 22, 2006?","t":"Record nights","e":"\ud83d\udd25","f":"Kobe scored 55 of his points in the second half as the Lakers came from behind to win 122\u2013104.","s":{"value":81,"tolerance":0,"min":40,"max":110,"unit":"points"}},{"k":"multi","i":"Select all the jersey numbers the Los Angeles Lakers retired in honour of Kobe Bryant.","t":"Jerseys","e":"\ud83d\udc55","f":"The Lakers retired both of Kobe's numbers on the same night in December 2017.","o":["8","23","24","32","33","34"],"s":{"indices":[0,2]}},{"k":"choice","i":"Which team drafted Shaquille O'Neal with the first overall pick in 1992?","t":"Draft day","e":"\ud83d\udcdd","f":"Shaq won four NBA titles: three with the Lakers and one with the Miami Heat in 2006.","o":["Orlando Magic","Los Angeles Lakers","Miami Heat","Phoenix Suns"],"s":{"index":0}},{"k":"choice","i":"Which city hosted the Olympics where the original 'Dream Team' of NBA stars won gold?","t":"Dream Team","e":"\ud83e\udd47","f":"Those Games were the first Olympics where NBA players were allowed to compete.","o":["Atlanta","Barcelona","Seoul","Los Angeles"],"s":{"index":1}},{"k":"multi","i":"Select all the players who were on the original 'Dream Team' that won Olympic gold.","t":"Dream Team","e":"\ud83c\uddfa\ud83c\uddf8","f":"Christian Laettner of Duke was the only college player on the 12-man roster.","o":["Michael Jordan","Shaquille O'Neal","Larry Bird","Isiah Thomas","Charles Barkley","Kobe Bryant"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Hakeem Olajuwon, who led Houston to back-to-back NBA titles in 1994 and 1995, was born in which country?","t":"Roots","e":"\ud83c\udf0d","f":"Houston picked him first overall in the 1984 NBA Draft, two places ahead of Michael Jordan, who went third to Chicago.","o":["Cameroon","Senegal","Nigeria","Ghana"],"s":{"index":2}},{"k":"order","i":"Order these legends by the year they retired from the NBA, from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Kobe's final game in April 2016 ended with a 60-point performance against the Utah Jazz.","o":["Wilt Chamberlain","Kareem Abdul-Jabbar","Larry Bird","Shaquille O'Neal","Kobe Bryant"]}]},{"slug":"wimbledon-whites","title":"Wimbledon Whites","tagline":"Traditions, trophies and the stories behind tennis's most famous fortnight.","emoji":"\ud83c\udf53","gradient":["#6d28d9","#15803d"],"categories":["sports","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":318,"items":[{"k":"number","i":"In what year were the first Wimbledon Championships held?","t":"Origins","e":"\ud83d\udcdc","f":"Only men's singles was contested that first year, and Spencer Gore took the title.","s":{"value":1877,"tolerance":0,"min":1850,"max":1920,"unit":""}},{"k":"choice","i":"Which fruit, served with cream, is Wimbledon's signature snack?","t":"Traditions","e":"\ud83c\udf53","f":"The fruit served at Wimbledon is traditionally English-grown, much of it from farms in Kent.","o":["Raspberries","Cherries","Blueberries","Strawberries"],"s":{"index":3}},{"k":"number","i":"In what year was Centre Court's retractable roof first used during the Championships?","t":"Centre Court","e":"\u2614","f":"No. 1 Court got a retractable roof of its own in time for the 2019 Championships.","s":{"value":2009,"tolerance":0,"min":1995,"max":2020,"unit":""}},{"k":"choice","i":"What is the name of the silver salver presented to the women's singles champion?","t":"Trophies","e":"\ud83c\udfc6","f":"Champions receive a smaller replica to keep, while the original stays at the All England Club.","o":["Juno Silver Platter","Venus Rosewater Dish","Minerva Gilt Tray","Diana Crystal Bowl"],"s":{"index":1}},{"k":"choice","i":"Which Swede won five Wimbledon men's singles titles in a row, from 1976 to 1980?","t":"Legends","e":"\ud83d\udd25","f":"His streak ended in the 1981 final, when John McEnroe beat him in four sets.","o":["Bj\u00f6rn Borg","Stefan Edberg","Mats Wilander","Magnus Norman"],"s":{"index":0}},{"k":"truefalse","i":"Before 2022, there had never been any play on Wimbledon's Middle Sunday.","t":"Traditions","e":"\ud83d\udcc6","f":"Rain backlogs forced Middle Sunday play in 1991, 1997, 2004 and 2016; since 2022 it has been a scheduled day of play.","a":false},{"k":"choice","i":"Who won nine Wimbledon singles titles, including six in a row from 1982 to 1987?","t":"Legends","e":"\ud83d\udc51","f":"Her ninth and final Wimbledon singles title came in 1990, when she was 33.","o":["Chris Evert","Steffi Graf","Martina Navratilova","Billie Jean King"],"s":{"index":2}},{"k":"choice","i":"What is the name of Centre Court's exclusive seating area for invited dignitaries and guests of the club?","t":"Centre Court","e":"\ud83c\udfa9","f":"Since 2003, players only bow or curtsy towards it if the monarch or the Prince of Wales is present.","o":["Crown Stand","Members' Balcony","President's Gallery","Royal Box"],"s":{"index":3}},{"k":"choice","i":"Which brand began supplying the official Wimbledon balls in 1902?","t":"Equipment","e":"\ud83c\udfbe","f":"Wimbledon balls were white until 1986, when yellow balls arrived to show up better on TV.","o":["Slazenger","Dunlop","Wilson","Penn"],"s":{"index":0}},{"k":"text","i":"What nickname is given to the grassy slope where fans watch matches on a giant screen, named after a British player?","t":"Fan Zone","e":"\u26f0\ufe0f","f":"Its official name is the Aorangi Terrace, and some fans renamed it 'Murray Mound' during Andy Murray's career.","s":{"accepted":["Henman Hill","Murray Mound","Murray Mount","Aorangi Terrace","Henman","Mount Murray"]}},{"k":"truefalse","i":"Centre Court got its name because the main court at the club's original Worple Road ground sat in the middle of the other courts.","t":"Centre Court","e":"\ud83c\udfdf\ufe0f","f":"The name stuck when the club moved to Church Road in 1922, even though the court was not central there at first.","a":true},{"k":"order","i":"Order these Wimbledon milestones from earliest to latest.","t":"Milestones","e":"\u23f3","f":"Hawk-Eye arrived at Wimbledon in 2007, on Centre Court and No. 1 Court.","o":["First Championships held","First ladies' singles event","Move to Church Road","First Open Era Championships","Hawk-Eye line calls introduced"]},{"k":"choice","i":"Which club, founded in 1868 as a croquet club, hosts the Championships?","t":"The Club","e":"\ud83c\udfdb\ufe0f","f":"It added lawn tennis in 1875 and still keeps croquet in its full official name.","o":["Queen's Club","All England Club","Hurlingham Club","Roehampton Club"],"s":{"index":1}},{"k":"multi","i":"Select all the British players who won a Wimbledon singles title between 1970 and 2024.","t":"Home Heroes","e":"\ud83c\uddec\ud83c\udde7","f":"Wade won in 1977, the centenary year, and Murray ended a 77-year wait for a British men's champion in 2013.","o":["Virginia Wade","Tim Henman","Andy Murray","Greg Rusedski","Sue Barker"],"s":{"indices":[0,2]}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'e3d0c4419107f5f6f9ff2b3fa41a85f1' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 3'; end $q$;
do $q$ declare d text := $d$[{"slug":"grand-prix-circuits","title":"Grand Prix Track Day","tagline":"Tunnels, hairpins and legendary corners: how well do you know F1's great tracks?","emoji":"\ud83c\udfc1","gradient":["#059669","#1e3a8a"],"categories":["sports","cars","travel"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":319,"items":[{"k":"choice","i":"Which circuit is nicknamed 'The Temple of Speed'?","t":"Nicknames","e":"\u26a1","f":"Its old banked oval, last used for the Italian Grand Prix in 1961, still stands in the park today.","o":["Spa-Francorchamps","Monza","Silverstone","Hockenheim"],"s":{"index":1}},{"k":"text","i":"In which country is the Spa-Francorchamps circuit?","t":"Geography","e":"\ud83c\udf27\ufe0f","f":"Spa's weather is famously fickle: it can be raining on one part of the lap while another stays dry.","s":{"accepted":["Belgium","Belgique","Belgi\u00eb","Belgie"]}},{"k":"choice","i":"Which famous Spa-Francorchamps corner sends cars plunging into a dip just before the steep climb up Raidillon?","t":"Famous corners","e":"\u26f0\ufe0f","f":"It takes its name, meaning 'red water', from the iron-tinted stream that flows beneath the track there.","o":["Becketts","Tamburello","Eau Rouge","Casino Square"],"s":{"index":2}},{"k":"choice","i":"Monaco's famous tunnel section runs underneath what kind of building?","t":"Monaco","e":"\ud83d\ude87","f":"The hairpin beside that same building is so tight that cars slow to around 50 km/h to get round it.","o":["A casino","The royal palace","A football stadium","A hotel"],"s":{"index":3}},{"k":"number","i":"In what year did the Hungaroring, near Budapest, host its first Formula One Grand Prix?","t":"Hungary","e":"\ud83c\udded\ud83c\uddfa","f":"Nelson Piquet won that first Hungarian Grand Prix after a famous sliding pass on Ayrton Senna.","s":{"value":1986,"tolerance":0,"min":1970,"max":2010,"unit":""}},{"k":"choice","i":"Which circuit has a figure-of-eight layout, with a bridge where the track crosses over itself?","t":"Layouts","e":"\u267e\ufe0f","f":"It was designed as a Honda test track and opened in 1962.","o":["Suzuka","Interlagos","Silverstone","Hungaroring"],"s":{"index":0}},{"k":"choice","i":"In which Brazilian city is the Interlagos circuit?","t":"Geography","e":"\ud83c\udf0e","f":"Its official name, Aut\u00f3dromo Jos\u00e9 Carlos Pace, honours a local driver who won there in 1975.","o":["Rio de Janeiro","S\u00e3o Paulo","Bras\u00edlia","Belo Horizonte"],"s":{"index":1}},{"k":"choice","i":"What nickname did Jackie Stewart give the N\u00fcrburgring's Nordschleife?","t":"Nicknames","e":"\ud83c\udf32","f":"The full Nordschleife loop is about 20.8 km long, roughly four times a typical modern Grand Prix lap.","o":["The Cathedral of Speed","The Brickyard","The Green Hell","The Corkscrew"],"s":{"index":2}},{"k":"choice","i":"Before it became a racing circuit, what was Silverstone during the Second World War?","t":"History","e":"\ud83c\uddec\ud83c\udde7","f":"Silverstone held its first Grand Prix in 1948, two years before the world championship began.","o":["A horse racing course","A car factory","A royal hunting estate","An RAF airfield"],"s":{"index":3}},{"k":"truefalse","i":"The Monaco Grand Prix is the longest race on the F1 calendar by distance.","t":"Monaco","e":"\ud83d\udccf","f":"At about 260 km, Monaco is the exception to F1's usual minimum race distance of roughly 305 km.","a":false},{"k":"truefalse","i":"The Hungaroring is in the town of Mogyor\u00f3d, just outside Budapest.","t":"Hungary","e":"\ud83d\udccd","f":"Its tight, twisty layout is often described as 'Monaco without the walls', which makes overtaking tricky.","a":true},{"k":"order","i":"Order these circuits by the year they first hosted a World Championship Grand Prix, from earliest to latest.","t":"Debuts","e":"\ud83d\udcc5","f":"Singapore's Marina Bay staged Formula One's first ever night race in 2008.","o":["Monaco","Interlagos","Suzuka","Marina Bay (Singapore)","Circuit of the Americas"]},{"k":"multi","i":"Select all the circuits in Italy that have hosted a Formula One World Championship race.","t":"Italy","e":"\ud83c\uddee\ud83c\uddf9","f":"Imola's official name honours Enzo Ferrari and his son Dino.","o":["Zandvoort","Imola","Hockenheim","Mugello","Magny-Cours","Pescara"],"s":{"indices":[1,3,5]}},{"k":"multi","i":"Select all the street circuits laid out on public roads.","t":"Street circuits","e":"\ud83c\udfd9\ufe0f","f":"Baku's track squeezes past the walls of the Old City before a long flat-out run along the seafront.","o":["Silverstone","Monaco","Marina Bay","Suzuka","Baku City Circuit","Hungaroring"],"s":{"indices":[1,2,4]}}]},{"slug":"winter-olympics-wonders","title":"Winter Olympics Wonders","tagline":"Bobsleighs, ski jumps and snowy firsts from Chamonix 1924 onwards.","emoji":"\u26f7\ufe0f","gradient":["#0891b2","#1e3a8a"],"categories":["olympics","sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":320,"items":[{"k":"choice","i":"Which French town hosted the very first Winter Olympics in 1924?","t":"Firsts","e":"\ud83c\udfd4\ufe0f","f":"The event was billed as an 'International Winter Sports Week' and only later recognised as the first Winter Games.","o":["Grenoble","Chamonix","Albertville","Val d'Is\u00e8re"],"s":{"index":1}},{"k":"number","i":"In what year did Sapporo host the first Winter Olympics held in Asia?","t":"Firsts","e":"\ud83d\uddfe","f":"Japanese ski jumpers swept gold, silver and bronze on the normal hill at those Games.","s":{"value":1972,"tolerance":0,"min":1948,"max":2002,"unit":""}},{"k":"choice","i":"Jamaica's famous bobsleigh team made its Olympic debut at the 1988 Winter Games in which city?","t":"Legends","e":"\ud83d\udef7","f":"The team crashed in the four-man event, then walked beside their sled to the finish line to huge cheers.","o":["Sarajevo","Albertville","Lake Placid","Calgary"],"s":{"index":3}},{"k":"text","i":"British athlete Eddie 'the Eagle' Edwards became a Winter Olympics cult hero in which sport?","t":"Legends","e":"\u26f7\ufe0f","f":"He finished last in both of his events but won fans worldwide, and a 2016 film told his story.","s":{"accepted":["Ski jumping","Ski jump","Ski-jumping","Skijumping","Jumping"]}},{"k":"multi","i":"Select all the Winter Olympic hosts located in Asia.","t":"Hosts","e":"\ud83c\udf0f","f":"Lillehammer 1994 came just two years after Albertville 1992, as the Winter Games moved to their own four-year cycle.","o":["Nagano","Lillehammer","PyeongChang","Oslo","St. Moritz"],"s":{"indices":[0,2]}},{"k":"choice","i":"At Vancouver 2010, Canada won men's ice hockey gold thanks to an overtime 'Golden Goal' by which player?","t":"Ice hockey","e":"\ud83c\udfd2","f":"Canada won 14 golds at those Games, a record for a single Winter Olympics at the time.","o":["Wayne Gretzky","Sidney Crosby","Mario Lemieux","Jarome Iginla"],"s":{"index":1}},{"k":"text","i":"Which Italian city, together with Cortina d'Ampezzo, was chosen to host the 2026 Winter Olympics?","t":"Hosts","e":"\ud83c\uddee\ud83c\uddf9","f":"Their joint bid won the IOC vote in 2019, beating a bid from Stockholm and \u00c5re in Sweden.","s":{"accepted":["Milan","Milano"]}},{"k":"order","i":"Order these Winter Olympic hosts from earliest to latest Games.","t":"Timeline","e":"\u23f3","f":"Sochi 2014 was the first Winter Olympics ever held in Russia.","o":["Grenoble","Sarajevo","Nagano","Turin","Sochi"]},{"k":"multi","i":"Select all the sports in which athletes race down an ice track on a sled.","t":"Disciplines","e":"\ud83e\uddca","f":"All three sliding sports usually share the same purpose-built track at each Winter Games.","o":["Bobsleigh","Biathlon","Luge","Curling","Skeleton","Nordic combined"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"How do athletes ride the sled in skeleton?","t":"Disciplines","e":"\ud83e\uddca","f":"Luge sliders do the opposite, racing feet-first while lying on their backs.","o":["Feet-first, lying on their back","Sitting upright","Head-first, lying on their front","Kneeling"],"s":{"index":2}},{"k":"choice","i":"Moguls and aerials are events in which Winter Olympic sport?","t":"Disciplines","e":"\ud83c\udfbf","f":"It was a demonstration sport at Calgary 1988, and moguls became a full medal event at Albertville 1992.","o":["Alpine skiing","Snowboarding","Nordic combined","Freestyle skiing"],"s":{"index":3}},{"k":"choice","i":"Which Norwegian figure skater won Olympic gold in 1928, 1932 and 1936?","t":"Legends","e":"\u26f8\ufe0f","f":"After her skating career she became a Hollywood film star.","o":["Sonja Henie","Katarina Witt","Peggy Fleming","Dorothy Hamill"],"s":{"index":0}},{"k":"truefalse","i":"Canada did not win a single gold medal in official events at its home Olympics in Montreal 1976 or Calgary 1988.","t":"Home Games","e":"\ud83c\udf41","f":"That changed at Vancouver 2010, when Alexandre Bilodeau won moguls gold, Canada's first on home soil.","a":true},{"k":"choice","i":"Which American speed skater won all five men's speed skating events at the 1980 Winter Olympics in Lake Placid?","t":"Speed skating","e":"\u26f8\ufe0f","f":"He set a world record in the 10,000 m at those Games, and later rode the 1986 Tour de France as a pro cyclist.","o":["Dan Jansen","Apolo Anton Ohno","Eric Heiden","Shani Davis"],"s":{"index":2}}]},{"slug":"german-sporting-greats","title":"German Sporting Greats","tagline":"From the Miracle of Bern to Wimbledon wonderkids: how well do you know German sport?","emoji":"\ud83c\udde9\ud83c\uddea","gradient":["#111827","#b91c1c"],"categories":["sports","football"],"countries":["DE"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":321,"items":[{"k":"choice","i":"In the 1954 World Cup final, the 'Miracle of Bern', West Germany came from 2\u20130 down to beat which favourites?","t":"World Cup","e":"\u26bd","f":"Helmut Rahn's late goal sealed a 3\u20132 win and West Germany's first World Cup title.","o":["Brazil","Uruguay","Austria","Hungary"],"s":{"index":3}},{"k":"text","i":"Which German legend, nicknamed 'Der Kaiser', won the World Cup as captain in 1974 and as coach in 1990?","t":"Legends","e":"\ud83d\udc51","f":"He was only the second man to win the World Cup as both player and coach, after Brazil's M\u00e1rio Zagallo.","s":{"accepted":["Beckenbauer","Franz Beckenbauer"]}},{"k":"number","i":"How many goals did Germany score against hosts Brazil in their 2014 World Cup semi-final?","t":"World Cup","e":"\ud83d\ude32","f":"Germany led 5\u20130 after just 29 minutes in Belo Horizonte, and went on to beat Argentina in the final.","s":{"value":7,"tolerance":0,"min":0,"max":10,"unit":"goals"}},{"k":"choice","i":"Who won the Wimbledon men's singles title in 1985 at just 17 years old?","t":"Tennis","e":"\ud83c\udfbe","f":"He was also the first unseeded player and the first German to win the men's title.","o":["Michael Stich","Mats Wilander","Stefan Edberg","Boris Becker"],"s":{"index":3}},{"k":"choice","i":"Michael Schumacher won five straight F1 world titles from 2000 to 2004 with which team?","t":"Formula One","e":"\ud83c\udfce\ufe0f","f":"His first two titles came with Benetton in 1994 and 1995, giving him seven in total.","o":["Benetton","Ferrari","McLaren","Williams"],"s":{"index":1}},{"k":"choice","i":"With which team did Dirk Nowitzki win the 2011 NBA championship?","t":"NBA","e":"\ud83c\udfc0","f":"He was named Finals MVP after beating the Miami Heat, and spent all 21 of his NBA seasons with the same franchise.","o":["Dallas Mavericks","San Antonio Spurs","Houston Rockets","Phoenix Suns"],"s":{"index":0}},{"k":"choice","i":"Katarina Witt won Olympic gold in 1984 and 1988 in which sport?","t":"Winter Olympics","e":"\u2744\ufe0f","f":"She was the first woman since Sonja Henie to win back-to-back Olympic titles in her event.","o":["Speed skating","Luge","Figure skating","Biathlon"],"s":{"index":2}},{"k":"choice","i":"Which German golfer won the Masters at Augusta in both 1985 and 1993?","t":"Golf","e":"\u26f3","f":"Langer also captained Europe to victory at the 2004 Ryder Cup at Oakland Hills in the USA.","o":["Martin Kaymer","Bernhard Langer","Alex \u010cejka","Marcel Siem"],"s":{"index":1}},{"k":"choice","i":"Who scored West Germany's winning goal in the 1974 World Cup final against the Netherlands?","t":"World Cup","e":"\ud83c\udfaf","f":"The 2\u20131 win in Munich came after the Dutch had scored a penalty before any German had touched the ball.","o":["Paul Breitner","Uli Hoene\u00df","Gerd M\u00fcller","J\u00fcrgen Grabowski"],"s":{"index":2}},{"k":"truefalse","i":"In 1988 Steffi Graf won all four Grand Slam singles titles and Olympic gold in the same year.","t":"Tennis","e":"\ud83e\udd47","f":"The feat became known as the 'Golden Slam'; she beat Gabriela Sabatini in the Olympic final in Seoul.","a":true},{"k":"truefalse","i":"By the end of 2024, Germany had won the men's European Championship three times.","t":"Euros","e":"\ud83c\udfc6","f":"They won in 1972 and 1980 as West Germany, and in 1996 when Oliver Bierhoff hit the first golden goal in a major final.","a":true},{"k":"truefalse","i":"The Bundesliga, Germany's top football league, was founded before World War II.","t":"Bundesliga","e":"\ud83d\udcdc","f":"It kicked off in the 1963\u201364 season, and 1. FC K\u00f6ln were crowned its first champions.","a":false},{"k":"multi","i":"Select all the German drivers who won the Formula One World Championship.","t":"Formula One","e":"\ud83c\udfc1","f":"Vettel won four titles in a row with Red Bull from 2010 to 2013, and Rosberg retired just days after winning in 2016.","o":["Sebastian Vettel","Ralf Schumacher","Nico Rosberg","Nick Heidfeld","Timo Glock"],"s":{"indices":[0,2]}},{"k":"order","i":"Order these German sporting moments from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Munich hosted in 1972, Schumacher won his first title in 1994, Germany's women first won the World Cup in 2003 and Nowitzki won the NBA title in 2011.","o":["Munich hosts the Summer Olympics","Michael Schumacher wins his first F1 world title","Germany's women win their first World Cup","Dirk Nowitzki wins the NBA title"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'df83045ec95a8fef2f5e07922d848466' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 4'; end $q$;
do $q$ declare d text := $d$[{"slug":"euro-championship-stories","title":"Euro Championship Stories","tagline":"Fairy tales, shocks and golden goals: the European Championship from 1960 to 2024.","emoji":"\ud83c\udf0d","gradient":["#b91c1c","#1d4ed8"],"categories":["football","sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":322,"items":[{"k":"choice","i":"Which nation won the first European Championship, in 1960?","t":"Origins","e":"\ud83e\udd47","f":"They beat Yugoslavia 2\u20131 after extra time in Paris, with the great Lev Yashin in goal.","o":["Yugoslavia","Soviet Union","Spain","Czechoslovakia"],"s":{"index":1}},{"k":"truefalse","i":"Denmark won Euro 1992 after being called up shortly before the tournament as a late replacement.","t":"Underdogs","e":"\ud83c\udf89","f":"They beat reigning world champions Germany 2\u20130 in the final.","a":true},{"k":"choice","i":"Who coached Greece to their shock Euro 2004 title?","t":"Underdogs","e":"\ud83c\udfdb\ufe0f","f":"Greece beat hosts Portugal in both the opening game and the final.","o":["Giovanni Trapattoni","Guus Hiddink","Otto Rehhagel","Luiz Felipe Scolari"],"s":{"index":2}},{"k":"text","i":"Which Czechoslovak player gave his name to the cheeky chipped penalty that won the Euro 1976 final shoot-out?","t":"Penalties","e":"\ud83e\udd45","f":"Czechoslovakia beat West Germany in the first Euro final to be decided by penalties.","s":{"accepted":["Panenka","Anton\u00edn Panenka","Antonin Panenka"]}},{"k":"choice","i":"Which country won Euro 2016, beating the hosts in the final?","t":"Finals","e":"\ud83c\udfaf","f":"Substitute \u00c9der scored the only goal in extra time at the Stade de France.","o":["Wales","Germany","Belgium","Portugal"],"s":{"index":3}},{"k":"number","i":"How many goals did Michel Platini score at Euro 1984?","t":"Goalscorers","e":"\u26bd","f":"He scored in all five of France's matches, including two hat-tricks.","s":{"value":9,"tolerance":0,"min":0,"max":15,"unit":"goals"}},{"k":"choice","i":"Which nation won Euro 2024 in Berlin, claiming its fourth European title?","t":"Finals","e":"\ud83c\udfc6","f":"Mikel Oyarzabal's late goal sealed a 2\u20131 win over England in the final.","o":["Spain","England","Germany","Italy"],"s":{"index":0}},{"k":"order","i":"Order these Euro hosts from earliest to latest tournament.","t":"Hosts","e":"\ud83d\uddfa\ufe0f","f":"Euro 2000 was the first co-hosted edition, shared by Belgium and the Netherlands.","o":["Yugoslavia","Sweden","Portugal","Austria & Switzerland","Poland & Ukraine"]},{"k":"multi","i":"Select all the countries that won the European Championship on home soil.","t":"Hosts","e":"\ud83c\udfe0","f":"Spain won in 1964, Italy in 1968 and France in 1984, each time as hosts.","o":["Sweden","Italy","France","England","Spain","Portugal"],"s":{"indices":[1,2,4]}},{"k":"choice","i":"Who scored the golden goal that won the Euro 96 final for Germany?","t":"Finals","e":"\u2728","f":"Germany beat the Czech Republic 2\u20131, with Bierhoff scoring both goals after coming off the bench.","o":["J\u00fcrgen Klinsmann","Oliver Bierhoff","Andreas M\u00f6ller","Matthias Sammer"],"s":{"index":1}},{"k":"truefalse","i":"Euro 2012 was the first European Championship with 24 teams.","t":"Format","e":"\ud83d\udd22","f":"The jump to 24 teams came at Euro 2016; the five tournaments from 1996 to 2012 had 16 teams each.","a":false},{"k":"choice","i":"Which nation won Euro 2020, beating England on penalties at Wembley?","t":"Finals","e":"\ud83d\udd35","f":"The tournament was postponed to 2021 because of the COVID-19 pandemic but kept its 'Euro 2020' name.","o":["Spain","Denmark","Italy","Belgium"],"s":{"index":2}},{"k":"multi","i":"Select all the nations that won the European Championship more than once between 1960 and 2024.","t":"Winners","e":"\ud83d\udd01","f":"France won in 1984 and 2000, while Spain lifted the trophy four times.","o":["Greece","Spain","Portugal","Netherlands","Denmark","France"],"s":{"indices":[1,5]}},{"k":"text","i":"Which Dutch striker scored a famous volley in the Euro 1988 final against the Soviet Union?","t":"Finals","e":"\ud83d\udfe0","f":"He was the tournament's top scorer with five goals, including a hat-trick against England.","s":{"accepted":["Marco van Basten","van Basten","Basten","Marco Van Basten"]}}]},{"slug":"super-bowl-sundays","title":"Super Bowl Sundays","tagline":"Roman numerals, perfect seasons and famous upsets: how sharp is your NFL history?","emoji":"\ud83c\udfc8","gradient":["#1e3a8a","#b91c1c"],"categories":["sports","history"],"countries":["US"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":323,"items":[{"k":"choice","i":"Which team won the first Super Bowl, played in January 1967?","t":"Firsts","e":"\ud83e\udd47","f":"The winners beat the Kansas City Chiefs 35\u201310 at the Los Angeles Memorial Coliseum.","o":["Kansas City Chiefs","New York Jets","Dallas Cowboys","Green Bay Packers"],"s":{"index":3}},{"k":"text","i":"The Super Bowl trophy is named after which legendary head coach?","t":"Trophies","e":"\ud83c\udfc6","f":"The trophy was renamed in the coach's memory after his death in 1970.","s":{"accepted":["Vince Lombardi","Lombardi","Vincent Lombardi"]}},{"k":"truefalse","i":"The 1985 Chicago Bears went through the entire season and playoffs without losing a game.","t":"Perfect season","e":"\ud83d\udc2c","f":"The Bears lost once, to Miami, before winning Super Bowl XX; it was the 1972 Dolphins who finished a perfect 17\u20130.","a":false},{"k":"truefalse","i":"The Buffalo Bills lost four Super Bowls in a row in the early 1990s.","t":"Near misses","e":"\ud83e\uddac","f":"Their defeats came against the New York Giants, Washington and, twice, the Dallas Cowboys.","a":true},{"k":"number","i":"Super Bowl LVIII was played in February 2024. What number is LVIII?","t":"Roman numerals","e":"\ud83d\udd22","f":"Super Bowl 50 in 2016 used ordinary numbers in its logo, because the NFL felt a lone 'L' looked odd.","s":{"value":58,"tolerance":0,"min":40,"max":70,"unit":""}},{"k":"choice","i":"How many Super Bowls did Tom Brady win during his playing career?","t":"Legends","e":"\ud83d\udc10","f":"Brady played in ten Super Bowls in all, winning seven and losing three.","o":["6","7","8","10"],"s":{"index":1}},{"k":"multi","i":"Select all the NFL teams Tom Brady played for.","t":"Legends","e":"\ud83c\udfdf\ufe0f","f":"Brady was only the 199th pick in the 2000 NFL Draft, chosen in the sixth round.","o":["Miami Dolphins","New England Patriots","San Francisco 49ers","Tampa Bay Buccaneers","Denver Broncos"],"s":{"indices":[1,3]}},{"k":"choice","i":"Which quarterback famously 'guaranteed' victory before the New York Jets' upset win in Super Bowl III?","t":"Upsets","e":"\ud83d\udde3\ufe0f","f":"The Jets beat the heavily favoured Baltimore Colts 16\u20137 in January 1969.","o":["Joe Namath","Johnny Unitas","Bart Starr","Joe Montana"],"s":{"index":0}},{"k":"number","i":"How many yards long is an American football field between the two goal lines?","t":"Rules","e":"\ud83d\udccf","f":"Add the two 10-yard end zones and the whole field measures 120 yards.","s":{"value":100,"tolerance":0,"min":60,"max":130,"unit":"yards"}},{"k":"choice","i":"Which coach led the Miami Dolphins to back-to-back Super Bowl wins after the 1972 and 1973 seasons?","t":"Coaches","e":"\ud83d\udccb","f":"He had also coached the Baltimore Colts in their shock Super Bowl III defeat.","o":["Tom Landry","Chuck Noll","Don Shula","Bill Walsh"],"s":{"index":2}},{"k":"choice","i":"Which team won four Super Bowls in six seasons in the 1970s?","t":"Dynasties","e":"\u2699\ufe0f","f":"Their famously tough defence was nicknamed the 'Steel Curtain'.","o":["Dallas Cowboys","Miami Dolphins","Pittsburgh Steelers","Oakland Raiders"],"s":{"index":2}},{"k":"choice","i":"The first Super Bowl matched the NFL champions against the champions of which rival league?","t":"Origins","e":"\ud83e\udd1d","f":"The two leagues fully merged in 1970, creating the AFC and NFC conferences.","o":["Canadian Football League (CFL)","United States Football League (USFL)","World Football League (WFL)","American Football League (AFL)"],"s":{"index":3}},{"k":"order","i":"Order these American football scoring plays from fewest points to most.","t":"Scoring","e":"\ud83d\udd22","f":"After a touchdown, a team can try a 1-point kick or go for a 2-point conversion from close range.","o":["Extra-point kick","Safety","Field goal","Touchdown"]},{"k":"truefalse","i":"The Super Bowl is always played in the home stadium of one of the two teams.","t":"Venues","e":"\ud83c\udfdf\ufe0f","f":"Sites are picked years in advance; no team played a Super Bowl in its own stadium until February 2021.","a":false}]},{"slug":"fairway-to-heaven","title":"Fairway to Heaven","tagline":"Majors, legends and the language of the links: tee off and test your swing.","emoji":"\u26f3","gradient":["#166534","#a16207"],"categories":["sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":324,"items":[{"k":"multi","i":"Select all the tournaments that are men's major championships.","t":"Majors","e":"\ud83c\udfc6","f":"The fourth men's major is the US Open, first played in 1895.","o":["The Masters","Players Championship","The Open Championship","Ryder Cup","PGA Championship","Tour Championship"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"What does the winner of the Masters receive to wear?","t":"Traditions","e":"\ud83e\udde5","f":"The champion may take it home for a year before it returns to Augusta National.","o":["A gold blazer","A red cardigan","A white cap","A green jacket"],"s":{"index":3}},{"k":"text","i":"In which US state is Augusta National, the home of the Masters?","t":"Venues","e":"\ud83d\uddfa\ufe0f","f":"The club was co-founded by amateur legend Bobby Jones, and the first Masters was played in 1934.","s":{"accepted":["Georgia","GA"]}},{"k":"choice","i":"By how many strokes did Tiger Woods win the 1997 Masters, his first major title?","t":"Breakthroughs","e":"\ud83d\udc2f","f":"Woods was just 21 and in his first full season as a professional.","o":["6","9","12","15"],"s":{"index":2}},{"k":"number","i":"How many men's major championships did Jack Nicklaus win as a professional?","t":"Legends","e":"\ud83d\udc3b","f":"The last came at the 1986 Masters, which he won at the age of 46.","s":{"value":18,"tolerance":0,"min":8,"max":30,"unit":"majors"}},{"k":"choice","i":"Which Scottish town is known as the 'Home of Golf'?","t":"Origins","e":"\ud83c\udff4","f":"Its Royal and Ancient Golf Club was founded in 1754.","o":["Carnoustie","Troon","St Andrews","Turnberry"],"s":{"index":2}},{"k":"order","i":"Order these single-hole scores from best (fewest strokes) to worst.","t":"Scoring","e":"\ud83d\udcc9","f":"An albatross is three under par on a hole, and in the USA it is often called a 'double eagle'.","o":["Albatross","Eagle","Par","Bogey","Double bogey"]},{"k":"choice","i":"What do golfers shout to warn people that a ball is heading their way?","t":"Etiquette","e":"\ud83d\udce3","f":"One popular theory is that it is short for 'before', a warning once called to forecaddies down the fairway.","o":["Fore!","Heads!","Mark!","Ware!"],"s":{"index":0}},{"k":"truefalse","i":"The 18-hole round became standard after St Andrews' Old Course was reduced from 22 holes to 18 in 1764.","t":"History","e":"\ud83d\udd70\ufe0f","f":"Other clubs gradually followed St Andrews' lead, and 18 holes became the norm worldwide.","a":true},{"k":"choice","i":"The Ryder Cup pits the United States against which team?","t":"Team Golf","e":"\ud83e\udd1d","f":"It began in 1927 as the USA against Great Britain, and continental Europeans joined from 1979.","o":["International Team","Canada","Japan","Europe"],"s":{"index":3}},{"k":"number","i":"Under the Rules of Golf, what is the maximum number of clubs a player may carry during a round?","t":"Rules","e":"\ud83c\udfcc\ufe0f","f":"The 14-club limit was adopted by the USGA in 1938 and by the R&A in 1939.","s":{"value":14,"tolerance":0,"min":6,"max":25,"unit":"clubs"}},{"k":"choice","i":"Which American golfer was nicknamed 'The King'?","t":"Legends","e":"\ud83d\udc51","f":"Palmer won seven majors, including four Masters titles, and his fans were known as 'Arnie's Army'.","o":["Ben Hogan","Arnold Palmer","Sam Snead","Tom Watson"],"s":{"index":1}},{"k":"truefalse","i":"The US Open is the only men's major played at the same course every year.","t":"Majors","e":"\ud83d\udccd","f":"That's the Masters at Augusta National; the US Open moves around, with Pebble Beach, Oakmont and Shinnecock Hills among its hosts.","a":false},{"k":"multi","i":"Select all the golfers who won the Masters.","t":"Champions","e":"\ud83d\udc9a","f":"Greg Norman finished runner-up at Augusta three times but never won it.","o":["Jack Nicklaus","Greg Norman","Tiger Woods","Colin Montgomerie","Arnold Palmer"],"s":{"indices":[0,2,4]}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'a5404c6b18dc67c555a3e7c63081d306' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 5'; end $q$;
do $q$ declare d text := $d$[{"slug":"motorsport-mix","title":"Beyond Formula One","tagline":"Bikes, ovals, deserts and 24-hour epics: explore motorsport's other giants.","emoji":"\ud83c\udfcd\ufe0f","gradient":["#ea580c","#9f1239"],"categories":["sports","cars"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":325,"items":[{"k":"choice","i":"Which racing number is famously associated with MotoGP legend Valentino Rossi?","t":"MotoGP","e":"\ud83c\udfcd\ufe0f","f":"Rossi chose it in honour of his father Graziano, who raced with that number.","o":["93","99","46","27"],"s":{"index":2}},{"k":"number","i":"How many premier-class (500cc and MotoGP) world titles did Valentino Rossi win before retiring in 2021?","t":"MotoGP","e":"\ud83c\udfc6","f":"Counting his 125cc and 250cc crowns too, Rossi won nine Grand Prix world championships.","s":{"value":7,"tolerance":0,"min":1,"max":12,"unit":"titles"}},{"k":"text","i":"Which French town hosts the famous 24-hour sports car endurance race, usually held in June?","t":"Endurance","e":"\ud83c\udf19","f":"In the old 'Le Mans start', drivers sprinted across the track to their cars; it was dropped after 1969.","s":{"accepted":["Le Mans","LeMans","Le Mans France"]}},{"k":"choice","i":"What do winners of the Indianapolis 500 traditionally drink in Victory Lane?","t":"Traditions","e":"\ud83c\udfc6","f":"The custom dates back to 1936, when winner Louis Meyer asked for a glass of buttermilk.","o":["Champagne","Orange juice","Lemonade","Milk"],"s":{"index":3}},{"k":"choice","i":"Why is the Indianapolis Motor Speedway nicknamed 'The Brickyard'?","t":"Nicknames","e":"\ud83c\udfdf\ufe0f","f":"A strip of the original bricks, one yard wide, still marks the start-finish line.","o":["Its track was once paved with millions of bricks","It was built on the site of a brick factory","Its grandstands are built of red brick","Its first winner was a bricklayer"],"s":{"index":0}},{"k":"number","i":"How many laps of the 2.5-mile oval make up the Indianapolis 500?","t":"Ovals","e":"\ud83d\udd04","f":"Ray Harroun won the first race in a Marmon Wasp, using a rear-view mirror instead of a riding mechanic.","s":{"value":200,"tolerance":0,"min":50,"max":400,"unit":"laps"}},{"k":"choice","i":"Which race, held each February in Florida, is known as 'The Great American Race'?","t":"Stock cars","e":"\ud83c\udfc1","f":"The very first edition ended in a photo finish, and Lee Petty was declared the winner three days later.","o":["Coca-Cola 600","Daytona 500","Southern 500","Brickyard 400"],"s":{"index":1}},{"k":"choice","i":"The Isle of Man TT is a famous road race for which kind of vehicle?","t":"Classic races","e":"\ud83c\udfdd\ufe0f","f":"On the fastest laps of its public-road course, riders average well over 200 km/h.","o":["Rally cars","Trucks","Motorcycles","Go-karts"],"s":{"index":2}},{"k":"truefalse","i":"The Dakar Rally originally ran from Paris to Dakar, the capital of Senegal.","t":"Desert racing","e":"\ud83c\udfdc\ufe0f","f":"The rally later moved to South America in 2009 and to Saudi Arabia in 2020.","a":true},{"k":"multi","i":"Select all the types of vehicle that have competed in the Dakar Rally.","t":"Desert racing","e":"\ud83e\udded","f":"Motorbike riders tackle the same long desert stages as the cars, often covering hundreds of kilometres a day.","o":["Trucks","Hovercraft","Motorbikes","Snowmobiles","Cars"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"In the World Rally Championship, what is the person in the passenger seat called?","t":"Rallying","e":"\ud83d\uddfa\ufe0f","f":"They read out 'pace notes' describing every bend, crest and jump on the stage ahead.","o":["Spotter","Crew chief","Pit boss","Co-driver"],"s":{"index":3}},{"k":"choice","i":"Which French driver won nine World Rally Championship titles in a row, from 2004 to 2012?","t":"Legends","e":"\ud83c\udfc6","f":"He won all nine titles with Citro\u00ebn, and before rallying he was a keen competitive gymnast.","o":["S\u00e9bastien Loeb","S\u00e9bastien Ogier","Carlos Sainz","Colin McRae"],"s":{"index":0}},{"k":"truefalse","i":"In rallying, cars race wheel-to-wheel on the same stretch of road at the same time.","t":"Rules","e":"\u23f1\ufe0f","f":"Rally cars start at intervals and race against the clock on closed roads called 'special stages'.","a":false},{"k":"order","i":"Order these world championships by their first season, from earliest to latest.","t":"Firsts","e":"\ud83d\udcc5","f":"The first motorcycle Grand Prix world championship race was the 1949 Isle of Man TT, and Formula E's first race was in Beijing in 2014.","o":["Motorcycle Grand Prix (now MotoGP)","World Rally Championship","World Superbike Championship","Formula E"]}]},{"slug":"paralympic-power","title":"Paralympic Power","tagline":"From Stoke Mandeville to the Paralympic stage: sports, symbols and pioneers.","emoji":"\ud83e\uddbd","gradient":["#16a34a","#1d4ed8"],"categories":["olympics","sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":326,"items":[{"k":"choice","i":"Which doctor organised the 1948 Stoke Mandeville Games, the forerunner of the Paralympics?","t":"Pioneers","e":"\ud83e\ude7a","f":"The first event was an archery contest for 16 injured ex-service personnel, held on the opening day of the London 1948 Olympics.","o":["Pierre de Coubertin","Ludwig Guttmann","Avery Brundage","Robert Steadward"],"s":{"index":1}},{"k":"number","i":"In what year were the first official Paralympic Games held, in Rome?","t":"Milestones","e":"\ud83c\udfdf\ufe0f","f":"They were held in Rome about a week after that year's Olympic Games had finished there.","s":{"value":1960,"tolerance":0,"min":1936,"max":1992,"unit":""}},{"k":"multi","i":"Select all the colours in the Paralympic symbol, the Agitos.","t":"Symbols","e":"\ud83c\udfa8","f":"Its name comes from the Latin 'agito', meaning 'I move', and it shows three swooshing crescents.","o":["Red","Yellow","Blue","Black","Green"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Goalball was designed for athletes with which type of impairment?","t":"Sports","e":"\ud83e\udd45","f":"The ball has bells inside, so spectators must stay silent while play is going on.","o":["Visual impairment","Hearing impairment","Spinal cord injury","Limb loss"],"s":{"index":0}},{"k":"number","i":"How many players per team are on court at once in goalball?","t":"Sports","e":"\ud83d\udd22","f":"Every player wears blackout eyeshades, so athletes with different levels of sight compete equally.","s":{"value":3,"tolerance":0,"min":1,"max":9,"unit":"players"}},{"k":"choice","i":"In boccia, players try to get their red or blue balls closest to which target?","t":"Sports","e":"\ud83c\udfaf","f":"Boccia has no Olympic equivalent and joined the Paralympic programme in 1984.","o":["A white ball called the jack","A painted bullseye on the floor","A wooden peg","A small hoop"],"s":{"index":0}},{"k":"text","i":"Wheelchair rugby was invented in Canada in 1977. What fierce nickname did it originally have?","t":"Sports","e":"\ud83e\uddbd","f":"It is played indoors with a ball like a volleyball, and men and women can play on the same team.","s":{"accepted":["Murderball","Murder ball","Murder-ball"]}},{"k":"truefalse","i":"In sitting volleyball, players are not allowed to lift their bottom off the floor while playing the ball.","t":"Rules","e":"\ud83c\udfd0","f":"The net is much lower than in standing volleyball: 1.15 m for men and 1.05 m for women.","a":true},{"k":"choice","i":"In Para swimming classes S1 to S10, for physical impairments, what does a lower number mean?","t":"Classification","e":"\ud83c\udfca","f":"Classes S11 to S13 are for visually impaired swimmers, and S11 athletes wear blackened goggles.","o":["A faster qualifying time","A younger age group","A more severe impairment","A shorter race distance"],"s":{"index":2}},{"k":"choice","i":"In Para athletics class names such as T44, what does the letter 'T' stand for?","t":"Classification","e":"\ud83c\udfc3","f":"Throwing events such as shot put and javelin use 'F' (field) classes instead.","o":["Team","Tier","Technique","Track"],"s":{"index":3}},{"k":"order","i":"Order these Paralympic milestones from earliest to latest.","t":"Milestones","e":"\u23f3","f":"The IPC was founded in 1989 and has its headquarters in Bonn, Germany.","o":["First Stoke Mandeville Games","First Summer Paralympics in Rome","First Winter Paralympics in Sweden","International Paralympic Committee founded"]},{"k":"multi","i":"Select all the sports on the Summer Paralympic programme.","t":"Sports","e":"\ud83c\udfc5","f":"Blind football is played five-a-side with a ball that rattles, and the goalkeepers can be sighted.","o":["Wheelchair fencing","Para ice hockey","Wheelchair basketball","Wheelchair curling","Blind football"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which phrase is the motto of the Paralympic movement?","t":"Motto","e":"\ud83d\udcac","f":"The name 'Paralympic' first came from 'paraplegic' but is now explained as 'parallel' to the Olympics.","o":["Faster, Higher, Stronger","Unity in Diversity","Dare to Dream","Spirit in Motion"],"s":{"index":3}},{"k":"truefalse","i":"In wheelchair tennis, the ball may bounce only once before it must be returned, just as in standard tennis.","t":"Rules","e":"\ud83c\udfbe","f":"Players may let the ball bounce twice; only the first bounce has to land inside the court, and the second can land outside it.","a":false}]},{"slug":"spanish-sporting-glory","title":"Spanish Sporting Glory","tagline":"Tiki-taka, clay-court kings and golfing magicians: how well do you know Spanish sport?","emoji":"\ud83c\uddea\ud83c\uddf8","gradient":["#c2410c","#9f1239"],"categories":["sports","football"],"countries":["ES"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":327,"items":[{"k":"text","i":"Who scored Spain's extra-time winner in the 2010 World Cup final?","t":"World Cup","e":"\u26bd","f":"His goal came in the 116th minute at Soccer City in Johannesburg, giving Spain its first World Cup.","s":{"accepted":["Iniesta","Andr\u00e9s Iniesta","Andres Iniesta"]}},{"k":"choice","i":"Which team did Spain beat 1\u20130 in the 2010 World Cup final?","t":"World Cup","e":"\ud83c\udfc6","f":"Spain became the first European nation to win a World Cup held outside Europe.","o":["Germany","Italy","Portugal","Netherlands"],"s":{"index":3}},{"k":"number","i":"How many men's European Championships had Spain won by the end of 2024?","t":"Euros","e":"\ud83e\udd47","f":"Spain won in 1964, 2008, 2012 and 2024, when they beat England 2\u20131 in the final in Berlin.","s":{"value":4,"tolerance":0,"min":0,"max":10,"unit":"titles"}},{"k":"truefalse","i":"Spain won Euro 2008, the 2010 World Cup and Euro 2012 in a row.","t":"Golden era","e":"\ud83d\udd01","f":"They capped the run by thrashing Italy 4\u20130 in the Euro 2012 final in Kyiv.","a":true},{"k":"number","i":"How many French Open singles titles did Rafael Nadal win in his career?","t":"Tennis","e":"\ud83c\udfbe","f":"He won 112 of his 116 French Open matches, losing only four times, before retiring in November 2024.","s":{"value":14,"tolerance":0,"min":5,"max":20,"unit":"titles"}},{"k":"multi","i":"Select all the tournaments Rafael Nadal won at least once.","t":"Tennis","e":"\ud83c\udfc5","f":"Nadal won all four majors, but the season-ending ATP Finals and the Miami Open eluded him despite several final appearances.","o":["Wimbledon","ATP Finals","US Open","Miami Open","Australian Open"],"s":{"indices":[0,2,4]}},{"k":"truefalse","i":"Brothers Pau and Marc Gasol both won NBA championships.","t":"NBA","e":"\ud83c\udfc0","f":"Pau won two titles with the Los Angeles Lakers in 2009 and 2010, and Marc won with the Toronto Raptors in 2019.","a":true},{"k":"choice","i":"In 1959, which rider became the first Spaniard to win the Tour de France?","t":"Cycling","e":"\ud83d\udeb4","f":"Nicknamed 'the Eagle of Toledo', he was a superb climber who won the Tour's mountains prize six times.","o":["Federico Bahamontes","Luis Oca\u00f1a","Pedro Delgado","Carlos Sastre"],"s":{"index":0}},{"k":"choice","i":"In 1980, which Spaniard became the first European to win the Masters at Augusta?","t":"Golf","e":"\u26f3","f":"Ballesteros won five majors in all, including three Open Championships, and was a talisman for Europe in the Ryder Cup.","o":["Seve Ballesteros","Jos\u00e9 Mar\u00eda Olaz\u00e1bal","Sergio Garc\u00eda","Miguel \u00c1ngel Jim\u00e9nez"],"s":{"index":0}},{"k":"choice","i":"FC Barcelona's famous motto 'M\u00e9s que un club' means what in English?","t":"Clubs","e":"\ud83d\udd34","f":"The motto is in Catalan, the language of the club's home region of Catalonia.","o":["Club of the people","More than a club","Always forward","United we stand"],"s":{"index":1}},{"k":"choice","i":"How was the Olympic cauldron lit at the Barcelona 1992 opening ceremony?","t":"Barcelona 1992","e":"\ud83d\udd25","f":"Paralympic archer Antonio Rebollo fired the arrow, and Spain went on to win 13 gold medals at its home Games.","o":["By a torch-bearer climbing a giant staircase","By a firework launched from the stadium roof","With a flaming arrow fired by an archer","By a cyclist riding up a ramp"],"s":{"index":2}},{"k":"choice","i":"Fernando Alonso won his Formula One world titles in 2005 and 2006 with which team?","t":"Formula One","e":"\ud83c\udfce\ufe0f","f":"In 2005 he ended Michael Schumacher's run of five straight titles and became the youngest champion at the time.","o":["Ferrari","McLaren","Minardi","Renault"],"s":{"index":3}},{"k":"multi","i":"Select all the Spanish clubs that have won the European Cup or Champions League.","t":"Champions League","e":"\u2b50","f":"Atl\u00e9tico and Valencia reached finals but lost, while Real Madrid won the first five European Cups from 1956 to 1960.","o":["Real Madrid","Atl\u00e9tico Madrid","Valencia","Barcelona","Sevilla"],"s":{"indices":[0,3]}},{"k":"order","i":"Order these Spanish sporting moments from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Spain's first Euro came on home soil in 1964, Barcelona hosted in 1992, the World Cup came in 2010 and Mar\u00edn won at Rio 2016.","o":["Spain win their first European Championship","Barcelona hosts the Summer Olympics","Spain win the World Cup in South Africa","Carolina Mar\u00edn wins Olympic badminton gold"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'cee0dd74f6745b646d70047404d5105e' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 6'; end $q$;
do $q$ declare d text := $d$[{"slug":"football-nicknames","title":"Name That Nickname","tagline":"Gunners, Azzurri, Socceroos and more: who goes by which name in world football?","emoji":"\ud83c\udff7\ufe0f","gradient":["#ea580c","#be123c"],"categories":["football","sports","language"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":328,"items":[{"k":"choice","i":"Which English club is nicknamed 'The Gunners'?","t":"Clubs","e":"\ud83d\udd34","f":"The name dates back to the club's founding in 1886 by workers at the Royal Arsenal in Woolwich.","o":["West Ham United","Everton","Aston Villa","Arsenal"],"s":{"index":3}},{"k":"choice","i":"Which national team is known as the 'Azzurri'?","t":"National teams","e":"\ud83d\udd35","f":"Azzurri means 'the blues', a colour linked to Italy's former royal family, the House of Savoy.","o":["Italy","Uruguay","Greece","Argentina"],"s":{"index":0}},{"k":"text","i":"Which country's national team is nicknamed 'Oranje'?","t":"National teams","e":"\ud83d\udfe0","f":"The orange shirts honour the Dutch royal family, the House of Orange-Nassau.","s":{"accepted":["Netherlands","The Netherlands","Holland","Nederland"]}},{"k":"choice","i":"Which national team is nicknamed the 'Super Eagles'?","t":"National teams","e":"\ud83e\udd85","f":"Nigeria won the Olympic football gold medal at Atlanta 1996.","o":["Ghana","Nigeria","Cameroon","Senegal"],"s":{"index":1}},{"k":"choice","i":"'Socceroos' is the nickname of which national team?","t":"National teams","e":"\u26bd","f":"The nickname blends the words 'soccer' and 'kangaroo'.","o":["New Zealand","United States","Australia","Canada"],"s":{"index":2}},{"k":"multi","i":"Select all the nicknames that belong to African national teams.","t":"National teams","e":"\ud83c\udf0d","f":"Ghana are the Black Stars, Cameroon the Indomitable Lions and Egypt the Pharaohs.","o":["Black Stars","Indomitable Lions","Samurai Blue","La Roja","The Pharaohs","All Whites"],"s":{"indices":[0,1,4]}},{"k":"choice","i":"Which national team is called 'La Albiceleste', after its white and sky-blue striped shirts?","t":"National teams","e":"\ud83e\udd0d","f":"Neighbours Uruguay, who wear plain sky blue, are known as 'La Celeste'.","o":["Uruguay","Chile","Paraguay","Argentina"],"s":{"index":3}},{"k":"truefalse","i":"France's national football team is widely known as 'Les Bleus'.","t":"National teams","e":"\ud83d\udd37","f":"France's rugby team shares the nickname, as both teams play in blue shirts.","a":true},{"k":"truefalse","i":"Liverpool and Belgium's national team share the nickname 'Red Devils'.","t":"Shared names","e":"\ud83d\ude08","f":"Manchester United share it with Belgium, whose team has been the Red Devils since the early 1900s; Liverpool are known as 'the Reds'.","a":false},{"k":"choice","i":"What is the best-known nickname of England's men's national team?","t":"National teams","e":"\u26aa","f":"It comes from the three lions on the team's crest, taken from England's royal coat of arms.","o":["The Three Lions","The Bulldogs","The Red Roses","The Redcoats"],"s":{"index":0}},{"k":"text","i":"Which country's national team is nicknamed 'Bafana Bafana'?","t":"National teams","e":"\ud83c\udfb6","f":"The phrase means 'the boys, the boys' in isiZulu.","s":{"accepted":["South Africa","RSA","Republic of South Africa"]}},{"k":"multi","i":"Select all the nicknames of Italian clubs.","t":"Clubs","e":"\ud83c\udfa8","f":"They describe shirt colours: red-black (AC Milan), black-blue (Inter) and white-black (Juventus).","o":["Los Blancos","Rossoneri","Blaugrana","Bianconeri","Nerazzurri","Les Parisiens"],"s":{"indices":[1,3,4]}},{"k":"choice","i":"Which English club is nicknamed 'The Toffees'?","t":"Clubs","e":"\ud83c\udf6c","f":"The name is linked to toffee shops near the club's early home grounds.","o":["Liverpool","Everton","Fulham","Leeds United"],"s":{"index":1}},{"k":"choice","i":"Which national team is known as 'El Tri'?","t":"National teams","e":"\ud83d\udfe2","f":"'El Tri' is short for 'El Tricolor', after the green, white and red of the national flag.","o":["Colombia","Peru","Mexico","Chile"],"s":{"index":2}}]},{"slug":"diamond-dreams","title":"Diamond Dreams","tagline":"Curses, perfect games and pinstripes: step up to the plate for baseball history.","emoji":"\u26be","gradient":["#0f766e","#1e40af"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":329,"items":[{"k":"number","i":"In what year did Jackie Robinson break Major League Baseball's modern colour barrier?","t":"Pioneers","e":"\ud83e\udde2","f":"His number 42 is retired by every MLB team, and all players wear it on Jackie Robinson Day each April 15.","s":{"value":1947,"tolerance":0,"min":1920,"max":1965,"unit":""}},{"k":"choice","i":"After the 1919 season, the Boston Red Sox sold Babe Ruth to which team?","t":"Legends","e":"\ud83d\udcb0","f":"Ruth went on to hit 714 career home runs, the vast majority of them for the Yankees.","o":["New York Yankees","New York Giants","Chicago Cubs","Detroit Tigers"],"s":{"index":0}},{"k":"choice","i":"In 2004, the Red Sox won their first World Series in 86 years by sweeping which team?","t":"Curses","e":"\ud83e\uddf9","f":"Days earlier, Boston beat the Yankees after trailing 3\u20130, the first such comeback in MLB playoff history.","o":["Houston Astros","St. Louis Cardinals","Atlanta Braves","Colorado Rockies"],"s":{"index":1}},{"k":"truefalse","i":"The Chicago Cubs' 2016 World Series win was their first since 1908.","t":"Curses","e":"\ud83d\udc3b","f":"They beat Cleveland 8\u20137 in ten innings in Game 7 to end a 108-year wait.","a":true},{"k":"choice","i":"Which Yankees great, nicknamed 'The Iron Horse', played in 2,130 consecutive games?","t":"Legends","e":"\ud83d\udc0e","f":"Cal Ripken Jr. broke the streak in 1995 and eventually stretched his own run to 2,632 games.","o":["Joe DiMaggio","Mickey Mantle","Lou Gehrig","Babe Ruth"],"s":{"index":2}},{"k":"text","i":"The Cy Young Award honours the best player in each league at which position?","t":"Awards","e":"\ud83c\udfc5","f":"Cy Young himself won 511 major league games between 1890 and 1911.","s":{"accepted":["Pitcher","Pitchers","Pitching","Starting pitcher"]}},{"k":"multi","i":"Select all the events that would end a pitcher's bid for a perfect game.","t":"Perfect games","e":"\ud83d\udeab","f":"In 1956 the Yankees' Don Larsen pitched a perfect game in the World Series against Brooklyn.","o":["A walk","A strikeout","A batter hit by a pitch","A caught fly ball","A base hit"],"s":{"indices":[0,2,4]}},{"k":"number","i":"How many outs must a pitcher record to complete a nine-inning perfect game?","t":"Perfect games","e":"0\ufe0f\u20e3","f":"Each side bats until it makes three outs, and a regulation game lasts nine innings.","s":{"value":27,"tolerance":0,"min":9,"max":40,"unit":"outs"}},{"k":"order","i":"Order these baseball milestones from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"DiMaggio's streak in 1941 is one of baseball's most celebrated records.","o":["Babe Ruth hits 60 home runs in a season","Joe DiMaggio's 56-game hitting streak","Jackie Robinson's MLB debut","Hank Aaron breaks Babe Ruth's career home run record","Red Sox end their 86-year title drought"]},{"k":"choice","i":"What is a home run hit with the bases loaded called?","t":"Terms","e":"\ud83d\udca5","f":"'Hitting for the cycle' means getting a single, double, triple and home run in one game.","o":["A triple play","A hat-trick","The cycle","A grand slam"],"s":{"index":3}},{"k":"choice","i":"How many balls (pitches outside the strike zone) earn a batter a walk?","t":"Rules","e":"\ud83d\udeb6","f":"The official name for a walk is a 'base on balls'.","o":["3","4","5","6"],"s":{"index":1}},{"k":"choice","i":"How far apart are the bases on a Major League Baseball diamond?","t":"Rules","e":"\ud83d\udc8e","f":"The pitcher's rubber sits 60 feet 6 inches from home plate.","o":["60 feet","90 feet","100 feet","120 feet"],"s":{"index":1}},{"k":"truefalse","i":"The World Series has been played every single year since 1903.","t":"World Series","e":"\ud83d\udcc6","f":"There was no Series in 1904, when the Giants refused to play, or in 1994 because of a players' strike.","a":false},{"k":"choice","i":"Which ballpark, opened in 1923, was nicknamed 'The House That Ruth Built'?","t":"Ballparks","e":"\ud83c\udfdf\ufe0f","f":"The original stadium was replaced by a new Yankee Stadium, built across the street, which opened in 2009.","o":["Yankee Stadium","Fenway Park","Polo Grounds","Ebbets Field"],"s":{"index":0}}]},{"slug":"ring-legends","title":"Ring Legends","tagline":"Famous fights, unbeaten records and Olympic heroes from boxing history.","emoji":"\ud83e\udd4a","gradient":["#b91c1c","#1e3a8a"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":330,"items":[{"k":"text","i":"Muhammad Ali was born with what name?","t":"Legends","e":"\ud83e\udd8b","f":"He changed his name in 1964, shortly after first winning the world heavyweight title.","s":{"accepted":["Cassius Clay","Cassius Marcellus Clay","Cassius Marcellus Clay Jr","Cassius Clay Jr","Clay","Cassius"]}},{"k":"choice","i":"In which city did Muhammad Ali face George Foreman in the 1974 'Rumble in the Jungle'?","t":"Big Fights","e":"\ud83c\udf0d","f":"Ali regained the heavyweight title by letting Foreman tire himself out, a tactic he called 'rope-a-dope'.","o":["Kinshasa","Lagos","Nairobi","Accra"],"s":{"index":0}},{"k":"choice","i":"The 1975 'Thrilla in Manila' was Muhammad Ali's third fight against which rival?","t":"Big Fights","e":"\ud83d\udd14","f":"Ali won after Frazier's corner stopped the fight before the 15th round.","o":["George Foreman","Ken Norton","Joe Frazier","Sonny Liston"],"s":{"index":2}},{"k":"choice","i":"Boxing's modern rules, which made gloves compulsory, are named after which British nobleman?","t":"Rules","e":"\ud83d\udcdc","f":"They were actually written by Welsh sportsman John Graham Chambers and published in 1867.","o":["Duke of Wellington","Earl of Sandwich","Lord Lonsdale","Marquess of Queensberry"],"s":{"index":3}},{"k":"number","i":"Rocky Marciano retired as heavyweight champion with a perfect record. How many professional fights did he win?","t":"Unbeaten","e":"\ud83d\udcaf","f":"He retired in 1956 without a single loss or draw on his record.","s":{"value":49,"tolerance":0,"min":30,"max":60,"unit":"fights"}},{"k":"number","i":"How old was Mike Tyson in 1986 when he became the youngest world heavyweight champion in history?","t":"Record Breakers","e":"\u26a1","f":"He won the WBC title by beating Trevor Berbick in November 1986.","s":{"value":20,"tolerance":0,"min":14,"max":30,"unit":"years"}},{"k":"order","i":"Order these boxing weight classes from lightest to heaviest.","t":"Weight Classes","e":"\u2696\ufe0f","f":"Flyweights weigh no more than 112 lb (50.8 kg), while middleweights can reach 160 lb (72.6 kg).","o":["Flyweight","Bantamweight","Featherweight","Welterweight","Middleweight"]},{"k":"choice","i":"At which Olympic Games did a young Muhammad Ali win light-heavyweight gold?","t":"Olympics","e":"\ud83e\udd47","f":"He was just 18 and made his professional debut less than two months later.","o":["Rome 1960","Melbourne 1956","Tokyo 1964","Mexico City 1968"],"s":{"index":0}},{"k":"truefalse","i":"Women's boxing became an Olympic medal event for the first time at Beijing 2008.","t":"Olympics","e":"\ud83e\udd4a","f":"It arrived at London 2012, where Britain's Nicola Adams won the first Olympic women's flyweight title.","a":false},{"k":"multi","i":"Select all the boxers who won an Olympic gold medal.","t":"Olympics","e":"\ud83c\udfc5","f":"Holyfield left Los Angeles 1984 with a bronze medal after a disputed disqualification.","o":["Joe Frazier","Mike Tyson","George Foreman","Evander Holyfield","Lennox Lewis","Rocky Marciano"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which boxer regained the world heavyweight title in 1994 at the age of 45?","t":"Comebacks","e":"\ud83d\udd04","f":"He beat Michael Moorer, 20 years after first losing the title to Muhammad Ali.","o":["Larry Holmes","George Foreman","Evander Holyfield","Lennox Lewis"],"s":{"index":1}},{"k":"truefalse","i":"Joe Frazier handed Muhammad Ali his first professional defeat in the 1971 'Fight of the Century'.","t":"Big Fights","e":"\ud83d\uddfd","f":"The bout at New York's Madison Square Garden went the full 15 rounds.","a":true},{"k":"order","i":"Order these boxers by when they first became world heavyweight champion, from earliest to latest.","t":"Champions","e":"\ud83d\udc51","f":"Foreman took the title from Frazier in Kingston, Jamaica, in 1973.","o":["Rocky Marciano","Muhammad Ali","Joe Frazier","George Foreman","Mike Tyson"]},{"k":"choice","i":"In boxing, what does 'TKO' stand for?","t":"Terms","e":"\ud83d\udcd6","f":"A referee can call it when one boxer can no longer safely continue, ending the bout early.","o":["Total knockout","Timed knockout","Title knockout","Technical knockout"],"s":{"index":3}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'aae12ed20e440bf30021422c1a259eea' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 7'; end $q$;
do $q$ declare d text := $d$[{"slug":"snow-and-ice","title":"Snow & Ice Showdown","tagline":"Slaloms, sleds and stones: how well do you know your winter sports?","emoji":"\u26f7\ufe0f","gradient":["#0e7490","#6d28d9"],"categories":["sports","olympics"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":331,"items":[{"k":"choice","i":"In which alpine skiing event are the gates set closest together, demanding the quickest turns?","t":"Alpine skiing","e":"\ud83d\udea9","f":"Skiers knock the flexible gate poles aside with their shins, hands and pole guards as they pass.","o":["Giant slalom","Super-G","Downhill","Slalom"],"s":{"index":3}},{"k":"truefalse","i":"In Olympic slalom and giant slalom, only the faster of each skier's two runs counts.","t":"Alpine skiing","e":"\u23f1\ufe0f","f":"The two run times are added together, and the second run is set on a different course on the same slope.","a":false},{"k":"order","i":"Order these alpine skiing events from slowest to fastest.","t":"Alpine skiing","e":"\ud83d\udca8","f":"Downhill racers can top 130 km/h, and each gets just one run to set a time.","o":["Slalom","Giant slalom","Super-G","Downhill"]},{"k":"choice","i":"Biathlon combines cross-country skiing with which other discipline?","t":"Biathlon","e":"\ud83c\udfbf","f":"Biathletes shoot at targets 50 metres away, and the prone targets are just 4.5 cm wide.","o":["Rifle shooting","Archery","Ski jumping","Snowshoe running"],"s":{"index":0}},{"k":"text","i":"In curling, what is the name of the circular target that teams aim their stones at?","t":"Curling","e":"\ud83e\udd4c","f":"The very centre of the target is called the button.","s":{"accepted":["House","The house"]}},{"k":"number","i":"In standard four-player curling, how many stones does each team deliver in one end?","t":"Curling","e":"\ud83e\udd4c","f":"Many Olympic curling stones are made from granite quarried on Ailsa Craig, a tiny island off Scotland.","s":{"value":8,"tolerance":0,"min":2,"max":20,"unit":"stones"}},{"k":"choice","i":"In which sliding sport do athletes race head-first, lying face down on a small sled?","t":"Sliding","e":"\ud83d\udef7","f":"Sliders can reach around 130 km/h with their chins just centimetres above the ice.","o":["Luge","Skeleton","Bobsleigh","Ski cross"],"s":{"index":1}},{"k":"truefalse","i":"In luge, athletes slide feet-first while lying on their backs.","t":"Sliding","e":"\ud83d\udef7","f":"Lugers steer with tiny pressures from their calves and shoulders, as the sled has no brakes.","a":true},{"k":"choice","i":"In bobsleigh, which crew member sits at the front and steers the sled?","t":"Sliding","e":"\ud83e\uddca","f":"The athlete at the back pulls the brake only after the sled has crossed the finish line.","o":["The brakeman","The side pusher","The pilot","The navigator"],"s":{"index":2}},{"k":"choice","i":"Which two disciplines make up Nordic combined?","t":"Nordic","e":"\ud83c\udfd4\ufe0f","f":"In the 'Gundersen' format, the ski jump winner starts the cross-country race first, with rivals chasing.","o":["Biathlon and slalom","Ski jumping and downhill","Cross-country skiing and shooting","Ski jumping and cross-country skiing"],"s":{"index":3}},{"k":"multi","i":"Select all the sports that were on the programme of the first Winter Olympics, at Chamonix in 1924.","t":"Olympic history","e":"\ud83c\udfc5","f":"American Charles Jewtraw won the first ever Winter Olympic gold medal, in the 500 m speed skating.","o":["Luge","Bobsleigh","Curling","Snowboarding","Ski jumping"],"s":{"indices":[1,2,4]}},{"k":"order","i":"Order these sports by their first appearance at the Winter Olympics, from earliest to latest.","t":"Olympic history","e":"\ud83d\udcc5","f":"Skeleton was held in 1928 and 1948, both times at St. Moritz, then returned for good in 2002.","o":["Skeleton","Alpine skiing","Luge","Snowboarding"]},{"k":"choice","i":"Besides distance, what else earns points in ski jumping?","t":"Ski jumping","e":"\ud83c\udfbf","f":"Judges look for a steady flight and a 'telemark' landing, with one foot ahead of the other.","o":["Style marks from the judges","Speed on the in-run","Height above the hill","Number of somersaults"],"s":{"index":0}},{"k":"text","i":"Modern ski jumpers spread their skis into the shape of which letter during flight?","t":"Ski jumping","e":"\ud83c\udfbf","f":"Sweden's Jan Bokl\u00f6v popularised the style in the late 1980s, and it gives more lift than parallel skis.","s":{"accepted":["V","V-style","V shape","The letter V"]}}]},{"slug":"sport-origins-passport","title":"Sport Origins Passport","tagline":"Stamp your passport: where were the world's favourite sports born?","emoji":"\ud83c\udf0d","gradient":["#ea580c","#9d174d"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":332,"items":[{"k":"text","i":"In which US city did James Naismith invent basketball?","t":"Inventions","e":"\ud83c\udfc0","f":"The first games used peach baskets as goals, so the ball had to be fetched out after every score.","s":{"accepted":["Springfield","Springfield, Massachusetts","Springfield Massachusetts","Springfield, MA"]}},{"k":"choice","i":"Volleyball was invented at a YMCA in Massachusetts. What was its original name?","t":"Inventions","e":"\ud83c\udfd0","f":"Inventor William G. Morgan designed it as a gentler indoor game than basketball for older members.","o":["Netball","Mintonette","Bounceball","Skyball"],"s":{"index":1}},{"k":"choice","i":"Rugby football takes its name from a school in which country?","t":"Origins","e":"\ud83c\udfc9","f":"The Rugby World Cup trophy is called the Webb Ellis Cup, after a pupil linked to the game's legendary beginning.","o":["Scotland","Wales","Ireland","England"],"s":{"index":3}},{"k":"choice","i":"Which martial art, now an Olympic sport, was founded in Japan by Jigoro Kano?","t":"Martial arts","e":"\ud83e\udd4b","f":"Kano's school in Tokyo, the Kodokan, is still the world headquarters of the sport.","o":["Karate","Aikido","Judo","Kendo"],"s":{"index":2}},{"k":"choice","i":"Which country is known as the home of modern golf?","t":"Origins","e":"\u26f3","f":"The Old Course at St Andrews helped make 18 holes the standard length of a round.","o":["Scotland","Ireland","Netherlands","England"],"s":{"index":0}},{"k":"number","i":"In what year was the first organised indoor ice hockey game played, in Montreal?","t":"Origins","e":"\ud83c\udfd2","f":"It was played at the Victoria Skating Rink with a flat wooden disc instead of a ball.","s":{"value":1875,"tolerance":0,"min":1840,"max":1920,"unit":""}},{"k":"choice","i":"Table tennis began as an after-dinner parlour game in which country?","t":"Origins","e":"\ud83c\udfd3","f":"The name 'Ping-Pong' was registered as a trademark by an English sports-goods company.","o":["England","China","Japan","Sweden"],"s":{"index":0}},{"k":"text","i":"Badminton's modern rules were shaped in England from a game played in India. What was that Indian game called?","t":"Origins","e":"\ud83c\udff8","f":"The sport takes its name from Badminton House, the Duke of Beaufort's estate in Gloucestershire.","s":{"accepted":["Poona","Pune"]}},{"k":"multi","i":"Select all the sports that were first developed in England.","t":"Origins","e":"\ud83e\udded","f":"Squash was born at Harrow School around 1830, when pupils hit balls against the school walls.","o":["Squash","Basketball","Cricket","Judo","Lawn tennis"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these sports from oldest to newest by when they were invented.","t":"Inventions","e":"\u23f3","f":"Basketball and volleyball were both created at YMCAs in Massachusetts, only a few years apart.","o":["Judo","Basketball","Volleyball","Wheelchair rugby"]},{"k":"order","i":"Order these sports by their Olympic medal debut, from earliest to latest.","t":"Olympic debuts","e":"\ud83c\udfc5","f":"Breaking, better known as breakdancing, made its Olympic debut at Paris 2024.","o":["Table tennis","Beach volleyball","Taekwondo","Rugby sevens","Breaking"]},{"k":"truefalse","i":"Lacrosse traces its roots to games played by Indigenous peoples of North America.","t":"Origins","e":"\ud83e\udd4d","f":"Lacrosse is Canada's official national summer sport, while ice hockey is its national winter sport.","a":true},{"k":"truefalse","i":"Taekwondo originated in China.","t":"Martial arts","e":"\ud83c\udf0f","f":"Taekwondo comes from Korea, and its name roughly means 'the way of the foot and fist'.","a":false},{"k":"choice","i":"Curling, played by sliding granite stones across the ice, began in which country?","t":"Origins","e":"\ud83e\udd4c","f":"It is nicknamed the 'roaring game' because of the rumbling sound the stones make as they travel.","o":["Canada","Switzerland","Norway","Scotland"],"s":{"index":3}}]},{"slug":"portuguese-sporting-stars","title":"Portuguese Sporting Stars","tagline":"From the Black Panther to Euro 2016 heroes: how well do you know Portugal's greats?","emoji":"\ud83c\uddf5\ud83c\uddf9","gradient":["#047857","#be123c"],"categories":["football","sports"],"countries":["PT"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":333,"items":[{"k":"number","i":"How many goals did Eus\u00e9bio score at the 1966 World Cup, finishing as top scorer?","t":"World Cup","e":"\u26bd","f":"Four of them came in a 5\u20133 quarter-final win over North Korea, after Portugal had trailed 3\u20130.","s":{"value":9,"tolerance":0,"min":0,"max":15,"unit":"goals"}},{"k":"choice","i":"Which Lisbon club plays its home games at the Est\u00e1dio Jos\u00e9 Alvalade?","t":"Clubs","e":"\ud83c\udfdf\ufe0f","f":"The current stadium opened in 2003 and hosted the 2005 UEFA Cup final, which Sporting lost to CSKA Moscow.","o":["Benfica","Belenenses","Sporting CP","Estoril"],"s":{"index":2}},{"k":"text","i":"Who scored Portugal's extra-time winner against France in the Euro 2016 final?","t":"Euro 2016","e":"\ud83c\udfc6","f":"The 1\u20130 win in Saint-Denis came after captain Cristiano Ronaldo had limped off injured in the first half.","s":{"accepted":["\u00c9der","Eder","\u00c9derzito","Ederzito"]}},{"k":"choice","i":"Which team did Portugal beat in the first UEFA Nations League final in 2019?","t":"Nations League","e":"\ud83e\udd47","f":"Gon\u00e7alo Guedes scored the only goal of the final, which was played on home soil in Porto.","o":["Netherlands","England","Switzerland","Spain"],"s":{"index":0}},{"k":"truefalse","i":"Lu\u00eds Figo won the Ballon d'Or in 2000, the year he moved from Barcelona to Real Madrid.","t":"Ballon d'Or","e":"\u2b50","f":"His transfer between the fierce rivals set a world-record fee at the time.","a":true},{"k":"multi","i":"Select all the Portuguese athletes who won the Olympic marathon.","t":"Marathon","e":"\ud83c\udfc3","f":"Lopes won in Los Angeles in 1984 aged 37, giving Portugal its first Olympic gold; Mota won in Seoul in 1988.","o":["Rosa Mota","Nelson \u00c9vora","Carlos Lopes","Francis Obikwelu","Naide Gomes"],"s":{"indices":[0,2]}},{"k":"choice","i":"FC Porto's nickname and the name of its stadium both come from which creature?","t":"Clubs","e":"\ud83c\udfdf\ufe0f","f":"Porto play at the Est\u00e1dio do Drag\u00e3o, while Benfica are the Eagles and Sporting are the Lions.","o":["Eagle","Dragon","Lion","Wolf"],"s":{"index":1}},{"k":"multi","i":"Select all the Portuguese clubs that have won the European Cup or Champions League.","t":"European Cup","e":"\u2b50","f":"Benfica won it in 1961 and 1962, and Porto in 1987 and 2004.","o":["Benfica","Sporting CP","FC Porto","Braga","Boavista"],"s":{"indices":[0,2]}},{"k":"order","i":"Order these Portuguese clubs from oldest to youngest by founding year.","t":"Clubs","e":"\ud83d\udcdc","f":"Porto date from 1893, Benfica from 1904, Sporting from 1906 and Braga from 1921.","o":["FC Porto","Benfica","Sporting CP","Braga"]},{"k":"truefalse","i":"Portugal won Euro 2004 on home soil.","t":"Euro 2004","e":"\ud83d\ude2e","f":"Greece beat them 1\u20130 in the final in Lisbon with an Angelos Charisteas header, having also won the opening game against the hosts.","a":false},{"k":"choice","i":"Cristiano Ronaldo was born on which Portuguese island?","t":"Birthplaces","e":"\ud83c\udfdd\ufe0f","f":"The airport in the island's capital, Funchal, was renamed in his honour in 2017.","o":["S\u00e3o Miguel","Porto Santo","Terceira","Madeira"],"s":{"index":3}},{"k":"choice","i":"Where did Portugal finish at the 1966 World Cup in England?","t":"World Cup","e":"\ud83c\udf0d","f":"They beat the Soviet Union 2\u20131 in the third-place match at Wembley, with goals from Eus\u00e9bio and Jos\u00e9 Torres.","o":["Third","Runners-up","Fourth","Quarter-finals"],"s":{"index":0}},{"k":"choice","i":"Who coached Portugal to the Euro 2016 title?","t":"Coaches","e":"\ud83d\udccb","f":"Santos also led Portugal to victory in the first Nations League in 2019.","o":["Jos\u00e9 Mourinho","Fernando Santos","Carlos Queiroz","Luiz Felipe Scolari"],"s":{"index":1}},{"k":"order","i":"Order these Portuguese sporting moments from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Portugal debuted at the 1966 World Cup, Ribeiro won in Atlanta in 1996, Euro 2004 was held in Portugal and the title came in 2016.","o":["Portugal play at their first World Cup","Fernanda Ribeiro wins Olympic 10,000 m gold","Portugal host the European Championship","Portugal win the European Championship"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'fe3256418b9ba89c23de5e23ecd4cb80' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 8'; end $q$;
do $q$ declare d text := $d$[{"slug":"ballon-dor-history","title":"Ballon d'Or Through Time","tagline":"Golden balls from 1956 to 2023: legends, surprises and the women's award.","emoji":"\ud83c\udfc5","gradient":["#a16207","#7c2d12"],"categories":["football","sports","history"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":334,"items":[{"k":"choice","i":"Who won the very first Ballon d'Or, in 1956?","t":"Origins","e":"\ud83c\udfa9","f":"Matthews was 41 years old and playing for Blackpool when he won it.","o":["Alfredo Di St\u00e9fano","Raymond Kopa","Ferenc Pusk\u00e1s","Stanley Matthews"],"s":{"index":3}},{"k":"text","i":"Which magazine created the Ballon d'Or in 1956?","t":"Origins","e":"\ud83d\udcf0","f":"The idea is credited to the magazine's editor Gabriel Hanot.","s":{"accepted":["France Football","France-Football"]}},{"k":"choice","i":"In 1963, which goalkeeper won the Ballon d'Or?","t":"Goalkeepers","e":"\ud83e\udde4","f":"The Ballon d'Or prize for the best goalkeeper, launched in 2019, is named the Yashin Trophy.","o":["Lev Yashin","Gordon Banks","Dino Zoff","Gyula Grosics"],"s":{"index":0}},{"k":"choice","i":"In 1995, the first year non-European players became eligible, who won the Ballon d'Or?","t":"Firsts","e":"\ud83c\udf0d","f":"The Liberian striker was playing for AC Milan and became the first African winner.","o":["J\u00fcrgen Klinsmann","George Weah","Jari Litmanen","Paolo Maldini"],"s":{"index":1}},{"k":"number","i":"In what year did Johan Cruyff win his first Ballon d'Or?","t":"Legends","e":"\ud83d\udcc6","f":"He won again in 1973 and 1974, becoming the first player to collect three.","s":{"value":1971,"tolerance":0,"min":1960,"max":1990,"unit":""}},{"k":"order","i":"Order these Ballon d'Or winners by the year they won it, from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Nedv\u011bd was the first Czech-born winner since Czechoslovakia's Josef Masopust in 1962.","o":["Eus\u00e9bio","George Best","Paolo Rossi","Hristo Stoichkov","Pavel Nedv\u011bd"]},{"k":"choice","i":"Which Dutch striker won the Ballon d'Or in 1988, 1989 and 1992?","t":"Legends","e":"\ud83d\udfe0","f":"A persistent ankle injury meant he played his last match in 1993, aged just 28.","o":["Ruud Gullit","Frank Rijkaard","Marco van Basten","Dennis Bergkamp"],"s":{"index":2}},{"k":"truefalse","i":"Luka Modri\u0107's 2018 win ended a ten-year run in which only Lionel Messi and Cristiano Ronaldo won the Ballon d'Or.","t":"Modern era","e":"\ud83c\udfc5","f":"That same year he captained Croatia to their first World Cup final.","a":true},{"k":"truefalse","i":"A men's Ballon d'Or was awarded in 2020.","t":"Oddities","e":"\ud83d\udeab","f":"France Football cancelled the 2020 award because of the COVID-19 pandemic.","a":false},{"k":"text","i":"Which Norwegian striker won the first women's Ballon d'Or in 2018?","t":"Women's award","e":"\ud83d\udc51","f":"She was playing for French club Lyon when she received the award.","s":{"accepted":["Ada Hegerberg","Hegerberg"]}},{"k":"choice","i":"Which Brazilian won the Ballon d'Or in 2007 while playing for AC Milan?","t":"Legends","e":"\u2b50","f":"That same year he won the Champions League with Milan, beating Liverpool in Athens.","o":["Ronaldinho","Rivaldo","Ronaldo","Kak\u00e1"],"s":{"index":3}},{"k":"multi","i":"Select all the players who won the Ballon d'Or in the 1970s.","t":"1970s","e":"\ud83d\udcfa","f":"Keegan won it in both 1978 and 1979 while playing for Hamburg.","o":["Ruud Gullit","Lothar Matth\u00e4us","Oleg Blokhin","Kevin Keegan","Franz Beckenbauer","Bobby Charlton"],"s":{"indices":[2,3,4]}},{"k":"choice","i":"In 1967, which Hungarian forward won the Ballon d'Or?","t":"Legends","e":"\ud83d\udfe2","f":"Albert spent his whole club career at Ferencv\u00e1ros in Budapest.","o":["Fl\u00f3ri\u00e1n Albert","Ferenc Pusk\u00e1s","Lajos Tichy","S\u00e1ndor Kocsis"],"s":{"index":0}},{"k":"number","i":"In what year did Zinedine Zidane win the Ballon d'Or?","t":"Legends","e":"\ud83c\udf96\ufe0f","f":"Zidane later coached Real Madrid to three Champions League titles in a row, from 2016 to 2018.","s":{"value":1998,"tolerance":0,"min":1985,"max":2006,"unit":""}}]},{"slug":"ice-hockey-heroes","title":"Ice Hockey Heroes","tagline":"Pucks, power plays and Olympic miracles: lace up for a frozen showdown.","emoji":"\ud83c\udfd2","gradient":["#0284c7","#312e81"],"categories":["sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":335,"items":[{"k":"choice","i":"Lord Stanley, who donated the Stanley Cup, held which office?","t":"Origins","e":"\ud83c\udfa9","f":"He paid just 10 guineas for the original silver bowl in 1892.","o":["Prime Minister of Canada","Mayor of Montreal","Governor General of Canada","First president of the NHL"],"s":{"index":2}},{"k":"multi","i":"Select all the teams that made up the NHL's 'Original Six'.","t":"History","e":"6\ufe0f\u20e3","f":"The Original Six era ran from 1942 to 1967, when the league doubled in size to 12 teams.","o":["Montreal Canadiens","Philadelphia Flyers","Detroit Red Wings","Edmonton Oilers","Boston Bruins","Pittsburgh Penguins"],"s":{"indices":[0,2,4]}},{"k":"number","i":"Which jersey number did the NHL retire for every team in honour of Wayne Gretzky?","t":"Legends","e":"\ud83d\udc55","f":"It is the only number ever retired across the entire NHL.","s":{"value":99,"tolerance":0,"min":10,"max":100,"unit":""}},{"k":"text","i":"What nickname was Wayne Gretzky famously known by?","t":"Legends","e":"\ud83c\udf1f","f":"He won four Stanley Cups with the Edmonton Oilers in the 1980s.","s":{"accepted":["The Great One","Great One"]}},{"k":"choice","i":"At the 1980 Winter Olympics, a team of American college players beat which hockey superpower in the 'Miracle on Ice'?","t":"Olympics","e":"\ud83c\uddfa\ud83c\uddf8","f":"The US won 4\u20133 at Lake Placid against a team that had won the previous four Olympic titles.","o":["Finland","Canada","Sweden","Soviet Union"],"s":{"index":3}},{"k":"truefalse","i":"The 'Miracle on Ice' was the final game the US team played at the 1980 Olympics.","t":"Olympics","e":"\ud83e\udd45","f":"The Americans still had to beat Finland two days later to clinch the gold medal.","a":false},{"k":"choice","i":"What is a regulation ice hockey puck made of?","t":"Equipment","e":"\u26ab","f":"Pucks are frozen before games so they bounce less on the ice.","o":["Vulcanized rubber","Hard plastic","Solid oak","Cork"],"s":{"index":0}},{"k":"multi","i":"Select all the terms that are used in ice hockey.","t":"Terms","e":"\ud83d\uddd2\ufe0f","f":"Icing is usually called when a player sends the puck from their own half across the opponents' goal line untouched.","o":["Wicket","Icing","Slapshot","Scrum","Face-off","Birdie"],"s":{"indices":[1,2,4]}},{"k":"choice","i":"What is a 'power play' in ice hockey?","t":"Rules","e":"\u26a1","f":"If the team with fewer players scores, it's called a short-handed goal.","o":["Having more players on the ice while an opponent serves a penalty","Scoring two goals within one minute","A game decided by a shootout","A face-off in the attacking zone"],"s":{"index":0}},{"k":"truefalse","i":"Fans traditionally throw hats onto the ice when a player scores a hat-trick.","t":"Traditions","e":"\ud83c\udfa9","f":"The term 'hat-trick' was borrowed from cricket, where it means three wickets with three balls in a row.","a":true},{"k":"order","i":"Order these periods of play from shortest to longest.","t":"Rules","e":"\u23f1\ufe0f","f":"An NHL game has three 20-minute periods of playing time.","o":["An NBA quarter","An NHL period","A rugby union half","A football (soccer) half"]},{"k":"text","i":"What brand name is commonly used for the machine that resurfaces the ice between periods?","t":"Rink life","e":"\ud83e\uddca","f":"Frank Zamboni invented the ice resurfacer in California in 1949.","s":{"accepted":["Zamboni","A Zamboni","Zamboni machine"]}},{"k":"order","i":"Order these hockey milestones from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The Stanley Cup was first awarded in 1893, long before the NHL existed.","o":["Stanley Cup first awarded","NHL founded","Original Six era begins","Miracle on Ice","Wayne Gretzky retires"]},{"k":"choice","i":"In 1988, Wayne Gretzky was traded from the Edmonton Oilers to which team?","t":"Legends","e":"\u2708\ufe0f","f":"Fans simply called it 'The Trade'; Gretzky later also played for St. Louis and the New York Rangers.","o":["New York Rangers","Los Angeles Kings","St. Louis Blues","Toronto Maple Leafs"],"s":{"index":1}}]},{"slug":"table-tennis-and-badminton","title":"Paddles & Shuttles","tagline":"Parlour-game origins, feathered shuttles and Olympic debuts: a quiz for racket pros.","emoji":"\ud83c\udff8","gradient":["#e11d48","#7c3aed"],"categories":["sports","olympics"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":336,"items":[{"k":"choice","i":"Which player won Olympic men's singles badminton gold at both Beijing 2008 and London 2012?","t":"Olympic champions","e":"\ud83e\udd47","f":"He beat Malaysia's Lee Chong Wei in both finals, and Lee took silver again at Rio 2016, losing to Chen Long.","o":["Lee Chong Wei","Taufik Hidayat","Chen Long","Lin Dan"],"s":{"index":3}},{"k":"text","i":"Badminton is named after Badminton House, the country seat of which line of English dukes?","t":"Origins","e":"\ud83c\udff0","f":"The Gloucestershire estate is also home to the famous Badminton Horse Trials.","s":{"accepted":["Beaufort","Duke of Beaufort","Dukes of Beaufort","Beauforts"]}},{"k":"number","i":"How many feathers does a regulation feathered shuttlecock have?","t":"Equipment","e":"\ud83e\udeb6","f":"The feathers, usually goose, are fixed into a cork base covered with a thin layer of leather.","s":{"value":16,"tolerance":0,"min":6,"max":30,"unit":"feathers"}},{"k":"truefalse","i":"In modern table tennis, a game is won by the first player to reach 21 points.","t":"Scoring","e":"\ud83d\udd22","f":"Games have gone to 11 points since 2001, and each player now serves twice in a row.","a":false},{"k":"number","i":"Under badminton's rally-point system, how many points normally win a game?","t":"Scoring","e":"\ud83c\udff8","f":"At 29-all, the next point wins, so no game can go beyond 30.","s":{"value":21,"tolerance":0,"min":5,"max":30,"unit":"points"}},{"k":"choice","i":"At which Olympic Games did table tennis make its debut as a medal sport?","t":"Olympics","e":"\ud83c\udf8c","f":"South Korea's Yoo Nam-kyu won the first men's singles gold on home soil.","o":["Los Angeles 1984","Seoul 1988","Barcelona 1992","Atlanta 1996"],"s":{"index":1}},{"k":"truefalse","i":"Badminton was a full Olympic medal sport at Seoul 1988.","t":"Olympics","e":"\ud83c\udff8","f":"It was a demonstration sport in 1972 and only an exhibition event in 1988, then became a medal sport at Barcelona 1992.","a":false},{"k":"choice","i":"Which Swede, nicknamed the 'Mozart of table tennis', won Olympic singles gold at Barcelona 1992?","t":"Legends","e":"\ud83c\udfbb","f":"Waldner also won the world singles title twice, in 1989 and 1997.","o":["Jan-Ove Waldner","J\u00f6rgen Persson","Mikael Appelgren","Stellan Bengtsson"],"s":{"index":0}},{"k":"choice","i":"What is the diameter of a regulation table tennis ball?","t":"Equipment","e":"\u26aa","f":"Since 2014, top-level balls have been made of plastic instead of flammable celluloid.","o":["36 mm","38 mm","40 mm","44 mm"],"s":{"index":2}},{"k":"order","i":"Order these from lightest to heaviest.","t":"Weights","e":"\u2696\ufe0f","f":"A shuttlecock weighs only about 5 grams, yet top players can smash it at well over 300 km/h.","o":["Table tennis ball","Shuttlecock","Golf ball","Tennis ball"]},{"k":"text","i":"In table tennis, what one-word term is used when a serve clips the net but lands correctly, so it is replayed?","t":"Rules","e":"\ud83d\udd01","f":"There is no limit to how many of these can happen in a row on a single serve.","s":{"accepted":["Let","A let","Let serve"]}},{"k":"multi","i":"Select all the terms that belong to table tennis.","t":"Terminology","e":"\ud83d\udde3\ufe0f","f":"The penhold grip, popular in Asia, has the bat held much like a pen.","o":["Penhold grip","Loop","Clear","Chop","Albatross"],"s":{"indices":[0,1,3]}},{"k":"choice","i":"How high is the net in table tennis?","t":"Equipment","e":"\ud83d\udccf","f":"The table itself is 2.74 m long, 1.525 m wide and stands 76 cm high.","o":["12.5 cm","15.25 cm","18 cm","22.5 cm"],"s":{"index":1}},{"k":"truefalse","i":"A badminton net is slightly higher at the posts than at the centre.","t":"Rules","e":"\ud83e\udd45","f":"It stands 1.55 m at the posts and dips to 1.524 m in the middle.","a":true}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '0e52ed11a4e130991a012a65043f9a71' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 9'; end $q$;
do $q$ declare d text := $d$[{"slug":"spins-and-somersaults","title":"Spins & Somersaults","tagline":"Axels, Lutzes and balance beams: could you sit on the judging panel?","emoji":"\u26f8\ufe0f","gradient":["#c026d3","#be123c"],"categories":["sports","olympics"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":337,"items":[{"k":"text","i":"Axel Paulsen, who gave his name to a figure skating jump, came from which country?","t":"Jump names","e":"\u26f8\ufe0f","f":"Paulsen first performed his jump at a competition in Vienna in 1882.","s":{"accepted":["Norway","Norge","Noreg","Norwegian"]}},{"k":"choice","i":"Which of the six main figure skating jumps is the only one that takes off forwards?","t":"Jumps","e":"\ud83c\udf00","f":"Canada's Vern Taylor landed the first triple version in competition, at the 1978 World Championships.","o":["Axel","Lutz","Salchow","Toe loop"],"s":{"index":0}},{"k":"choice","i":"Which jump is named after a Swedish skater who won ten world titles?","t":"Jump names","e":"\u26f8\ufe0f","f":"Ulrich Salchow also won the first Olympic men's figure skating title, at London in 1908.","o":["Loop","Salchow","Flip","Lutz"],"s":{"index":1}},{"k":"multi","i":"Select all the toe jumps, launched with help from the toe pick.","t":"Jumps","e":"\ud83e\uddb6","f":"The Lutz is named after Austrian skater Alois Lutz, who first performed it in 1913.","o":["Salchow","Lutz","Toe loop","Axel","Flip","Loop"],"s":{"indices":[1,2,4]}},{"k":"truefalse","i":"The first quadruple Axel in competition was landed by Ilia Malinin in 2022.","t":"Firsts","e":"\ud83d\ude80","f":"Malinin was just 17 when he landed it, at a competition in Lake Placid, New York.","a":true},{"k":"choice","i":"Which spin, where the skater pulls the free leg up behind and over the head, is named after a Swiss champion?","t":"Spins","e":"\ud83c\udf2a\ufe0f","f":"Denise Biellmann, the 1981 world champion, made the spin famous, though she was not the first to perform it.","o":["Camel spin","Layback spin","Biellmann spin","Sit spin"],"s":{"index":2}},{"k":"choice","i":"Which figure skating discipline is based on ballroom dancing and features no big jumps?","t":"Disciplines","e":"\ud83d\udc83","f":"It joined the Winter Olympic programme at Innsbruck in 1976.","o":["Pairs skating","Synchronised skating","Men's singles","Ice dance"],"s":{"index":3}},{"k":"number","i":"On how many apparatus do men compete in Olympic artistic gymnastics?","t":"Apparatus","e":"\ud83e\udd38","f":"The pommel horse, rings, parallel bars and horizontal bar are used only by men.","s":{"value":6,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"order","i":"Order the four women's apparatus in the official Olympic order, starting with the first.","t":"Apparatus","e":"\ud83d\udd04","f":"Men follow their own Olympic order, starting on the floor and finishing on the horizontal bar.","o":["Vault","Uneven bars","Balance beam","Floor exercise"]},{"k":"number","i":"How wide is the top of a gymnastics balance beam, in centimetres?","t":"Balance beam","e":"\ud83d\udccf","f":"The beam is 5 metres long and stands about 1.25 metres above the floor.","s":{"value":10,"tolerance":0,"min":2,"max":30,"unit":"cm"}},{"k":"choice","i":"On which apparatus did Simone Biles first have a skill named after her, in 2013?","t":"Named skills","e":"\u2728","f":"That skill is a double layout with a half twist; in 2019 she added the triple-double 'Biles II' there too.","o":["Floor exercise","Vault","Balance beam","Uneven bars"],"s":{"index":0}},{"k":"truefalse","i":"Simone Biles won four gold medals at the 2012 London Olympics.","t":"Rio 2016","e":"\ud83e\udd47","f":"She was too young for London 2012; her four golds came at Rio 2016, where she also took bronze on the balance beam.","a":false},{"k":"multi","i":"Select all the apparatus used in rhythmic gymnastics.","t":"Rhythmic","e":"\ud83e\udd38","f":"Rhythmic gymnastics has been an Olympic sport since Los Angeles 1984.","o":["Pommel horse","Hoop","Baton","Ribbon","Clubs","Rings"],"s":{"indices":[1,3,4]}},{"k":"choice","i":"Under gymnastics' open-ended Code of Points, introduced after the Athens Olympics, what is the execution score marked out of?","t":"Scoring","e":"\ud83d\udcca","f":"Brought in for 2006, it ended the era of the 'perfect 10', so winning totals now look more like 14 or 15.","o":["20","10","15","100"],"s":{"index":1}}]},{"slug":"sports-lingo","title":"Sports Lingo Lab","tagline":"Eagles, turkeys and nutmegs: can you talk like a true sports fan?","emoji":"\ud83d\udde3\ufe0f","gradient":["#9333ea","#e11d48"],"categories":["sports","language"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":338,"items":[{"k":"choice","i":"In golf, what does it mean to score an 'eagle' on a hole?","t":"Golf","e":"\ud83e\udd85","f":"A hole-in-one on a par-3 hole also counts as an eagle.","o":["One stroke over par","Two strokes under par","One stroke under par","Three strokes under par"],"s":{"index":1}},{"k":"text","i":"In golf, which bird name is given to a score of three under par on a single hole?","t":"Golf","e":"\ud83d\udc26","f":"In the USA it is often called a 'double eagle', and it is much rarer than a hole-in-one.","s":{"accepted":["Albatross","Double eagle","An albatross"]}},{"k":"order","i":"Order these units of a tennis match from smallest to largest.","t":"Tennis","e":"\ud83c\udfbe","f":"Men's singles at the Grand Slams are played as best of five sets, while most other matches are best of three.","o":["Point","Game","Set","Match"]},{"k":"choice","i":"In tennis, what is it called when the score in a game reaches 40\u201340?","t":"Tennis","e":"\ud83c\udfbe","f":"Under standard scoring, a player must then win two points in a row to take the game.","o":["Advantage","Let","Deuce","Tiebreak"],"s":{"index":2}},{"k":"choice","i":"In ten-pin bowling, what is a 'turkey'?","t":"Bowling","e":"\ud83c\udfb3","f":"Two strikes in a row are called a 'double'.","o":["Three strikes in a row","A ball that ends up in the gutter","Missing every pin in a frame","A spare in the final frame"],"s":{"index":0}},{"k":"truefalse","i":"In ten-pin bowling, a 'spare' means knocking down all ten pins with your first ball.","t":"Bowling","e":"\ud83c\udfb3","f":"That's a strike; a spare means clearing all ten pins using both balls of a frame.","a":false},{"k":"number","i":"What is the maximum score in a single game of ten-pin bowling?","t":"Bowling","e":"\ud83c\udfc6","f":"A perfect game needs 12 strikes in a row.","s":{"value":300,"tolerance":0,"min":100,"max":600,"unit":"points"}},{"k":"choice","i":"The term 'hat-trick' means achieving something three times in one game. In which sport did it begin?","t":"Word origins","e":"\ud83c\udfa9","f":"In 1858 cricketer H. H. Stephenson took three wickets with three balls and was given a hat to celebrate.","o":["Football","Ice hockey","Baseball","Cricket"],"s":{"index":3}},{"k":"text","i":"In basketball, what is the name for a shot where a player jumps and forces the ball down through the hoop from above?","t":"Basketball","e":"\ud83c\udfc0","f":"Dunking was banned in US college basketball from 1967 to 1976.","s":{"accepted":["Slam dunk","Dunk","Slam-dunk","Slamdunk","Slam"]}},{"k":"choice","i":"In which sport would you hit a 'home run'?","t":"Bat and ball","e":"\ud83c\udfdf\ufe0f","f":"A home run hit with all three bases occupied is called a 'grand slam' and scores four runs.","o":["Cricket","Baseball","Lacrosse","Golf"],"s":{"index":1}},{"k":"multi","i":"Select all the terms used in cricket.","t":"Cricket","e":"\ud83c\udfcf","f":"An 'over' is a set of six balls bowled by the same bowler, and a 'duck' is a score of zero.","o":["Wicket","Spare","Over","Deuce","Duck"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"In rugby, what is it called when a player grounds the ball over the opponents' goal line?","t":"Rugby","e":"\ud83c\udfc9","f":"The name dates from early rugby, when grounding the ball earned no points, only a 'try' at kicking a goal.","o":["Touchdown","Conversion","Try","Scrum"],"s":{"index":2}},{"k":"text","i":"In chess, what word means the king is trapped with no escape and the game is over?","t":"Chess","e":"\u265f\ufe0f","f":"The word comes from the Persian 'sh\u0101h m\u0101t', often translated as 'the king is helpless'.","s":{"accepted":["Checkmate","Mate","Check mate"]}},{"k":"choice","i":"In football, what does it mean to 'nutmeg' an opponent?","t":"Football","e":"\u26bd","f":"In French the same trick is called a 'petit pont', meaning 'little bridge'.","o":["Play the ball through their legs","Score from inside your own half","Win the ball with a sliding tackle","Chip the ball over their head"],"s":{"index":0}}]},{"slug":"czech-sporting-legends","title":"Czech Sporting Legends","tagline":"From Helsinki 1952 to Nagano 1998: how well do you know the legends of Czech sport?","emoji":"\ud83c\udde8\ud83c\uddff","gradient":["#1d4ed8","#b91c1c"],"categories":["sports","olympics"],"countries":["CZ"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":339,"items":[{"k":"multi","i":"Select all the events Emil Z\u00e1topek won at the 1952 Helsinki Olympics.","t":"Helsinki 1952","e":"\ud83c\udfc3","f":"The marathon was the first he had ever run, and he still won it by more than two minutes.","o":["1,500 m","5,000 m","10,000 m","Marathon","3,000 m steeplechase"],"s":{"indices":[1,2,3]}},{"k":"choice","i":"Emil Z\u00e1topek's tireless running style earned him which nickname?","t":"Nicknames","e":"\ud83d\udca8","f":"His wife, Dana Z\u00e1topkov\u00e1, won Olympic javelin gold in Helsinki on the same day he won the 5,000 m.","o":["The Flying Finn","The Iron Man","The Prague Express","The Czech Locomotive"],"s":{"index":3}},{"k":"truefalse","i":"Emil Z\u00e1topek won an Olympic gold medal at the 1948 London Games.","t":"London 1948","e":"\ud83c\udfc5","f":"He won the 10,000 m in London and took silver in the 5,000 m.","a":true},{"k":"number","i":"Czechoslovakia reached two men's World Cup finals. The first was in 1934; in what year was the second?","t":"World Cup","e":"\u26bd","f":"They lost 3\u20131 to Brazil in Santiago, Chile, after Josef Masopust had given them the lead.","s":{"value":1962,"tolerance":0,"min":1938,"max":1998,"unit":""}},{"k":"choice","i":"Which shirt number did Jarom\u00edr J\u00e1gr make famous?","t":"Ice hockey","e":"\ud83c\udfd2","f":"J\u00e1gr won back-to-back Stanley Cups with the Pittsburgh Penguins in 1991 and 1992 as a young star.","o":["99","66","68","87"],"s":{"index":2}},{"k":"choice","i":"Which team did the Czech Republic beat 1\u20130 in the 1998 Olympic ice hockey final in Nagano?","t":"Nagano 1998","e":"\ud83e\udd47","f":"Petr Svoboda scored the winner, and Nagano was the first Olympics where NHL stars took part.","o":["Canada","Finland","Sweden","Russia"],"s":{"index":3}},{"k":"choice","i":"Which Czech goaltender was nicknamed 'The Dominator'?","t":"Nicknames","e":"\ud83e\udd45","f":"Ha\u0161ek was the first goaltender to win the Hart Trophy as NHL MVP twice, in 1997 and 1998.","o":["Dominik Ha\u0161ek","Tom\u00e1\u0161 Vokoun","Roman \u010cechm\u00e1nek","Ond\u0159ej Pavelec"],"s":{"index":0}},{"k":"text","i":"Which Czech midfielder won the 2003 Ballon d'Or while playing for Juventus?","t":"Ballon d'Or","e":"\u26bd","f":"He was the first Czech winner since Josef Masopust in 1962, and Italian fans called him 'Furia Ceca', the Czech Fury.","s":{"accepted":["Nedv\u011bd","Nedved","Pavel Nedv\u011bd","Pavel Nedved"]}},{"k":"choice","i":"V\u011bra \u010c\u00e1slavsk\u00e1 won seven Olympic gold medals in which sport?","t":"Olympians","e":"\ud83c\udf1f","f":"She won the all-around title at both Tokyo 1964 and Mexico City 1968.","o":["Figure skating","Swimming","Gymnastics","Athletics"],"s":{"index":2}},{"k":"truefalse","i":"Ivan Lendl won the Wimbledon men's singles title at least once.","t":"Tennis","e":"\ud83c\udfbe","f":"He reached the final in 1986 and 1987 but lost both, though he won eight majors at the other Slams.","a":false},{"k":"choice","i":"At PyeongChang 2018, Ester Ledeck\u00e1 won gold in alpine skiing and in which other sport?","t":"PyeongChang 2018","e":"\u26f7\ufe0f","f":"She became the first athlete to win gold in both skiing and snowboarding at the same Winter Olympics.","o":["Biathlon","Snowboarding","Ski jumping","Speed skating"],"s":{"index":1}},{"k":"number","i":"To the nearest metre, how far was Jan \u017delezn\u00fd's javelin world record, set in 1996?","t":"Javelin","e":"\ud83c\udfaf","f":"His 98.48 m throw in Jena still stood at the end of 2024, and he won three straight Olympic titles from 1992 to 2000.","s":{"value":98,"tolerance":0,"min":80,"max":110,"unit":"m"}},{"k":"order","i":"Order these Czech players by when they first won the Wimbledon singles title, earliest first.","t":"Wimbledon","e":"\ud83c\udfc6","f":"Novotn\u00e1 won in 1998, Kvitov\u00e1 in 2011 and 2014, Vondrou\u0161ov\u00e1 in 2023 and Krej\u010d\u00edkov\u00e1 in 2024.","o":["Jana Novotn\u00e1","Petra Kvitov\u00e1","Mark\u00e9ta Vondrou\u0161ov\u00e1","Barbora Krej\u010d\u00edkov\u00e1"]},{"k":"order","i":"Order these Czech sporting moments from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"\u010c\u00e1slavsk\u00e1 starred in 1968, Navratilova first won Wimbledon in 1978, Nagano came in 1998 and Ledeck\u00e1's double in 2018.","o":["V\u011bra \u010c\u00e1slavsk\u00e1 wins four golds in Mexico City","Martina Navratilova wins her first Wimbledon title","The Czech Republic win Olympic ice hockey gold in Nagano","Ester Ledeck\u00e1 wins gold in two sports at one Games"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '5b0ddc8c9bd48ae176cae36e470ac043' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 10'; end $q$;
do $q$ declare d text := $d$[{"slug":"laws-of-the-game","title":"Laws of the Game","tagline":"Offside, penalties, cards and VAR: how well do you know football's rulebook?","emoji":"\ud83d\udfe8","gradient":["#15803d","#065f46"],"categories":["football","sports"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":340,"items":[{"k":"number","i":"How far is the penalty spot from the goal line, in metres?","t":"Pitch","e":"\ud83d\udccf","f":"That's 12 yards; the penalty spot itself was first marked on pitches in 1902.","s":{"value":11,"tolerance":0,"min":5,"max":20,"unit":"m"}},{"k":"number","i":"How many minutes does a standard match last, not counting stoppage time?","t":"Timing","e":"\u23f1\ufe0f","f":"The referee adds stoppage time at the end of each half for time lost to injuries, substitutions and other delays.","s":{"value":90,"tolerance":0,"min":45,"max":120,"unit":"minutes"}},{"k":"choice","i":"At which World Cup were yellow and red cards first used?","t":"Cards","e":"\ud83d\udfe5","f":"English referee Ken Aston came up with the idea while waiting at traffic lights.","o":["1958 in Sweden","1966 in England","1970 in Mexico","1978 in Argentina"],"s":{"index":2}},{"k":"truefalse","i":"In a standard professional match, a player who has been substituted off can come back on later.","t":"Substitutions","e":"\ud83d\udd04","f":"Return substitutions are only allowed in some youth, veterans' and grassroots football.","a":false},{"k":"truefalse","i":"A goal counts as soon as part of the ball crosses the goal line.","t":"Goals","e":"\ud83e\udd45","f":"The whole ball must cross the whole line; goal-line technology made its men's World Cup debut in Brazil in 2014.","a":false},{"k":"choice","i":"How long is each period of extra time in a knockout match?","t":"Timing","e":"\u231b","f":"If the score is still level after both periods, the match usually goes to a penalty shoot-out.","o":["10 minutes","15 minutes","20 minutes","30 minutes"],"s":{"index":1}},{"k":"choice","i":"How must a player take a throw-in?","t":"Restarts","e":"\ud83d\ude4c","f":"Part of each foot must also be on the touchline or on the ground outside it.","o":["With one hand, from the shoulder","With both hands, from the chest","With both hands, underarm","With both hands, from behind and over the head"],"s":{"index":3}},{"k":"choice","i":"What does VAR stand for?","t":"Technology","e":"\ud83d\udcfa","f":"VAR made its men's World Cup debut at the 2018 tournament in Russia.","o":["Video Action Review","Video Assistant Referee","Visual Analysis Replay","Verified Assistant Ruling"],"s":{"index":1}},{"k":"choice","i":"How many yellow cards in one match add up to a sending-off?","t":"Cards","e":"\ud83d\udfe8","f":"A second yellow is followed by a red, and the team must play on with one player fewer.","o":["Two","Three","Four","Five"],"s":{"index":0}},{"k":"multi","i":"Select all the restarts from which a goal can be scored directly, with no other player touching the ball.","t":"Scoring","e":"\u26bd","f":"If a throw-in goes straight into the opponents' goal, a goal kick is awarded instead.","o":["Throw-in","Corner kick","Penalty kick","Indirect free kick","Direct free kick"],"s":{"indices":[1,2,4]}},{"k":"text","i":"Inside which marked part of the pitch may the goalkeeper handle the ball?","t":"Pitch","e":"\ud83e\udde4","f":"It stretches 16.5 m (18 yards) out from the goal line.","s":{"accepted":["Penalty area","The penalty area","Penalty box","The box","Box","18-yard box","Eighteen-yard box"]}},{"k":"multi","i":"Select all the ways a player can receive the ball directly without ever being offside.","t":"Offside","e":"\ud83d\udea9","f":"A player can also never be offside while in their own half of the pitch.","o":["From a throw-in","From a teammate's pass in open play","From a free kick","From a corner kick","From a goal kick"],"s":{"indices":[0,3,4]}},{"k":"order","i":"Order these pitch measurements from shortest to longest.","t":"Pitch","e":"\ud83d\udcd0","f":"The goal is 7.32 m wide and 2.44 m high, or 8 yards by 8 feet.","o":["Height of the goal","Width of the goal","Distance from goal line to penalty spot","Depth of the penalty area"]},{"k":"choice","i":"What is the minimum number of players a team must have on the pitch for a match to continue?","t":"Players","e":"\ud83d\udc65","f":"The same law says each team starts with no more than 11 players, one of whom must be the goalkeeper.","o":["Five","Six","Seven","Eight"],"s":{"index":2}}]},{"slug":"rugby-rumble","title":"Rugby Rumble","tagline":"Tries, trophies and World Cup legends: can you handle the oval ball?","emoji":"\ud83c\udfc9","gradient":["#166534","#b45309"],"categories":["sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":341,"items":[{"k":"choice","i":"According to legend, William Webb Ellis first picked up the ball and ran with it in 1823 at which English school?","t":"Origins","e":"\ud83c\udfeb","f":"Historians doubt the story, but the Rugby World Cup trophy is still named after him.","o":["Eton College","Harrow School","Rugby School","Winchester College"],"s":{"index":2}},{"k":"number","i":"In what year was the first Rugby World Cup held?","t":"World Cup","e":"\ud83c\udf0f","f":"Sixteen teams took part, all invited, as there was no qualifying tournament.","s":{"value":1987,"tolerance":0,"min":1960,"max":2000,"unit":""}},{"k":"choice","i":"Which nation won the first Rugby World Cup?","t":"World Cup","e":"\ud83c\udfc6","f":"The winners beat France 29\u20139 in the final at Eden Park in Auckland.","o":["Australia","France","England","New Zealand"],"s":{"index":3}},{"k":"truefalse","i":"South Africa won the 1995 Rugby World Cup on home soil.","t":"World Cup","e":"\ud83c\udf0d","f":"Joel Stransky's extra-time drop goal beat New Zealand 15\u201312 in the final in Johannesburg.","a":true},{"k":"text","i":"What is the name of the traditional M\u0101ori challenge the All Blacks perform before matches?","t":"Traditions","e":"\ud83d\udda4","f":"The best-known version, 'Ka Mate', was composed around 1820 by the M\u0101ori chief Te Rauparaha.","s":{"accepted":["Haka","The haka","Ka Mate"]}},{"k":"choice","i":"How many points is a try worth in rugby union?","t":"Scoring","e":"\ud83d\ude4c","f":"Tries were worth 4 points until 1992, and the conversion kick that follows adds 2 more.","o":["3","4","5","7"],"s":{"index":2}},{"k":"number","i":"In what year did rugby union's world governing body end the amateur era and allow players to be paid?","t":"Milestones","e":"\ud83d\udcb0","f":"The International Rugby Board made the change at a meeting in Paris in August 1995, about two months after that year's World Cup final.","s":{"value":1995,"tolerance":0,"min":1950,"max":2020,"unit":""}},{"k":"multi","i":"Select all the nations that compete in rugby's Six Nations Championship.","t":"Six Nations","e":"\ud83c\udff4","f":"Italy joined in 2000, turning the old Five Nations into the Six Nations.","o":["Italy","Argentina","Wales","South Africa","Scotland","New Zealand"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"The Calcutta Cup is contested between which two teams?","t":"Trophies","e":"\ud83e\udd48","f":"The trophy was made from melted-down silver rupees when the Calcutta Football Club in India disbanded.","o":["England and Scotland","England and Wales","Ireland and Wales","France and Italy"],"s":{"index":0}},{"k":"choice","i":"Which set piece restarts play after a knock-on, with the forwards binding together and pushing?","t":"Rules","e":"\ud83d\udcaa","f":"A rugby union scrum normally involves eight forwards from each team.","o":["Lineout","Scrum","Drop-out","Mark"],"s":{"index":1}},{"k":"order","i":"Order these rugby union scores from fewest points to most.","t":"Scoring","e":"\ud83d\udcca","f":"Since 2017, a penalty try has been worth an automatic 7 points, with no conversion needed.","o":["Conversion","Drop goal","Try","Penalty try"]},{"k":"order","i":"Order these rugby milestones from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The Calcutta Cup, first played for in 1879, is one of the oldest trophies in international rugby.","o":["The Webb Ellis legend","First Calcutta Cup match","Rugby league breaks away","First Rugby World Cup"]},{"k":"truefalse","i":"In rugby union, players may pass the ball forward with their hands.","t":"Rules","e":"\u21a9\ufe0f","f":"Passes must travel sideways or backwards, although players are allowed to kick the ball forward.","a":false},{"k":"text","i":"What is the nickname of South Africa's national rugby union team?","t":"Nicknames","e":"\ud83e\udd8c","f":"The springbok is a fast, leaping antelope found across southern Africa.","s":{"accepted":["Springboks","Springbok","The Springboks","Boks","Bokke"]}}]},{"slug":"snooker-and-darts","title":"Pots & Arrows","tagline":"Colours, checkouts and the legends of the baize and the board.","emoji":"\ud83c\udfb1","gradient":["#065f46","#9f1239"],"categories":["sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":342,"items":[{"k":"choice","i":"In which English city is the Crucible Theatre, which first hosted the World Snooker Championship in 1977?","t":"Venues","e":"\ud83c\udfad","f":"The championship itself dates back to 1927, when Joe Davis won the first edition.","o":["Leeds","Nottingham","Manchester","Sheffield"],"s":{"index":3}},{"k":"number","i":"How many points is the black ball worth in snooker?","t":"Ball Values","e":"\u26ab","f":"The black sits on its spot near the top cushion, at the opposite end from the baulk line.","s":{"value":7,"tolerance":0,"min":1,"max":10,"unit":"points"}},{"k":"order","i":"Order these snooker colours from lowest to highest value.","t":"Ball Values","e":"\ud83c\udf08","f":"Once the reds are gone, the colours must be potted in exactly this order, with the black last.","o":["Yellow","Green","Brown","Blue","Pink"]},{"k":"choice","i":"Which player, nicknamed 'The Nugget', won six world snooker titles in the 1980s?","t":"Legends","e":"\ud83e\udd47","f":"Davis played professionally until 2016 and became a well-known TV commentator.","o":["Alex Higgins","Steve Davis","Jimmy White","Dennis Taylor"],"s":{"index":1}},{"k":"text","i":"Which Scottish player won seven world snooker titles in the 1990s?","t":"Legends","e":"\ud83c\udff4","f":"In 1990, aged 21, he became the youngest world champion, a record that still stood at the end of 2024.","s":{"accepted":["Stephen Hendry","Hendry"]}},{"k":"choice","i":"In darts, what is the name of the line players must stand behind when throwing?","t":"Darts Lingo","e":"\ud83d\udccf","f":"At top level it is set 2.37 m (7 ft 9\u00bc in) from the face of the board.","o":["Oche","Crease","Baulk","Spot"],"s":{"index":0}},{"k":"number","i":"In a standard darts leg, from what score does each player count down to zero?","t":"Scoring","e":"\ud83c\udfaf","f":"Players must finish exactly on zero with a double, and the bullseye counts as one.","s":{"value":501,"tolerance":0,"min":101,"max":1001,"unit":""}},{"k":"choice","i":"How many points is the inner bullseye worth?","t":"Scoring","e":"\ud83d\udd34","f":"The ring just around it, known as the outer bull, is worth 25.","o":["25","50","60","100"],"s":{"index":1}},{"k":"choice","i":"Which darts legend is nicknamed 'The Power'?","t":"Legends","e":"\u26a1","f":"Taylor won 16 world championships, the last in 2013, and lost his final PDC world final to Rob Cross in 2018.","o":["Eric Bristow","Raymond van Barneveld","Phil Taylor","John Part"],"s":{"index":2}},{"k":"choice","i":"The 2008 PDC World Darts Championship was the first held at which north London venue?","t":"Venues","e":"\ud83c\udfaa","f":"Fans call it 'Ally Pally', and fancy dress in the crowd has become part of the festive show.","o":["Crystal Palace","Wembley Arena","Royal Albert Hall","Alexandra Palace"],"s":{"index":3}},{"k":"truefalse","i":"On a standard dartboard, the number 1 sits at the top.","t":"The Board","e":"\ud83c\udfaf","f":"The 20 sits at the top, flanked by 1 and 5, so a slightly wayward dart aimed at 20 is punished.","a":false},{"k":"multi","i":"Select all the scores that can be made with a single dart.","t":"Scoring","e":"\ud83e\uddee","f":"One dart can score 1 to 20, a double up to 40, a treble up to 60, or 25 and 50 at the centre.","o":["60","57","59","50","23","41"],"s":{"indices":[0,1,3]}},{"k":"truefalse","i":"Snooker was invented by British Army officers stationed in India in the 19th century.","t":"Origins","e":"\ud83c\udfb1","f":"An army officer named Neville Chamberlain, not the later prime minister, is credited with devising it in 1875.","a":true},{"k":"multi","i":"Select all the players who won the World Snooker Championship during the 1980s.","t":"World Champions","e":"\ud83c\udfc6","f":"Jimmy White reached six world finals between 1984 and 1994 but lost every one of them.","o":["Dennis Taylor","Jimmy White","Joe Johnson","John Parrott","Ray Reardon"],"s":{"indices":[0,2]}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '0452a7ad92bec733b8fbd065e6ce72f4' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 11'; end $q$;
do $q$ declare d text := $d$[{"slug":"action-sports","title":"Extreme Air Time","tagline":"Boards, bikes, waves and walls: how rad is your action sports knowledge?","emoji":"\ud83d\udef9","gradient":["#d97706","#7e22ce"],"categories":["sports","olympics"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":343,"items":[{"k":"number","i":"How many degrees of spin were in the trick Tony Hawk famously landed at the 1999 X Games?","t":"Skateboarding","e":"\ud83d\udef9","f":"Hawk had chased the trick for about ten years, and he finally landed it after the event's official time had run out.","s":{"value":900,"tolerance":0,"min":180,"max":1440,"unit":"\u00b0"}},{"k":"choice","i":"In skateboarding, what is an 'ollie'?","t":"Skateboarding","e":"\ud83d\udef9","f":"The trick is named after Alan 'Ollie' Gelfand, who invented it in the late 1970s.","o":["Spinning on the back wheels","Popping the board into the air without using your hands","Sliding along a rail on the board's middle","Doing a handstand on the board"],"s":{"index":1}},{"k":"choice","i":"At which Olympics did skateboarding, surfing and sport climbing all make their debut?","t":"Olympic debuts","e":"\ud83c\udfc5","f":"Because of the pandemic, those Games were actually held in the summer of 2021.","o":["Rio 2016","Paris 2024","Tokyo 2020","London 2012"],"s":{"index":2}},{"k":"truefalse","i":"Snowboarding made its Winter Olympic debut at Lillehammer 1994.","t":"Olympic debuts","e":"\ud83c\udfc2","f":"It debuted at Nagano 1998, where Canada's Ross Rebagliati won the first Olympic snowboarding gold, in giant slalom.","a":false},{"k":"number","i":"In what year were the first X Games held?","t":"Origins","e":"\ud83d\udcc5","f":"The first edition, held mainly in Rhode Island, was called the 'Extreme Games'.","s":{"value":1995,"tolerance":0,"min":1980,"max":2005,"unit":""}},{"k":"choice","i":"At which Olympics did BMX racing make its debut?","t":"Olympic debuts","e":"\ud83d\udeb2","f":"BMX racing sends up to eight riders over jumps and banked turns in short, frantic heats.","o":["Athens 2004","Sydney 2000","London 2012","Beijing 2008"],"s":{"index":3}},{"k":"text","i":"What name is given to a surfing stance with the right foot forward on the board?","t":"Surfing","e":"\ud83c\udfc4","f":"Left foot forward is called 'regular', and the same terms are used in skateboarding and snowboarding.","s":{"accepted":["Goofy","Goofy foot","Goofy-footed","Goofyfoot"]}},{"k":"choice","i":"Which surfing term means riding inside the hollow curl of a breaking wave?","t":"Surfing","e":"\ud83c\udf0a","f":"Hanging ten means riding a longboard with all ten toes curled over the nose.","o":["Getting barrelled","Wiping out","Hanging ten","Duck diving"],"s":{"index":0}},{"k":"choice","i":"How tall is the standard wall used in Olympic speed climbing?","t":"Climbing","e":"\ud83e\uddd7","f":"Every speed wall uses the same set of holds, so times can be compared anywhere in the world.","o":["8 m","15 m","25 m","40 m"],"s":{"index":1}},{"k":"text","i":"What is the name of the climbing discipline done on short walls without ropes, with crash mats below?","t":"Climbing","e":"\ud83e\uddd7","f":"Each route is called a 'problem', and climbers score by solving as many as they can.","s":{"accepted":["Bouldering","Boulder"]}},{"k":"multi","i":"Select all the skateboarding disciplines held at the Olympics.","t":"Skateboarding","e":"\ud83c\udfc5","f":"Japan's Momiji Nishiya won the first Olympic women's street title aged just 13.","o":["Vert","Street","Big air","Park","Halfpipe"],"s":{"indices":[1,3]}},{"k":"truefalse","i":"Snowboard halfpipe is a judged event, while snowboard cross is a head-to-head race.","t":"Snowboarding","e":"\ud83c\udfc2","f":"In snowboard cross, small groups of riders race down a course of jumps and banked turns at the same time.","a":true},{"k":"order","i":"Order these snowboarding events by when they joined the Winter Olympics, from earliest to latest.","t":"Snowboarding","e":"\ud83d\udcc5","f":"Shaun White won Olympic halfpipe gold three times: in 2006, 2010 and 2018.","o":["Halfpipe","Snowboard cross","Slopestyle","Big air"]},{"k":"choice","i":"Which Hawaiian, often called the father of modern surfing, also won Olympic gold in swimming?","t":"Surfing","e":"\ud83c\udfc4","f":"He won the 100 m freestyle at both the 1912 and 1920 Olympics.","o":["Eddie Aikau","Kelly Slater","Duke Kahanamoku","Laird Hamilton"],"s":{"index":2}}]},{"slug":"gear-check","title":"Gear Check","tagline":"Pucks, \u00e9p\u00e9es and shuttlecocks: can you match the kit to the sport?","emoji":"\ud83c\udf92","gradient":["#059669","#0e7490"],"categories":["sports","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":344,"items":[{"k":"choice","i":"Which sport is played with a shuttlecock?","t":"Rackets","e":"\ud83e\udeb6","f":"Shuttlecocks are also known as 'shuttles' or 'birdies'.","o":["Squash","Table tennis","Badminton","Tennis"],"s":{"index":2}},{"k":"number","i":"The classic black-and-white football, made famous by the Adidas Telstar at the 1970 World Cup, is stitched from how many panels?","t":"Balls","e":"\u26bd","f":"It has 12 black pentagons and 20 white hexagons, a pattern designed to stand out on black-and-white TV.","s":{"value":32,"tolerance":0,"min":8,"max":64,"unit":"panels"}},{"k":"choice","i":"In which sport do players hit a puck?","t":"Equipment","e":"\ud83e\uddca","f":"Pucks are often frozen before games so they slide faster and bounce less.","o":["Field hockey","Lacrosse","Curling","Ice hockey"],"s":{"index":3}},{"k":"multi","i":"Select all the types of golf club.","t":"Golf","e":"\ud83c\udfcc\ufe0f","f":"Drivers are built for long shots from the tee, irons for approach shots, and putters for rolling the ball on the green.","o":["Putter","Paddle","Driver","Cue","Iron"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"At Scottish Highland games, which piece of equipment is famously flipped end over end?","t":"Highland games","e":"\ud83d\udcaa","f":"A caber toss is judged on how straight the pole lands, not how far it goes.","o":["Caber","Javelin","Discus","Hammer"],"s":{"index":0}},{"k":"multi","i":"Select all the equipment used in curling.","t":"Curling","e":"\ud83e\udd4c","f":"Sweeping warms the ice slightly, helping the stone travel farther and straighter.","o":["Granite stone","Puck","Broom","Racket","Paddle"],"s":{"indices":[0,2]}},{"k":"choice","i":"Which game uses mallets to hit balls through hoops on a lawn?","t":"Lawn games","e":"\ud83d\udd28","f":"Polo players use mallets too, but they swing them while riding horses.","o":["Polo","Croquet","Golf","Cricket"],"s":{"index":1}},{"k":"choice","i":"In which athletics event do runners pass a baton?","t":"Athletics","e":"\ud83c\udfc3","f":"In the 4 x 100 m race, the baton must be handed over inside a marked changeover zone.","o":["Hurdles","Steeplechase","Relay","Marathon"],"s":{"index":2}},{"k":"text","i":"What do rowers use to pull their boat through the water?","t":"Water sports","e":"\ud83d\udea3","f":"Rowers sit facing backwards, away from the direction the boat is travelling.","s":{"accepted":["Oar","Oars","An oar","Scull","Sculls","Blade","Blades"]}},{"k":"choice","i":"Which athletics event involves throwing a spear-like implement?","t":"Athletics","e":"\ud83c\udfaf","f":"The men's version was redesigned in 1986 because throws were getting dangerously long.","o":["Shot put","Discus","Hammer","Javelin"],"s":{"index":3}},{"k":"text","i":"What is the name of the long stick used to strike the balls in snooker?","t":"Table games","e":"\ud83c\udfb1","f":"Players rub chalk on the tip so it grips the ball instead of slipping.","s":{"accepted":["Cue","Cue stick","Snooker cue"]}},{"k":"choice","i":"Why do rock climbers carry a chalk bag?","t":"Climbing","e":"\ud83e\uddd7","f":"Gymnasts and weightlifters use the same kind of chalk, magnesium carbonate, for grip.","o":["To mark their route on the wall","To keep their hands dry for better grip","To cool down their shoes","To measure their height"],"s":{"index":1}},{"k":"order","i":"Order this ice hockey kit from head to toe.","t":"Ice hockey","e":"\ud83c\udfd2","f":"Goaltenders wear a special mask with a metal cage to protect their face from shots.","o":["Helmet","Shoulder pads","Shin guards","Skates"]},{"k":"text","i":"In golf, what is the small peg the ball sits on for the first shot of a hole called?","t":"Golf","e":"\u26f3","f":"Tees may only be used for shots played from the teeing area, where each hole begins.","s":{"accepted":["Tee","Golf tee","A tee"]}}]},{"slug":"american-sports-culture","title":"American Sports Culture","tagline":"Bowl games, ballpark songs and halftime shows: test your US sports know-how.","emoji":"\ud83c\udfc8","gradient":["#312e81","#be185d"],"categories":["sports","culture"],"countries":["US"],"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":345,"items":[{"k":"choice","i":"Which two NFL teams traditionally host games on Thanksgiving Day?","t":"Thanksgiving","e":"\ud83e\udd83","f":"The Lions have hosted a Thanksgiving game almost every year since 1934, and the Cowboys joined the tradition in 1966.","o":["Green Bay Packers and Chicago Bears","Detroit Lions and Dallas Cowboys","New York Giants and New York Jets","Pittsburgh Steelers and Cleveland Browns"],"s":{"index":1}},{"k":"choice","i":"Which song do fans traditionally sing during baseball's seventh-inning stretch?","t":"Baseball","e":"\u26be","f":"The song was written in 1908 by Jack Norworth and Albert Von Tilzer, and mentions peanuts and Cracker Jack.","o":["Take Me Out to the Ball Game","Sweet Caroline","The Star-Spangled Banner","Centerfield"],"s":{"index":0}},{"k":"choice","i":"In March Madness, what name is given to the national semi-finals and championship game?","t":"College basketball","e":"\ud83c\udfc0","f":"The Sweet Sixteen and Elite Eight are earlier rounds, while 'The Big Dance' is a nickname for the whole tournament.","o":["The Sweet Sixteen","The Elite Eight","The Big Dance","The Final Four"],"s":{"index":3}},{"k":"number","i":"How many teams were in the field for the 2024 NCAA men's March Madness tournament?","t":"College basketball","e":"\ud83d\uddd3\ufe0f","f":"The field grew from 65 to 68 teams in 2011, when the four 'First Four' play-in games were added; it had been 64 teams from 1985.","s":{"value":68,"tolerance":0,"min":16,"max":128,"unit":"teams"}},{"k":"choice","i":"Which superstar's 1993 Super Bowl halftime show began with him standing perfectly still on stage for over a minute?","t":"Super Bowl","e":"\ud83c\udfa4","f":"Earlier halftime shows had mostly featured marching bands, and his set helped turn halftime into a pop spectacle.","o":["Prince","Bruce Springsteen","Michael Jackson","Elton John"],"s":{"index":2}},{"k":"order","i":"Order these Olympic Games held in the United States from earliest to latest.","t":"Olympics","e":"\ud83d\uddfd","f":"They came in 1904, 1960, 1996 and 2002; in all the US has hosted four Summer and four Winter Games.","o":["St. Louis Summer Games","Squaw Valley Winter Games","Atlanta Summer Games","Salt Lake City Winter Games"]},{"k":"number","i":"In what year was Title IX, the law that opened up school and college sport to women, signed in the US?","t":"Title IX","e":"\u2696\ufe0f","f":"It bans sex discrimination in federally funded education programs, and girls' participation in school sport soared afterwards.","s":{"value":1972,"tolerance":0,"min":1950,"max":2000,"unit":""}},{"k":"choice","i":"Which college football bowl game, played in Pasadena, is nicknamed 'The Granddaddy of Them All'?","t":"College football","e":"\ud83c\udfc8","f":"First played in 1902, it is the oldest bowl game and is traditionally held on New Year's Day.","o":["Orange Bowl","Sugar Bowl","Cotton Bowl","Rose Bowl"],"s":{"index":3}},{"k":"text","i":"What is the name for the pre-game parties fans hold around open vehicles in stadium parking lots?","t":"Game day","e":"\ud83d\ude97","f":"Fans grill food and play games such as cornhole, often arriving hours before kickoff.","s":{"accepted":["Tailgating","Tailgate","Tailgate party","Tailgate parties","Tailgating party","Tailgates"]}},{"k":"truefalse","i":"The World Series is open to baseball champions from leagues all around the world.","t":"Baseball","e":"\ud83c\udf0d","f":"It is contested by the champions of MLB's American and National Leagues, and was first played in 1903.","a":false},{"k":"truefalse","i":"The Harlem Globetrotters were originally founded in Chicago, not Harlem.","t":"Showtime","e":"\ud83e\udd39","f":"The exhibition team's famous warm-up tune is a whistled version of 'Sweet Georgia Brown'.","a":true},{"k":"choice","i":"Fans of which NHL team famously throw octopuses onto the ice during the playoffs?","t":"Fan traditions","e":"\ud83d\udc19","f":"The custom began in 1952, when an octopus's eight arms stood for the eight playoff wins then needed to lift the Stanley Cup.","o":["Boston Bruins","Chicago Blackhawks","Detroit Red Wings","Montreal Canadiens"],"s":{"index":2}},{"k":"multi","i":"Select all the places that are home to the national Hall of Fame for baseball or for pro American football.","t":"Halls of Fame","e":"\ud83c\udfdb\ufe0f","f":"Baseball's Hall of Fame opened in Cooperstown, New York, in 1939, and the Pro Football Hall of Fame in Canton, Ohio, in 1963.","o":["Cooperstown","Nashville","Canton","Orlando","Phoenix"],"s":{"indices":[0,2]}},{"k":"order","i":"Order these annual US sporting events as they usually fall in the calendar year, from earliest to latest.","t":"Sports calendar","e":"\ud83d\udcc5","f":"The Super Bowl is in February, March Madness ends in early April, the Derby runs in May and the World Series wraps up by early November.","o":["The Super Bowl","The March Madness title game","The Kentucky Derby","The World Series","Thanksgiving Day NFL games"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'f437d3ce6b7429fcc66b176af49f4b65' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 12'; end $q$;
do $q$ declare d text := $d$[{"slug":"copa-america-and-afcon","title":"Copa Am\u00e9rica & AFCON","tagline":"South America's oldest cup meets Africa's finest: continental football for experts.","emoji":"\ud83c\udf0e","gradient":["#0369a1","#16a34a"],"categories":["football","sports","history"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":346,"items":[{"k":"number","i":"In what year was the first official South American Championship, today's Copa Am\u00e9rica, played?","t":"Origins","e":"\ud83d\udcc5","f":"It is the oldest international continental football tournament still being played.","s":{"value":1916,"tolerance":0,"min":1890,"max":1950,"unit":""}},{"k":"choice","i":"Which nation won the first official South American Championship?","t":"Origins","e":"\ud83c\udfc6","f":"The four-team event was held in Argentina, and a 0\u20130 draw with the hosts in the last match sealed the title.","o":["Argentina","Brazil","Uruguay","Chile"],"s":{"index":2}},{"k":"truefalse","i":"The South American Championship was renamed the Copa Am\u00e9rica in 1975.","t":"Origins","e":"\ud83d\udd24","f":"That 1975 edition had no fixed host, with matches played home and away across the continent.","a":true},{"k":"choice","i":"Which country won the Copa Am\u00e9rica for the first time in 2015, as hosts?","t":"Winners","e":"\ud83c\udf89","f":"They beat Argentina on penalties in the final, then did it again at the 2016 Centenario edition.","o":["Colombia","Peru","Paraguay","Chile"],"s":{"index":3}},{"k":"choice","i":"Which nation hosted and won the 2001 Copa Am\u00e9rica without conceding a single goal?","t":"Winners","e":"\ud83e\uddf1","f":"It was their first Copa Am\u00e9rica title, sealed by Iv\u00e1n C\u00f3rdoba's header against Mexico in the final.","o":["Colombia","Peru","Ecuador","Venezuela"],"s":{"index":0}},{"k":"choice","i":"In which country was the 2024 Copa Am\u00e9rica final between Argentina and Colombia played?","t":"Finals","e":"\ud83c\udfdf\ufe0f","f":"Argentina won 1\u20130 in extra time at Hard Rock Stadium near Miami.","o":["Mexico","United States","Brazil","Ecuador"],"s":{"index":1}},{"k":"multi","i":"Select all the nations that had won the Copa Am\u00e9rica at least once by the end of 2024.","t":"Winners","e":"\u2705","f":"Bolivia's only title came as hosts in 1963; Ecuador and Venezuela were still waiting for their first.","o":["Paraguay","Venezuela","Mexico","Bolivia","Ecuador","Peru"],"s":{"indices":[0,3,5]}},{"k":"number","i":"In what year was the first Africa Cup of Nations held?","t":"Origins","e":"\ud83d\udcc5","f":"Only three teams took part, and Egypt beat Ethiopia 4\u20130 in the final.","s":{"value":1957,"tolerance":0,"min":1940,"max":1980,"unit":""}},{"k":"choice","i":"Which country hosted the first Africa Cup of Nations?","t":"Hosts","e":"\ud83c\udfdc\ufe0f","f":"The matches were played in the capital, Khartoum.","o":["Egypt","Ethiopia","Sudan","Ghana"],"s":{"index":2}},{"k":"truefalse","i":"Cameroon won three Africa Cup of Nations titles in a row, in 2006, 2008 and 2010.","t":"Winners","e":"\ud83d\udd01","f":"It was Egypt, under coach Hassan Shehata; Cameroon's back-to-back titles came in 2000 and 2002.","a":false},{"k":"choice","i":"In 2012, which country won its first Africa Cup of Nations in a final played in Libreville, Gabon?","t":"Winners","e":"\ud83d\udfe2","f":"They won the final on penalties, coached by Frenchman Herv\u00e9 Renard.","o":["Ghana","Mali","Senegal","Zambia"],"s":{"index":3}},{"k":"text","i":"Which country hosted the 2023 Africa Cup of Nations, played in early 2024, and won it?","t":"Hosts","e":"\ud83c\udfe0","f":"They beat Nigeria 2\u20131 in the final after almost being knocked out in the group stage.","s":{"accepted":["Ivory Coast","C\u00f4te d'Ivoire","Cote d'Ivoire","C\u00f4te dIvoire","Cote dIvoire"]}},{"k":"order","i":"Order these nations by their first Africa Cup of Nations title, from earliest to latest.","t":"Firsts","e":"\ud83d\udcc8","f":"Morocco's 1976 title was decided by a final group stage rather than a one-off final.","o":["Ghana","Morocco","Cameroon","Algeria","Senegal"]},{"k":"text","i":"Which Senegal forward scored the winning penalty in the shoot-out of the 2021 Africa Cup of Nations final?","t":"Finals","e":"\ud83c\udfaf","f":"Senegal beat Egypt for their first title, in a tournament played in Cameroon in early 2022.","s":{"accepted":["Sadio Man\u00e9","Sadio Mane","Man\u00e9","Mane"]}}]},{"slug":"cricket-crease","title":"At the Crease","tagline":"Urns, overs and Test-match legends: a proper examination for true cricket buffs.","emoji":"\ud83c\udfcf","gradient":["#065f46","#a16207"],"categories":["sports","history"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":347,"items":[{"k":"choice","i":"Australia's 1882 win at which English ground led to a mock obituary of English cricket and the birth of the Ashes?","t":"The Ashes","e":"\u26b1\ufe0f","f":"The Sporting Times joked that English cricket had died and its body would be cremated and taken to Australia.","o":["Lord's","Old Trafford","Headingley","The Oval"],"s":{"index":3}},{"k":"truefalse","i":"The original Ashes urn is not handed to the series winners; it is kept in the MCC Museum at Lord's.","t":"The Ashes","e":"\ud83c\udfdb\ufe0f","f":"Since the late 1990s, winning captains have lifted a larger Waterford Crystal replica instead.","a":true},{"k":"choice","i":"How many legal deliveries make up an over in modern cricket?","t":"Rules","e":"\ud83d\udd04","f":"Australia used eight-ball overs in home Tests for decades, until the late 1970s.","o":["4","6","8","10"],"s":{"index":1}},{"k":"text","i":"In cricket, what does the abbreviation LBW stand for?","t":"Rules","e":"\ud83e\uddb5","f":"A batter can be out this way when the ball would have hit the stumps but strikes their body first.","s":{"accepted":["Leg before wicket","Leg before the wicket","Leg before"]}},{"k":"number","i":"In what year was the first-ever Test match played?","t":"Test history","e":"\ud83d\udcdc","f":"Australia beat England by 45 runs in Melbourne, the exact same margin as in the Centenary Test 100 years later.","s":{"value":1877,"tolerance":0,"min":1850,"max":1920,"unit":""}},{"k":"number","i":"How many international centuries did India's Sachin Tendulkar score in his career?","t":"Legends","e":"\ud83d\udcaf","f":"He made 51 hundreds in Tests and 49 in one-day internationals before retiring in 2013.","s":{"value":100,"tolerance":0,"min":50,"max":130,"unit":"centuries"}},{"k":"truefalse","i":"In his final Test innings in 1948, Don Bradman needed just four runs for a career average of 100, and he scored them.","t":"Legends","e":"\ud83e\udd86","f":"Leg-spinner Eric Hollies bowled him second ball for nought, leaving his Test batting average at 99.94.","a":false},{"k":"choice","i":"Which team won the first men's Cricket World Cup in 1975?","t":"World Cups","e":"\ud83c\udfc6","f":"Clive Lloyd's side beat Australia in the final at Lord's and won the trophy again in 1979.","o":["Australia","England","India","West Indies"],"s":{"index":3}},{"k":"choice","i":"Which country won the first ICC World Twenty20 in 2007?","t":"Twenty20","e":"\u26a1","f":"The winners beat their arch-rivals by five runs in a tense final in Johannesburg.","o":["India","Pakistan","Sri Lanka","Australia"],"s":{"index":0}},{"k":"multi","i":"Select all the ways a batter can be dismissed in cricket.","t":"Rules","e":"\u261d\ufe0f","f":"One of the rarest is 'timed out', when a new batter takes too long to get ready to face the bowling.","o":["Stumped","Offside","Run out","Double fault","Caught","Knock-on"],"s":{"indices":[0,2,4]}},{"k":"text","i":"What is the name for an over in which the bowler concedes no runs?","t":"Terms","e":"\ud83c\udfaf","f":"If the bowler also takes a wicket in that over, it's called a 'wicket maiden'.","s":{"accepted":["Maiden","Maiden over","A maiden"]}},{"k":"order","i":"Order these cricket formats from the shortest innings to the longest.","t":"Formats","e":"\u23f3","f":"Test matches can last up to five days, with no limit on the number of overs in an innings.","o":["The Hundred","Twenty20","One Day International","Test match"]},{"k":"choice","i":"Which bowler became the first to take 800 Test wickets, reaching the mark with his final ball in Test cricket?","t":"Legends","e":"\ud83c\udf00","f":"The Sri Lankan off-spinner reached the milestone at Galle in 2010.","o":["Shane Warne","Anil Kumble","Muttiah Muralitharan","James Anderson"],"s":{"index":2}},{"k":"choice","i":"How long is a cricket pitch from stumps to stumps?","t":"The pitch","e":"\ud83d\udccf","f":"That distance equals one 'chain', an old surveying unit.","o":["20 yards","22 yards","24 yards","26 yards"],"s":{"index":1}}]},{"slug":"checkmate-champions","title":"Checkmate Champions","tagline":"Supercomputers, legendary showdowns and sneaky pawn moves: your move.","emoji":"\u265f\ufe0f","gradient":["#1e293b","#7c3aed"],"categories":["sports","puzzles"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":348,"items":[{"k":"choice","i":"What is it called when the player to move has no legal move but is not in check?","t":"Rules","e":"\ud83e\udd1d","f":"A stalemate ends the game immediately as a draw, which can rescue a player who is far behind.","o":["Stalemate","Checkmate","Zugzwang","Perpetual check"],"s":{"index":0}},{"k":"text","i":"In which city did Bobby Fischer beat Boris Spassky to become world champion in 1972?","t":"Famous Matches","e":"\ud83e\uddca","f":"Fischer became the first American to win the official world chess title.","s":{"accepted":["Reykjav\u00edk","Reykjavik"]}},{"k":"choice","i":"Which Hungarian broke Bobby Fischer's record as the youngest grandmaster in 1991, at the age of 15?","t":"Prodigies","e":"\ud83c\udded\ud83c\uddfa","f":"Polg\u00e1r competed mainly against men and peaked at No. 8 in the overall world rankings in 2005.","o":["Susan Polgar","Judit Polg\u00e1r","Maia Chiburdanidze","Hou Yifan"],"s":{"index":1}},{"k":"number","i":"In what year was the first official Chess Olympiad held, in London?","t":"Olympiads","e":"\ud83c\udf10","f":"FIDE, chess's world governing body, had been founded in Paris in 1924.","s":{"value":1927,"tolerance":0,"min":1900,"max":1960,"unit":""}},{"k":"order","i":"Order these pieces from lowest to highest standard point value.","t":"Piece Values","e":"\ud83d\udc51","f":"The king has no point value, because losing it means losing the game.","o":["Pawn","Bishop","Rook","Queen"]},{"k":"choice","i":"Which special move lets a player move the king and a rook in the same turn?","t":"Special Moves","e":"\ud83c\udff0","f":"You cannot do it out of, through or into check, or if either piece has already moved.","o":["En passant","Promotion","Fianchetto","Castling"],"s":{"index":3}},{"k":"choice","i":"What does the 'en passant' rule allow?","t":"Special Moves","e":"\u2659","f":"The capture must be made immediately on the next move, or the chance is lost.","o":["A pawn to move two squares on its very first move","A pawn to become a queen on the last rank","A pawn to capture an enemy pawn that has just advanced two squares beside it","A king to swap places with a rook"],"s":{"index":2}},{"k":"choice","i":"Which piece moves in an 'L' shape and can leap over other pieces?","t":"Piece Moves","e":"\ud83d\udc34","f":"From the centre of an empty board, it can reach up to eight different squares.","o":["Knight","Bishop","Rook","King"],"s":{"index":0}},{"k":"text","i":"The chess rating system used around the world is named after which Hungarian-American physics professor?","t":"Ratings","e":"\ud83d\udcc8","f":"FIDE adopted his system in 1970, and versions of it are now used in many other games and sports.","s":{"accepted":["Elo","Arpad Elo","\u00c1rp\u00e1d \u00c9l\u0151","\u00c9l\u0151","\u00c1rp\u00e1d Elo","Arpad El\u0151"]}},{"k":"truefalse","i":"In competitive chess, players press their clock after completing each move.","t":"Clocks","e":"\u23f1\ufe0f","f":"Run out of time and you lose, unless your opponent has no possible way to checkmate you.","a":true},{"k":"choice","i":"Which country did Boris Spassky represent in the 1972 World Championship match?","t":"Famous Matches","e":"\ud83c\udf0d","f":"Fischer won 12\u00bd\u20138\u00bd, ending a run of Soviet world champions that stretched back to 1948.","o":["Yugoslavia","Hungary","East Germany","Soviet Union"],"s":{"index":3}},{"k":"multi","i":"Select all the pieces that can move diagonally.","t":"Piece Moves","e":"\u2197\ufe0f","f":"Pawns also capture diagonally, even though they move straight ahead.","o":["Bishop","Rook","Queen","Knight","King"],"s":{"indices":[0,2,4]}},{"k":"truefalse","i":"A pawn that reaches the far side of the board must always become a queen.","t":"Promotion","e":"\u2728","f":"It can become a queen, rook, bishop or knight; choosing anything but a queen is called underpromotion.","a":false},{"k":"choice","i":"In which year did Garry Kasparov first become world champion by beating Anatoly Karpov?","t":"World Champions","e":"\ud83c\udfc6","f":"At 22, he became the youngest undisputed world champion at the time.","o":["1978","1982","1985","1990"],"s":{"index":2}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '0130c2cbb5104448e62d2b4b4d6d1b23' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array