do $q$ declare d text := $d$[{"slug":"water-world","title":"Making a Splash","tagline":"Strokes, dives and water polo: plunge into the wettest sports around.","emoji":"\ud83c\udfca","gradient":["#0284c7","#0f766e"],"categories":["sports","olympics"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":349,"items":[{"k":"order","i":"Order the strokes of an individual medley as they are swum, from first to last.","t":"Medley","e":"\ud83d\udd04","f":"Both the 200 m and 400 m individual medley are Olympic events for men and women.","o":["Butterfly","Backstroke","Breaststroke","Freestyle"]},{"k":"choice","i":"Which stroke is swum first in a medley relay?","t":"Relays","e":"\ud83c\udfca","f":"It leads off because those swimmers start in the water, which would clash with teammates diving in.","o":["Butterfly","Breaststroke","Backstroke","Freestyle"],"s":{"index":2}},{"k":"multi","i":"Select all the strokes in which swimmers must touch the wall with both hands at once at each turn and finish.","t":"Rules","e":"\ud83e\udd1a","f":"Freestyle and backstroke swimmers usually save time with a rolling tumble turn instead.","o":["Freestyle","Breaststroke","Backstroke","Butterfly"],"s":{"indices":[1,3]}},{"k":"number","i":"How high above the water is the Olympic diving platform, in metres?","t":"Diving","e":"\ud83e\udd3f","f":"Divers falling from the platform hit the water at roughly 50 km/h.","s":{"value":10,"tolerance":0,"min":1,"max":25,"unit":"m"}},{"k":"choice","i":"From what height is Olympic springboard diving contested?","t":"Diving","e":"\ud83e\udd3f","f":"A 1 m springboard event is held at World Championships, but not at the Olympics.","o":["1 m","5 m","7.5 m","3 m"],"s":{"index":3}},{"k":"truefalse","i":"In water polo, outfield players are allowed to stand on the bottom of the pool.","t":"Water polo","e":"\ud83e\udd3d","f":"Players tread water with a powerful 'eggbeater' kick to stay high 