do $q$ declare d text := $d$[{"slug":"womens-world-cup","title":"Women's World Cup Wonders","tagline":"Champions, heroes and unforgettable finals from 1991 to 2023.","emoji":"\ud83c\udf1f","gradient":["#c026d3","#4f46e5"],"categories":["football","sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":352,"items":[{"k":"choice","i":"Which country hosted the first FIFA Women's World Cup in 1991?","t":"Hosts","e":"\ud83c\udfdf\ufe0f","f":"The USA beat Norway 2\u20131 in the final, with Michelle Akers scoring both goals.","o":["China","United States","Sweden","Norway"],"s":{"index":0}},{"k":"truefalse","i":"Matches at the 1991 Women's World Cup lasted 80 minutes rather than 90.","t":"Rules","e":"\u23f1\ufe0f","f":"The tournament switched to the standard 90 minutes from 1995 onwards.","a":true},{"k":"choice","i":"Which nation won the 1995 Women's World Cup?","t":"Champions","e":"\ud83c\udfc6","f":"They beat Germany 2\u20130 in the final at the R\u00e5sunda Stadium.","o":["Germany","Norway","United States","China"],"s":{"index":1}},{"k":"text","i":"Which US defender scored the winning penalty in the 1999 final shoot-out against China, then celebrated by whipping off her shirt?","t":"Heroes","e":"\ud83d\udc55","f":"Over 90,000 fans watched at the Rose Bowl, a record for a women's sporting event at the time.","s":{"accepted":["Brandi Chastain","Chastain"]}},{"k":"truefalse","i":"The 2003 Women's World Cup was moved to Canada because of the SARS outbreak in China.","t":"Hosts","e":"\u2708\ufe0f","f":"It moved to the United States, which had also hosted in 1999, and China was given the 2007 tournament instead.","a":false},{"k":"choice","i":"Which country won both the 2003 and 2007 Women's World Cups?","t":"Champions","e":"\ud83d\udee1\ufe0f","f":"In 2007 they won the title without conceding a single goal.","o":["Sweden","Brazil","Germany","Norway"],"s":{"index":2}},{"k":"choice","i":"Which nation won the 2011 Women's World Cup, becoming the first Asian champions?","t":"Champions","e":"\ud83c\udf38","f":"They beat the USA on penalties after twice coming from behind in the final.","o":["China","North Korea","South Korea","Japan"],"s":{"index":3}},{"k":"number","i":"In what year did Carli Lloyd score a hat-trick inside 16 minutes of a Women's World Cup final?","t":"Finals","e":"\u26a1","f":"One of her goals came from the halfway line as the USA beat Japan 5\u20132.","s":{"value":2015,"tolerance":0,"min":1995,"max":2023,"unit":""}},{"k":"choice","i":"Which nation did the USA beat in the 2019 Women's World Cup final?","t":"Finals","e":"\ud83e\udd47","f":"Megan Rapinoe won both the Golden Ball and the Golden Boot at that tournament.","o":["Netherlands","Sweden","England","Germany"],"s":{"index":0}},{"k":"choice","i":"Which country won the 2023 Women's World Cup?","t":"Champions","e":"\ud83d\udd34","f":"Olga Carmona's goal gave them a 1\u20130 win over England in the final in Sydney.","o":["England","Spain","Sweden","Australia"],"s":{"index":1}},{"k":"number","i":"How many teams took part in the 2023 Women's World Cup, the first edition of that size?","t":"Format","e":"\ud83d\udd22","f":"The tournament had grown from 12 teams in 1991 to 16 in 1999 and 24 in 2015.","s":{"value":32,"tolerance":0,"min":12,"max":48,"unit":"teams"}},{"k":"text","i":"Which Brazilian forward, known by a single name, was FIFA World Player of the Year five times in a row from 2006 to 2010?","t":"Legends","e":"\ud83d\udcab","f":"She scored at five different Women's World Cups, from 2003 to 2019.","s":{"accepted":["Marta","Marta Vieira da Silva","Marta da Silva"]}},{"k":"multi","i":"Select all the players who won a Women's World Cup with the USA.","t":"Players","e":"\ud83d\udc5f","f":"Prinz won with Germany, Sawa with Japan, and Canada's Christine Sinclair never lifted the trophy.","o":["Homare Sawa","Kristine Lilly","Mia Hamm","Christine Sinclair","Birgit Prinz","Abby Wambach"],"s":{"indices":[1,2,5]}},{"k":"order","i":"Order these Women's World Cup hosts from earliest to latest tournament.","t":"Hosts","e":"\ud83d\uddfa\ufe0f","f":"The 2023 edition was the first co-hosted by two countries and the first held in the Southern Hemisphere.","o":["Sweden","Germany","Canada","France","Australia & New Zealand"]}]},{"slug":"net-gains","title":"Net Gains","tagline":"Volleyball, handball, netball and more: serve up your indoor court-sport smarts.","emoji":"\ud83c\udfd0","gradient":["#db2777","#6d28d9"],"categories":["sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":353,"items":[{"k":"choice","i":"What name did William G. Morgan originally give the game we now call volleyball?","t":"Origins","e":"\ud83d\udcdd","f":"Morgan blended elements of basketball, baseball, tennis and handball into his new game.","o":["Sphairistike","Battledore","Mintonette","Pallone"],"s":{"index":2}},{"k":"number","i":"In what year was volleyball invented?","t":"Origins","e":"\ud83d\udcc5","f":"The name 'volley ball' was suggested in 1896 by Alfred Halstead after watching an early demonstration.","s":{"value":1895,"tolerance":0,"min":1860,"max":1950,"unit":""}},{"k":"multi","i":"Select all the sports that were invented in Massachusetts.","t":"Origins","e":"\ud83d\uddfa\ufe0f","f":"Springfield and Holyoke, birthplaces of the two games, are only a few miles apart.","o":["Netball","Basketball","Handball","Volleyball","Ice hockey","Lacrosse"],"s":{"indices":[1,3]}},{"k":"truefalse","i":"Beach volleyball is played with two players per team.","t":"Beach volleyball","e":"\ud83c\udfd6\ufe0f","f":"Beach courts are smaller than indoor ones: 16 m by 8 m compared with 18 m by 9 m.","a":true},{"k":"choice","i":"In indoor volleyball, how many touches may a team use before the ball must go back over the net (a block not counting)?","t":"Volleyball rules","e":"\u270b","f":"The same player can't touch the ball twice in a row, except after a block.","o":["2","3","4","5"],"s":{"index":1}},{"k":"choice","i":"Which volleyball defensive specialist wears a different-coloured shirt from teammates?","t":"Volleyball rules","e":"\ud83d\udc55","f":"The word 'libero' is Italian for 'free'.","o":["Setter","Opposite hitter","Middle blocker","Libero"],"s":{"index":3}},{"k":"order","i":"Order these sports by when they first appeared as Olympic medal events, from earliest to latest.","t":"Olympics","e":"\ud83c\udfc5","f":"An 11-a-side outdoor version called field handball was played at the 1936 Berlin Olympics.","o":["Basketball","Indoor volleyball","Indoor handball","Beach volleyball","3x3 basketball"]},{"k":"choice","i":"How many players per side are on court in a handball match?","t":"Handball","e":"\ud83e\udd3e","f":"That's six court players plus a goalkeeper, the only player allowed to stand in the 6-metre goal area.","o":["5","6","7","9"],"s":{"index":2}},{"k":"truefalse","i":"In handball, a player may take up to five steps while holding the ball.","t":"Handball","e":"\ud83d\udc63","f":"The limit is three steps, and players may hold the ball for no more than three seconds before passing, shooting or dribbling.","a":false},{"k":"text","i":"Netball developed in 1890s England from an early version of which sport?","t":"Netball","e":"\ud83d\udd04","f":"The first Netball World Cup was held in Eastbourne, England, in 1963 and won by Australia.","s":{"accepted":["Basketball","Women's basketball"]}},{"k":"choice","i":"In netball, what do the letters 'GA' on a player's bib stand for?","t":"Netball","e":"\ud83d\udd24","f":"Netball players may not dribble or run with the ball, and must pass it within three seconds.","o":["Goal Attack","Goal Area","Guard Attack","Game Advantage"],"s":{"index":0}},{"k":"text","i":"Korfball, a sport where men and women play together on the same team, was invented in which country?","t":"World games","e":"\ud83e\uddfa","f":"Amsterdam teacher Nico Broekhuysen created it in 1902; 'korf' is Dutch for basket.","s":{"accepted":["Netherlands","The Netherlands","Holland","Dutch"]}},{"k":"choice","i":"Sepak takraw, popular in Southeast Asia, is like volleyball, but players may NOT touch the ball with which body part?","t":"World games","e":"\ud83e\uddb6","f":"The ball was traditionally woven from rattan, though modern balls are synthetic.","o":["Feet","Head","Knees","Hands"],"s":{"index":3}},{"k":"choice","i":"Futsal, an indoor relative of football, is played with how many players per side, including the goalkeeper?","t":"Futsal","e":"\u26bd","f":"Futsal uses a smaller, heavier ball that bounces much less than a normal football.","o":["4","5","6","7"],"s":{"index":1}}]},{"slug":"martial-arts-origins","title":"Martial Arts Origins","tagline":"Belts, throws and sumo rings: where did the world's great fighting arts begin?","emoji":"\ud83e\udd4b","gradient":["#ea580c","#be123c"],"categories":["sports","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":354,"items":[{"k":"text","i":"Which Japanese educator founded judo in 1882?","t":"Founders","e":"\ud83d\udc64","f":"His school, the Kodokan in Tokyo, is still the world headquarters of judo.","s":{"accepted":["Jigoro Kano","Kano","Jigor\u014d Kan\u014d","Kan\u014d Jigor\u014d","Kano Jigoro","Kan\u014d","Jigoro Kan\u014d","Jigor\u014d Kano"]}},{"k":"number","i":"In what year did judo make its Olympic debut, at the Tokyo Games?","t":"Olympics","e":"\ud83d\uddfc","f":"Dutch giant Anton Geesink won the open category, beating Japan's Akio Kaminaga.","s":{"value":1964,"tolerance":0,"min":1940,"max":1996,"unit":""}},{"k":"choice","i":"Karate developed on which island, part of an island chain that now belongs to Japan?","t":"Origins","e":"\ud83c\udfdd\ufe0f","f":"The word 'karate' means 'empty hand', reflecting fighting without weapons.","o":["Hokkaido","Okinawa","Kyushu","Shikoku"],"s":{"index":1}},{"k":"choice","i":"From which country does taekwondo come?","t":"Origins","e":"\ud83c\udf0f","f":"Taekwondo became a full Olympic medal sport at Sydney 2000.","o":["Korea","China","Thailand","Japan"],"s":{"index":0}},{"k":"choice","i":"Which combat sport is called 'the art of eight limbs' because it uses fists, elbows, knees and shins?","t":"Combat sports","e":"\ud83e\udd4a","f":"It is Thailand's national sport, and fighters traditionally perform a ritual dance, the wai kru, before a bout.","o":["Kung fu","Taekwondo","Muay Thai","Aikido"],"s":{"index":2}},{"k":"truefalse","i":"Karate made its Olympic debut at the Rio 2016 Games.","t":"Olympics","e":"\ud83e\udd4b","f":"It debuted at the Tokyo 2020 Games, held in 2021, and was not part of the programme at Paris 2024.","a":false},{"k":"choice","i":"Kung fu is a broad term for the martial arts of which country?","t":"Origins","e":"\ud83d\udc09","f":"The Shaolin Temple in Henan province is famous as a legendary birthplace of kung fu styles.","o":["Japan","Vietnam","Korea","China"],"s":{"index":3}},{"k":"order","i":"Order these belt colours from beginner to most advanced, as in most judo and karate grading systems.","t":"Belts","e":"\ud83c\udf97\ufe0f","f":"Black marks the first 'dan' grade, and many arts have further dan levels beyond it.","o":["White","Yellow","Green","Brown","Black"]},{"k":"choice","i":"In judo, what is the name of the full point that instantly wins a contest?","t":"Judo Scoring","e":"\u2705","f":"A throw that lands an opponent largely on their back with force and speed can earn it.","o":["Ippon","Waza-ari","Yuko","Hajime"],"s":{"index":0}},{"k":"choice","i":"What does the name 'judo' roughly mean in English?","t":"Meanings","e":"\ud83d\udcd6","f":"The idea is to use an opponent's strength and momentum against them.","o":["The way of the fist","The gentle way","The way of the warrior","The flowing hand"],"s":{"index":1}},{"k":"multi","i":"Select all the martial arts that originated in Japan.","t":"Origins","e":"\ud83d\uddfe","f":"Kendo, 'the way of the sword', is fought with bamboo swords called shinai.","o":["Aikido","Muay Thai","Kendo","Krav Maga","Judo","Wing Chun"],"s":{"indices":[0,2,4]}},{"k":"truefalse","i":"In sumo, a wrestler loses if any part of his body other than the soles of his feet touches the ground.","t":"Sumo","e":"\ud83e\udd3c","f":"He also loses if he steps or is pushed out of the circular ring, called the dohy\u014d.","a":true},{"k":"order","i":"Order these sumo ranks from lowest to highest.","t":"Sumo","e":"\ud83c\udfef","f":"A yokozuna cannot be demoted; one who starts losing regularly is expected to retire.","o":["Maegashira","Komusubi","Sekiwake","Ozeki","Yokozuna"]},{"k":"text","i":"What short Japanese word is commonly used for the uniform worn in judo and karate?","t":"Uniforms","e":"\ud83d\udc58","f":"Judo uniforms are made of thicker cotton than karate ones, so they survive constant gripping.","s":{"accepted":["Gi","Judogi","Karategi","Dogi","Do-gi","Keikogi"]}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '41c5cef5c7d610bc2edb1f0f881b0a9c' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 15'; end $q$;
do $q$ declare d text := $d$[{"slug":"rowing-and-sailing","title":"Oars & Sails","tagline":"Boat Races, regattas and ocean classics: are you shipshape on the water?","emoji":"\ud83d\udea3","gradient":["#2563eb","#1e1b4b"],"categories":["sports","olympics"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":355,"items":[{"k":"number","i":"In what year was the first Oxford v Cambridge Boat Race rowed?","t":"Origins","e":"\ud83d\udcc5","f":"Oxford won that first race, and it has been held almost every year since 1856.","s":{"value":1829,"tolerance":0,"min":1760,"max":1920,"unit":""}},{"k":"truefalse","i":"The Boat Race's Championship Course runs about 6.8 km on the Thames, from Putney to Mortlake.","t":"The Boat Race","e":"\ud83c\udf0a","f":"Crews race upstream, timed to ride the incoming flood tide.","a":true},{"k":"text","i":"What is the name of the crew member who steers an eight and calls the rhythm, but does not row?","t":"Crew roles","e":"\ud83d\udce3","f":"They are usually small and light, and racing rules often set a minimum weight for them.","s":{"accepted":["Coxswain","Cox","Coxwain"]}},{"k":"choice","i":"In rowing, what separates sculling from sweep rowing?","t":"Technique","e":"\ud83d\udea3","f":"An Olympic eight is a sweep boat, with each of its eight rowers pulling a single oar.","o":["Scullers face forwards; sweep rowers face backwards","Sculling is done standing up","Sweep rowing is only for single rowers","Scullers hold an oar in each hand; sweep rowers hold one"],"s":{"index":3}},{"k":"choice","i":"Steve Redgrave won Olympic gold at five consecutive Games. Which years did that run span?","t":"Legends","e":"\ud83e\udd47","f":"Redgrave was knighted in 2001, the year after his fifth gold in Sydney.","o":["1984\u20132000","1980\u20131996","1988\u20132004","1976\u20131992"],"s":{"index":0}},{"k":"truefalse","i":"Steve Redgrave won all five of his Olympic golds in the same boat class.","t":"Legends","e":"\ud83d\udea3","f":"He won in three different boat types across his five Games, including the pair with Matthew Pinsent.","a":false},{"k":"choice","i":"In 1983, which nation's challenger became the first to win the America's Cup away from the United States?","t":"America's Cup","e":"\ud83c\udfc6","f":"Australia II's secret winged keel helped end the New York Yacht Club's 132-year hold on the trophy.","o":["New Zealand","Australia","Great Britain","Italy"],"s":{"index":1}},{"k":"choice","i":"In Olympic canoe sprint, what kind of paddle do kayakers use?","t":"Paddles","e":"\ud83d\udef6","f":"Canoeists, by contrast, use a single-bladed paddle and race kneeling on one knee.","o":["A single-bladed paddle","Two oars fixed in rowlocks","A double-bladed paddle","A long pole pushed off the riverbed"],"s":{"index":2}},{"k":"text","i":"Which Thames-side town's Royal Regatta, first held in 1839, is a highlight of the English rowing summer?","t":"Regattas","e":"\ud83c\udfc1","f":"It became 'Royal' in 1851, when Prince Albert became its first royal patron.","s":{"accepted":["Henley","Henley-on-Thames","Henley on Thames","Henley Royal Regatta"]}},{"k":"multi","i":"Select all the manoeuvres in which a sailing boat turns so that the wind comes from its other side.","t":"Sailing terms","e":"\u26f5","f":"When tacking, the bow turns through the wind; in a gybe, the stern does.","o":["Reefing","Tack","Hiking out","Gybe"],"s":{"indices":[1,3]}},{"k":"order","i":"Order these rowing boats by the number of rowers, from fewest to most.","t":"Boats","e":"\ud83d\udea3","f":"An eight also carries a ninth person, who steers and directs the crew.","o":["Single scull","Double scull","Quadruple scull","Eight"]},{"k":"order","i":"Order these sailing events by the year they were first held, from earliest to latest.","t":"Sailing history","e":"\ud83d\udcc5","f":"The America's Cup is named after the schooner America, which won the first race around the Isle of Wight.","o":["America's Cup","Sydney to Hobart Yacht Race","Whitbread Round the World Race","Vend\u00e9e Globe"]},{"k":"choice","i":"In rowing, what does it mean to 'catch a crab'?","t":"Rowing slang","e":"\ud83d\udea3","f":"A bad one can jerk the oar so hard that it throws the rower right out of the boat.","o":["To win by the smallest possible margin","To overtake a rival on the outside","To row without a steering crew member","To get the oar blade stuck in the water mid-stroke"],"s":{"index":3}},{"k":"choice","i":"Which British sailor won Olympic gold at four consecutive Games, from Sydney 2000 to London 2012?","t":"Sailing","e":"\u26f5","f":"He also won silver at Atlanta 1996, giving him medals at five Olympics in a row.","o":["Ben Ainslie","Iain Percy","Matthew Pinsent","Shirley Robertson"],"s":{"index":0}}]},{"slug":"sports-fact-or-fiction","title":"Sports: Fact or Fiction?","tagline":"Strange but true, or total myth? Sort the sports facts from the fiction.","emoji":"\ud83e\udd14","gradient":["#4f46e5","#0d9488"],"categories":["sports","general"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"Fact or fiction?","yes_label":"Fact","no_label":"Fiction","sort":356,"items":[{"k":"truefalse","i":"Tug of war was once an Olympic sport.","t":"Olympic history","e":"\ud83e\udea2","f":"It was contested at five Summer Games, from 1900 to 1920.","a":true},{"k":"truefalse","i":"The Summer Olympics have been held in Africa.","t":"Olympic history","e":"\ud83c\udf0d","f":"Africa is the only inhabited continent that has never hosted the Summer or Winter Games.","a":false},{"k":"truefalse","i":"The official rules of tennis say the ball must be yellow.","t":"Tennis","e":"\ud83c\udfbe","f":"The rules allow white or yellow balls; Wimbledon switched to yellow in 1986 to help TV viewers.","a":false},{"k":"truefalse","i":"Golf has been played on the Moon.","t":"Space","e":"\ud83c\udf19","f":"Astronaut Alan Shepard hit two golf balls on the lunar surface during Apollo 14 in 1971.","a":true},{"k":"truefalse","i":"Olympic medals were once awarded for painting, music and literature.","t":"Olympic history","e":"\ud83c\udfa8","f":"Art competitions inspired by sport were part of the Games from 1912 to 1948.","a":true},{"k":"truefalse","i":"Football (soccer) has been played at every Summer Olympics since 1896.","t":"Football","e":"\u26bd","f":"Football was not on the programme at the first Games in 1896, or at Los Angeles 1932.","a":false},{"k":"truefalse","i":"An NBA basketball court is longer than a tennis court.","t":"Courts","e":"\ud83d\udccf","f":"An NBA court is 94 ft (28.65 m) long, while a tennis court is 78 ft (23.77 m).","a":true},{"k":"truefalse","i":"Michael Jordan never played professional baseball.","t":"Legends","e":"\ud83c\udf1f","f":"In 1994 he played minor league baseball for the Birmingham Barons before returning to the NBA.","a":false},{"k":"truefalse","i":"World Cup winners today still receive the original Jules Rimet Trophy.","t":"Trophies","e":"\ud83c\udfc6","f":"Brazil kept the Jules Rimet Trophy for good after their third title in 1970; the current trophy debuted in 1974.","a":false},{"k":"truefalse","i":"The Boston Marathon is the world's oldest annual marathon.","t":"Running","e":"\ud83c\udfc3","f":"It was first run in 1897, a year after the marathon at the first modern Olympics.","a":true},{"k":"truefalse","i":"The USA won Olympic gold in 15-a-side rugby in both 1920 and 1924.","t":"Rugby","e":"\ud83c\udfc9","f":"Rugby then vanished from the Games until rugby sevens arrived at Rio 2016.","a":true},{"k":"truefalse","i":"The Olympic flame at Olympia is traditionally lit with a match.","t":"Olympic flame","e":"\ud83d\udd25","f":"It is lit by focusing the sun's rays with a curved mirror, in a ceremony at the ancient site.","a":false},{"k":"truefalse","i":"Sumo wrestling is an Olympic sport.","t":"Martial arts","e":"\ud83e\udd3c","f":"Sumo has never been part of the Olympics, while judo, another Japanese martial art, debuted at Tokyo 1964.","a":false},{"k":"truefalse","i":"A regulation baseball is held together by 108 double stitches.","t":"Baseball","e":"\u26be","f":"The red stitches are sewn by hand around a core of cork and rubber wrapped in yarn.","a":true}]},{"slug":"legends-and-nicknames","title":"Legends and Nicknames","tagline":"Behind every great nickname is a legend. Can you put a name to the name?","emoji":"\ud83c\udff7\ufe0f","gradient":["#7c3aed","#db2777"],"categories":["sports","celebs"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":357,"items":[{"k":"text","i":"Which ice hockey legend is known as 'The Great One'?","t":"Ice hockey","e":"\ud83c\udfd2","f":"His No. 99 was retired across the entire NHL in 2000.","s":{"accepted":["Gretzky","Wayne Gretzky"]}},{"k":"choice","i":"Michael Jordan's nickname 'Air Jordan' is also the name of a shoe line launched in 1985 by which brand?","t":"Sneakers","e":"\ud83d\udc5f","f":"Jordan signed with Nike in 1984, and the Air Jordan 1 went on sale the following year.","o":["Nike","Adidas","Reebok","Converse"],"s":{"index":0}},{"k":"text","i":"Which NBA star gave himself the nickname 'Black Mamba'?","t":"NBA","e":"\ud83d\udc0d","f":"He spent his whole 20-season career with the Los Angeles Lakers and won five NBA titles.","s":{"accepted":["Kobe Bryant","Kobe","Bryant"]}},{"k":"choice","i":"Which snooker player is nicknamed 'The Rocket'?","t":"Snooker","e":"\ud83c\udfb1","f":"He earned the name for his lightning-fast style, and can play at a top level with either hand.","o":["Stephen Hendry","Steve Davis","John Higgins","Ronnie O'Sullivan"],"s":{"index":3}},{"k":"text","i":"Which Dutch athlete, who won four gold medals at the 1948 London Olympics, was nicknamed 'The Flying Housewife'?","t":"Athletics","e":"\ud83c\udfc3\u200d\u2640\ufe0f","f":"A 30-year-old mother of two at the time, she won the 100 m, 200 m, 80 m hurdles and 4 \u00d7 100 m relay.","s":{"accepted":["Fanny Blankers-Koen","Blankers-Koen","Fanny Blankers Koen","Blankers Koen","Blankers"]}},{"k":"choice","i":"Which boxer was nicknamed 'Hands of Stone'?","t":"Boxing","e":"\ud83e\udd4a","f":"The Panamanian beat Sugar Ray Leonard in Montreal in 1980, and a 2016 film about his life took his nickname as its title.","o":["Sugar Ray Leonard","Thomas Hearns","Roberto Dur\u00e1n","Marvin Hagler"],"s":{"index":2}},{"k":"text","i":"Which golfer, winner of 18 major championships, is nicknamed 'The Golden Bear'?","t":"Golf","e":"\ud83d\udc3b","f":"He won the Masters six times, the last in 1986 at the age of 46.","s":{"accepted":["Jack Nicklaus","Nicklaus"]}},{"k":"choice","i":"Which cricketer was nicknamed 'The Wall' for his rock-solid batting?","t":"Cricket","e":"\ud83e\uddf1","f":"India's Dravid retired in 2012 after scoring more than 13,000 Test runs.","o":["Sachin Tendulkar","Rahul Dravid","Sourav Ganguly","Virat Kohli"],"s":{"index":1}},{"k":"text","i":"'Der Bomber' was the nickname of which German goal machine?","t":"Football","e":"\ud83d\udca3","f":"He scored 68 goals in just 62 internationals for West Germany.","s":{"accepted":["Gerd M\u00fcller","M\u00fcller","Muller","Mueller","Gerd Muller","Gerd Mueller"]}},{"k":"choice","i":"Which Brazilian striker was nicknamed 'O Fen\u00f4meno' ('Il Fenomeno' in Italy)?","t":"Football","e":"\u26a1","f":"He won the Ballon d'Or in 1997 and 2002, and was top scorer at the 2002 World Cup.","o":["Ronaldinho","Rom\u00e1rio","Rivaldo","Ronaldo Naz\u00e1rio"],"s":{"index":3}},{"k":"truefalse","i":"'The Baltimore Bullet' was the nickname of sprinter Usain Bolt.","t":"Olympians","e":"\ud83c\udfca","f":"It belonged to swimmer Michael Phelps, who grew up in Baltimore and won 23 Olympic golds.","a":false},{"k":"choice","i":"'King Kenny' Dalglish is a legend at Liverpool and which Scottish club?","t":"Football","e":"\ud83d\udc51","f":"He joined Liverpool in 1977 to replace Kevin Keegan, and later won the league as their player-manager.","o":["Celtic","Rangers","Aberdeen","Hearts"],"s":{"index":0}},{"k":"number","i":"How many Olympic gold medals did 'The Flying Finn' Paavo Nurmi win?","t":"Athletics","e":"\ud83c\udfc3","f":"At Paris 1924 he won both the 1,500 m and the 5,000 m on the same day.","s":{"value":9,"tolerance":0,"min":0,"max":15,"unit":"golds"}},{"k":"multi","i":"Select all the nicknames that belonged to Muhammad Ali.","t":"Boxing","e":"\ud83d\udde3\ufe0f","f":"Ali was born in Louisville, Kentucky; 'The Brown Bomber' was Joe Louis and 'Smokin' Joe' was Joe Frazier.","o":["The Greatest","Sugar Ray","The Louisville Lip","The Brown Bomber","Smokin' Joe"],"s":{"indices":[0,2]}}]},{"slug":"legendary-number-tens","title":"Legendary Number Tens","tagline":"Pel\u00e9, Maradona, Zidane and more: the stories behind football's greatest icons.","emoji":"\ud83d\udd1f","gradient":["#4338ca","#0ea5e9"],"categories":["football","sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":358,"items":[{"k":"text","i":"What was Pel\u00e9's first name at birth?","t":"Names","e":"\ud83d\udcdb","f":"His parents named him after the American inventor Thomas Edison.","s":{"accepted":["Edson","Edson Arantes do Nascimento","Edison"]}},{"k":"choice","i":"Which Italian club did Diego Maradona lead to its first Serie A title in 1987?","t":"Clubs","e":"\ud83d\udc99","f":"The club's stadium was renamed Stadio Diego Armando Maradona in 2020.","o":["Roma","Lazio","Napoli","Fiorentina"],"s":{"index":2}},{"k":"number","i":"Which shirt number did Johan Cruyff famously wear for Ajax and the Netherlands?","t":"Shirts","e":"\ud83d\udc55","f":"Ajax retired that number in his honour in 2007.","s":{"value":14,"tolerance":0,"min":1,"max":23,"unit":""}},{"k":"choice","i":"Which Hungarian legend, nicknamed the 'Galloping Major', later starred for Real Madrid?","t":"Nicknames","e":"\ud83c\udf96\ufe0f","f":"Since 2009, FIFA has named its award for the year's best goal after him.","o":["S\u00e1ndor Kocsis","N\u00e1ndor Hidegkuti","Zolt\u00e1n Czibor","Ferenc Pusk\u00e1s"],"s":{"index":3}},{"k":"truefalse","i":"Eus\u00e9bio, Portugal's great striker, was born in Mozambique.","t":"Origins","e":"\ud83c\udf0d","f":"Nicknamed the 'Black Panther', he was top scorer at the 1966 World Cup with nine goals.","a":true},{"k":"choice","i":"Roberto Baggio missed the final penalty of the 1994 World Cup final shoot-out against which team?","t":"Heartbreak","e":"\ud83d\udc94","f":"Famous for his hairstyle, Baggio was nicknamed 'Il Divin Codino', the Divine Ponytail.","o":["Brazil","Argentina","Germany","Netherlands"],"s":{"index":0}},{"k":"choice","i":"In 2005, Real Madrid fans gave which Barcelona star a standing ovation at the Bernab\u00e9u?","t":"Classic moments","e":"\ud83d\udc4f","f":"He scored twice in a 3\u20130 win and was named Ballon d'Or winner later that year.","o":["Rivaldo","Ronaldinho","Samuel Eto'o","Deco"],"s":{"index":1}},{"k":"choice","i":"Which Brazilian playmaker, nicknamed the 'White Pel\u00e9', later coached Japan's national team?","t":"Nicknames","e":"\ud83e\uddd1\u200d\ud83c\udfeb","f":"Before coaching Japan, he starred for Kashima Antlers in the early years of the J.League.","o":["S\u00f3crates","Rivellino","Zico","Falc\u00e3o"],"s":{"index":2}},{"k":"choice","i":"Before joining Real Madrid in 2001, Zinedine Zidane won two Serie A titles with which club?","t":"Clubs","e":"\u26aa","f":"At Real Madrid, his left-foot volley won the 2002 Champions League final in Glasgow.","o":["AC Milan","Inter Milan","Lazio","Juventus"],"s":{"index":3}},{"k":"text","i":"Which French playmaker starred for Nancy, Saint-\u00c9tienne and Juventus and captained France to the Euro 1984 title?","t":"Captains","e":"\ud83c\udfa9","f":"He won the Ballon d'Or three years running, from 1983 to 1985.","s":{"accepted":["Michel Platini","Platini"]}},{"k":"multi","i":"Select all the legends who played for Barcelona.","t":"Clubs","e":"\ud83c\udfdf\ufe0f","f":"Cruyff later returned as coach and built Barcelona's 'Dream Team' of the early 1990s.","o":["Roberto Baggio","Ferenc Pusk\u00e1s","Zico","Eus\u00e9bio","Johan Cruyff","Diego Maradona"],"s":{"indices":[4,5]}},{"k":"order","i":"Order these legends by year of birth, from oldest to youngest.","t":"Timeline","e":"\ud83c\udf82","f":"Pusk\u00e1s was born in Budapest in 1927, 45 years before Zidane.","o":["Ferenc Pusk\u00e1s","Eus\u00e9bio","Zico","Diego Maradona","Zinedine Zidane"]},{"k":"truefalse","i":"Zico won the World Cup with Brazil.","t":"World Cup","e":"\ud83c\udfc6","f":"His dazzling 1982 Brazil side was knocked out by Italy, thanks to a Paolo Rossi hat-trick.","a":false},{"k":"number","i":"How old was Pel\u00e9 when he won his first World Cup in 1958?","t":"Prodigies","e":"\ud83c\udf1f","f":"He scored twice in the final as Brazil beat hosts Sweden 5\u20132.","s":{"value":17,"tolerance":0,"min":14,"max":30,"unit":"years"}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '835ee6fdd5cb7bb1f0e098bd082c807c' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 16'; end $q$;
do $q$ declare d text := $d$[{"slug":"trophy-cabinet","title":"Trophy Cabinet","tagline":"Jugs, jackets and silver cups: match sport's most famous prizes to their stories.","emoji":"\ud83c\udfc6","gradient":["#d97706","#9a3412"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":359,"items":[{"k":"choice","i":"The Claret Jug is presented to the winner of which championship?","t":"Silverware","e":"\ud83c\udf77","f":"Before the jug, winners received a red leather Challenge Belt.","o":["The Open Championship","The Masters","Wimbledon","The Derby"],"s":{"index":0}},{"k":"choice","i":"A Green Jacket is presented to the winner of which golf tournament?","t":"Golf","e":"\ud83e\udde5","f":"Champions may take the jacket home for a year, after which it stays at Augusta National Golf Club.","o":["US Open","The Open Championship","PGA Championship","The Masters"],"s":{"index":3}},{"k":"text","i":"The Larry O'Brien Trophy goes to the champions of which league?","t":"Named trophies","e":"\ud83c\udfc0","f":"It is named after Larry O'Brien, the league's commissioner from 1975 to 1984.","s":{"accepted":["NBA","National Basketball Association","The NBA"]}},{"k":"truefalse","i":"The Vince Lombardi Trophy shows a silver football standing in kicking position.","t":"American football","e":"\ud83c\udfc8","f":"Tiffany & Co. crafts a brand-new trophy every year, so each champion keeps one.","a":true},{"k":"choice","i":"Which country got to keep the original Jules Rimet Trophy after winning its third World Cup in 1970?","t":"Football","e":"\ud83c\udf0d","f":"Before the 1966 World Cup, the trophy was stolen in London and found a week later by a dog named Pickles.","o":["Brazil","Italy","Uruguay","West Germany"],"s":{"index":0}},{"k":"number","i":"In what year was tennis's Davis Cup first contested?","t":"Tennis","e":"\ud83c\udfbe","f":"Harvard student Dwight Davis donated the trophy, and the USA beat the British Isles in the first match.","s":{"value":1900,"tolerance":0,"min":1870,"max":1950,"unit":""}},{"k":"choice","i":"Since 1979, the USA has faced which team in golf's Ryder Cup?","t":"Golf","e":"\u26f3","f":"The event has twice been pushed back by a year, in 2001 and 2020.","o":["Great Britain and Ireland","Rest of the World","Europe","Asia-Pacific"],"s":{"index":2}},{"k":"multi","i":"Select all the trophies contested in rugby union.","t":"Rugby","e":"\ud83c\udfc9","f":"Rugby World Cup winners lift the Webb Ellis Cup, which players often nickname 'Bill'.","o":["Webb Ellis Cup","Grey Cup","Calcutta Cup","Heisman Trophy","Solheim Cup"],"s":{"indices":[0,2]}},{"k":"text","i":"The Borg-Warner Trophy, covered in sculpted faces of past winners, is presented at which famous motor race?","t":"Motorsport","e":"\ud83c\udfce\ufe0f","f":"First presented in 1936, it bears a sculpted silver face of every winner, and drivers take home a smaller replica nicknamed the 'Baby Borg'.","s":{"accepted":["Indianapolis 500","Indy 500","Indianapolis","Indy","Indy500","The Indianapolis 500","The Indy 500","Indianapolis 500 Mile Race"]}},{"k":"truefalse","i":"A brand-new Stanley Cup is made for each year's NHL champions.","t":"Ice hockey","e":"\ud83c\udfd2","f":"The same Cup is passed from champion to champion, and each winning player traditionally gets a day with it.","a":false},{"k":"order","i":"Order these trophies by when they were first awarded, from oldest to newest.","t":"Timeline","e":"\ud83d\udcc5","f":"The America's Cup is widely described as the oldest trophy in international sport.","o":["America's Cup","Claret Jug","Stanley Cup","Ryder Cup","Webb Ellis Cup"]},{"k":"choice","i":"The Commissioner's Trophy goes to the winners of which North American event?","t":"Named trophies","e":"\u26be","f":"It's the only one of the big four North American championship trophies not named after a person.","o":["Stanley Cup Final","NBA Finals","World Series","Super Bowl"],"s":{"index":2}},{"k":"choice","i":"The Thomas Cup is the men's world team championship in which sport?","t":"Team trophies","e":"\ud83c\udfc6","f":"Named after English player Sir George Thomas, it was first contested in 1948\u201349 and won by Malaya; the women's version is the Uber Cup.","o":["Squash","Badminton","Table tennis","Volleyball"],"s":{"index":1}},{"k":"number","i":"In what year did the yacht America win the race that gave the America's Cup its name?","t":"Sailing","e":"\ud83d\udee5\ufe0f","f":"The race was sailed around the Isle of Wight, off the south coast of England.","s":{"value":1851,"tolerance":0,"min":1800,"max":1920,"unit":""}}]},{"slug":"target-and-blade","title":"Target & Blade","tagline":"Foils, bows and bullseyes: a sharp-eyed quiz on fencing, archery and shooting.","emoji":"\ud83c\udff9","gradient":["#0f766e","#4338ca"],"categories":["sports","olympics"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":360,"items":[{"k":"multi","i":"Select all the weapons used in Olympic fencing.","t":"Fencing","e":"\ud83e\udd3a","f":"All three are scored electrically, with a light signalling each valid hit.","o":["Foil","Rapier","\u00c9p\u00e9e","Cutlass","Sabre","Katana"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"In foil, which area of the body is the valid target?","t":"Fencing","e":"\ud83c\udfaf","f":"Foil and sabre use 'right of way' rules to decide who scores when both fencers hit at once.","o":["The whole body","Everything above the waist, including arms and head","Only the arms and legs","The torso"],"s":{"index":3}},{"k":"text","i":"What French-derived word names the long, narrow strip on which fencing bouts take place?","t":"Fencing","e":"\ud83d\udcd0","f":"Step off the back end of it with both feet and your opponent is awarded a touch.","s":{"accepted":["Piste"]}},{"k":"number","i":"How many metres long is a standard Olympic fencing competition area?","t":"Fencing","e":"\ud83d\udccf","f":"It is between 1.5 and 2 metres wide.","s":{"value":14,"tolerance":0,"min":4,"max":30,"unit":"m"}},{"k":"truefalse","i":"In sabre, a hit anywhere on the body, from head to foot, can score.","t":"Fencing","e":"\u2705","f":"That's \u00e9p\u00e9e; in sabre only hits above the waist count, and fencers can score with the edge of the blade as well as the point.","a":false},{"k":"choice","i":"Fencing has featured at every modern Summer Olympics, starting from which Games?","t":"Olympic History","e":"\ud83c\udfdb\ufe0f","f":"Women's fencing was first contested at the 1924 Paris Olympics, in foil.","o":["Athens 1896","Paris 1900","London 1908","Stockholm 1912"],"s":{"index":0}},{"k":"number","i":"From how many metres do archers shoot in Olympic recurve events?","t":"Archery","e":"\ud83c\udff9","f":"The Olympic target face is 122 cm across, but its central 10-ring is just 12.2 cm wide.","s":{"value":70,"tolerance":0,"min":20,"max":100,"unit":"m"}},{"k":"order","i":"Order the colours of an Olympic archery target from the centre outwards.","t":"Archery","e":"\ud83c\udfaf","f":"A tiny inner 'X' ring inside the 10 is used to help break ties.","o":["Gold (yellow)","Red","Blue","Black","White"]},{"k":"choice","i":"How many points is an arrow in the outermost white ring of an Olympic target worth?","t":"Archery","e":"\u26aa","f":"Each colour band contains two scoring rings, so the inner white ring is worth 2.","o":["0","1","2","5"],"s":{"index":1}},{"k":"truefalse","i":"Olympic recurve archers are allowed to fit a sight to their bows.","t":"Archery","e":"\ud83d\udd2d","f":"Unlike compound archers, they may not use magnifying lenses in their sights.","a":true},{"k":"choice","i":"Which country won every Olympic women's team archery title from 1988 to 2024?","t":"Archery","e":"\ud83c\udfc5","f":"Paris 2024 brought their tenth straight gold in the event.","o":["China","United States","South Korea","Japan"],"s":{"index":2}},{"k":"multi","i":"Select all the disciplines that make up Olympic shooting.","t":"Shooting","e":"\ud83c\udfaf","f":"Olympic rifle and pistol events are shot at fixed distances of 10, 25 or 50 metres.","o":["Rifle","Crossbow","Pistol","Blowpipe","Shotgun"],"s":{"indices":[0,2,4]}},{"k":"text","i":"Which Olympic shotgun event launches targets from a 'high house' and a 'low house' on either side of the range?","t":"Shooting","e":"\ud83e\udd4f","f":"In trap, the other Olympic shotgun event, targets fly away from the shooter out of a trench in front.","s":{"accepted":["Skeet"]}},{"k":"choice","i":"Olympic air rifle finals use decimal scoring. What is the highest score possible for a single shot?","t":"Shooting","e":"\ud83d\udd22","f":"On a 10 m air rifle target, the 10-ring is a dot just 0.5 mm across.","o":["10.0","10.5","10.9","11.0"],"s":{"index":2}}]},{"slug":"horse-power","title":"Horse Power","tagline":"From the Run for the Roses to the race that stops a nation: saddle up!","emoji":"\ud83c\udfc7","gradient":["#92400e","#166534"],"categories":["sports","olympics"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":361,"items":[{"k":"choice","i":"Which race is nicknamed 'The Run for the Roses'?","t":"Nicknames","e":"\ud83c\udf39","f":"It is traditionally run on the first Saturday in May at Churchill Downs in Louisville.","o":["Kentucky Derby","Preakness Stakes","Belmont Stakes","Epsom Derby"],"s":{"index":0}},{"k":"multi","i":"Select all the races that make up the US Triple Crown.","t":"Triple Crown","e":"\ud83d\udc51","f":"Sir Barton became the first horse to win all three races, back in 1919.","o":["Epsom Derby","Belmont Stakes","Kentucky Derby","Melbourne Cup","Breeders' Cup Classic","Preakness Stakes"],"s":{"indices":[1,2,5]}},{"k":"number","i":"In what year did Secretariat win the US Triple Crown?","t":"Legends","e":"\ud83d\udc0e","f":"Secretariat won the final leg, the Belmont Stakes, by an astonishing 31 lengths.","s":{"value":1973,"tolerance":0,"min":1940,"max":2000,"unit":""}},{"k":"choice","i":"At which racecourse is the Grand National run?","t":"Racecourses","e":"\ud83c\udfc7","f":"The course is near Liverpool, and its famous fences include Becher's Brook.","o":["Epsom Downs","Aintree","Ascot","Cheltenham"],"s":{"index":1}},{"k":"truefalse","i":"The Grand National is a flat race with no jumps.","t":"Rules","e":"\ud83c\udfc7","f":"Runners tackle 30 fences over two laps of the course.","a":false},{"k":"choice","i":"Royal Ascot is held at a racecourse in which English county?","t":"Racecourses","e":"\ud83c\udfa9","f":"Each day of Royal Ascot begins with a royal carriage procession down the course.","o":["Surrey","Kent","Berkshire","Yorkshire"],"s":{"index":2}},{"k":"text","i":"The Melbourne Cup, 'the race that stops a nation', is traditionally run on the first ___ of November. Which day of the week?","t":"Traditions","e":"\ud83d\udcc6","f":"It is run at Flemington Racecourse, and the day is a public holiday in Melbourne.","s":{"accepted":["Tuesday","Tues","Tue"]}},{"k":"choice","i":"Which equestrian discipline, sometimes called 'horse ballet', is judged on precise movements?","t":"Equestrian","e":"\ud83d\udc34","f":"Equestrian is one of the few Olympic sports in which men and women compete directly against each other.","o":["Show jumping","Eventing","Polo","Dressage"],"s":{"index":3}},{"k":"multi","i":"Select all the phases of Olympic eventing.","t":"Equestrian","e":"\ud83c\udfc5","f":"Eventing grew out of cavalry tests that demanded obedience, stamina and bold jumping from horses.","o":["Cross-country","Polo","Dressage","Show jumping","Flat racing"],"s":{"indices":[0,2,3]}},{"k":"text","i":"What is the name of each period of play in a polo match?","t":"Polo","e":"\ud83d\udc0e","f":"Each period lasts about seven minutes, and players often switch to a fresh pony between them.","s":{"accepted":["Chukka","Chukkas","Chukker","Chukkers"]}},{"k":"choice","i":"In horse racing, how long is a furlong?","t":"Racing terms","e":"\ud83d\udccf","f":"The name comes from 'furrow long', the length of a ploughed furrow; at 220 yards, it makes the 1\u00bc-mile Kentucky Derby a 10-furlong race.","o":["A quarter of a mile","A tenth of a mile","An eighth of a mile","Half a mile"],"s":{"index":2}},{"k":"choice","i":"In show jumping, what does a 'clear round' mean?","t":"Show jumping","e":"\ud83d\udea7","f":"Knocking down a pole costs 4 faults, and riders tied on clear rounds usually meet in a timed jump-off.","o":["Riding without a saddle","Finishing with no faults","Jumping every fence twice","Winning a jump-off"],"s":{"index":1}},{"k":"order","i":"Order these famous races by the month they are traditionally run, from earliest to latest in the year.","t":"Racing calendar","e":"\ud83d\udcc5","f":"The Prix de l'Arc de Triomphe is traditionally run at Longchamp in Paris on the first Sunday in October.","o":["Grand National","Kentucky Derby","Royal Ascot","Prix de l'Arc de Triomphe","Melbourne Cup"]},{"k":"truefalse","i":"Thoroughbred racehorses in the Northern Hemisphere all share an official birthday of 1 January.","t":"Racing rules","e":"\ud83c\udf82","f":"In the Southern Hemisphere, racehorses officially turn a year older on 1 August.","a":true}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '4ba138d9245d8185599fd8dc9a25d4a6' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 17'; end $q$;
do $q$ declare d text := $d$[{"slug":"sports-on-screen","title":"Sports on the Big Screen","tagline":"From Rocky's steps to Space Jam: how well do you know sports movies?","emoji":"\ud83c\udfac","gradient":["#be123c","#7e22ce"],"categories":["sports","movies"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":362,"items":[{"k":"choice","i":"In 'Rocky', the boxer famously trains by running up the steps of which landmark?","t":"Classics","e":"\ud83c\udfc3","f":"A bronze statue of Rocky now stands near the foot of the steps.","o":["Lincoln Memorial","Philadelphia Museum of Art","US Capitol","New York Public Library"],"s":{"index":1}},{"k":"text","i":"Which country's bobsleigh team inspired the Disney film 'Cool Runnings'?","t":"Winter sports","e":"\ud83d\udef7","f":"The real team made its Olympic debut at the 1988 Winter Games in Calgary, Canada.","s":{"accepted":["Jamaica","Jamaican"]}},{"k":"choice","i":"Which basketball legend starred alongside Bugs Bunny in 'Space Jam'?","t":"Animation","e":"\ud83d\udc30","f":"The Looney Tunes take on alien villains called the Monstars, who steal NBA players' skills.","o":["Magic Johnson","Shaquille O'Neal","Larry Bird","Michael Jordan"],"s":{"index":3}},{"k":"choice","i":"Brad Pitt's 'Moneyball' follows which baseball team's data-driven 2002 season?","t":"True stories","e":"\ud83d\udcca","f":"Pitt plays general manager Billy Beane, who used statistics to compete on a small budget.","o":["Oakland Athletics","New York Yankees","Boston Red Sox","Chicago Cubs"],"s":{"index":0}},{"k":"number","i":"'Chariots of Fire' follows two British runners at the Paris Olympics of which year?","t":"Olympics on film","e":"\ud83c\udfc5","f":"The film won the Oscar for Best Picture, and Vangelis's theme music became world famous.","s":{"value":1924,"tolerance":0,"min":1896,"max":1972,"unit":""}},{"k":"choice","i":"The film 'Rush' is about the 1970s Formula 1 rivalry between James Hunt and which driver?","t":"Motor racing","e":"\ud83c\udfce\ufe0f","f":"It centres on the 1976 season, which Hunt won by a single point.","o":["Ayrton Senna","Jackie Stewart","Niki Lauda","Alain Prost"],"s":{"index":2}},{"k":"text","i":"'Invictus' is set during the 1995 Rugby World Cup. Which country won that tournament?","t":"True stories","e":"\ud83c\udfc9","f":"South Africa hosted and won the tournament. Morgan Freeman plays Nelson Mandela and Matt Damon plays captain Fran\u00e7ois Pienaar.","s":{"accepted":["South Africa","RSA","Springboks"]}},{"k":"choice","i":"Which move does Daniel use to win the tournament at the end of 'The Karate Kid' (1984)?","t":"Classics","e":"\ud83e\udd4b","f":"Mr. Miyagi famously trained Daniel through chores such as 'wax on, wax off'.","o":["Crane kick","Tiger punch","Dragon sweep","Flying elbow"],"s":{"index":0}},{"k":"choice","i":"The title 'Bend It Like Beckham' refers to David Beckham's skill at what?","t":"Football","e":"\u26bd","f":"The 2002 film helped launch the careers of Parminder Nagra and Keira Knightley.","o":["Long throw-ins","Diving headers","Curling free kicks","Sliding tackles"],"s":{"index":2}},{"k":"choice","i":"'Ford v Ferrari' centres on which famous 1966 race?","t":"Motor racing","e":"\ud83c\udfc1","f":"Ford's GT40s finished first, second and third, ending Ferrari's run of six straight wins at the race.","o":["Indianapolis 500","Monaco Grand Prix","Daytona 500","24 Hours of Le Mans"],"s":{"index":3}},{"k":"text","i":"In 'Field of Dreams', Kevin Costner's character builds a baseball diamond in a cornfield in which US state?","t":"Classics","e":"\ud83c\udf3d","f":"The film's famous whispered line is 'If you build it, he will come.'","s":{"accepted":["Iowa"]}},{"k":"multi","i":"Select all the films about American football.","t":"Team sports","e":"\ud83c\udfa5","f":"'Remember the Titans', starring Denzel Washington, is based on a real 1971 high school team from Virginia.","o":["Remember the Titans","Hoosiers","Rudy","Seabiscuit","Miracle"],"s":{"indices":[0,2]}},{"k":"multi","i":"Select all the films about baseball.","t":"Team sports","e":"\ud83e\udde2","f":"'A League of Their Own' is based on a real professional baseball league for women, founded in 1943.","o":["The Sandlot","Coach Carter","A League of Their Own","The Mighty Ducks","Senna"],"s":{"indices":[0,2]}},{"k":"order","i":"Order these sports films by release year, from earliest to latest.","t":"Release dates","e":"\ud83c\udf9e\ufe0f","f":"'Rocky' was written by its star, Sylvester Stallone.","o":["Rocky","Chariots of Fire","Cool Runnings","Moneyball","Ford v Ferrari"]}]},{"slug":"arenas-of-legend","title":"Arenas of Legend","tagline":"From the Crucible to the Big House: tour the world's most famous sporting venues.","emoji":"\ud83c\udfdf\ufe0f","gradient":["#0f766e","#1d4ed8"],"categories":["sports","travel"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":363,"items":[{"k":"choice","i":"Which famous arena sits on top of Pennsylvania Station in New York City?","t":"Arenas","e":"\ud83d\uddfd","f":"The current Garden, the fourth to carry the name, opened in 1968 and is home to the Knicks and Rangers.","o":["Barclays Center","Madison Square Garden","Yankee Stadium","Citi Field"],"s":{"index":1}},{"k":"number","i":"In what year did Paris's Stade Roland Garros, home of the French Open, open?","t":"Tennis","e":"\ud83c\udfbe","f":"It was built for France's Davis Cup defence after the 'Four Musketeers' won the trophy in 1927, and is named after a pioneering aviator.","s":{"value":1928,"tolerance":0,"min":1900,"max":1970,"unit":""}},{"k":"choice","i":"What nickname is given to the stretch from the 11th to the 13th hole at Augusta National?","t":"Golf","e":"\u26f3","f":"Writer Herbert Warren Wind is credited with the name, which he used in a 1958 Sports Illustrated report on the Masters.","o":["Hogan's Alley","The Bear Trap","Amen Corner","The Devil's Elbow"],"s":{"index":2}},{"k":"choice","i":"The Melbourne Cricket Ground traditionally hosts a Test match starting on which day?","t":"Cricket","e":"\ud83c\udfcf","f":"The MCG also hosted the first-ever Test match in 1877 and was the main stadium of the 1956 Olympics.","o":["New Year's Day (1 January)","Australia Day (26 January)","Boxing Day (26 December)","Anzac Day (25 April)"],"s":{"index":2}},{"k":"truefalse","i":"The playing field at Lord's, the 'Home of Cricket', has a noticeable slope.","t":"Cricket","e":"\ud83d\udcd0","f":"The ground drops about 2.5 metres from one side to the other, which bowlers can use to move the ball.","a":true},{"k":"number","i":"To the nearest foot, how tall is the 'Green Monster', the left-field wall at Boston's Fenway Park?","t":"Baseball","e":"\ud83d\udfe9","f":"Fenway opened in 1912, days after the Titanic sank, and is the oldest ballpark in Major League Baseball.","s":{"value":37,"tolerance":0,"min":20,"max":60,"unit":"ft"}},{"k":"truefalse","i":"Lambeau Field, home of the famous 'Lambeau Leap' touchdown celebration, is the home of the Chicago Bears.","t":"NFL venues","e":"\ud83e\uddc0","f":"It is the home of the Green Bay Packers, who have played there since it opened in 1957.","a":false},{"k":"text","i":"In which city is Croke Park, the headquarters and main stadium of Gaelic games?","t":"Gaelic games","e":"\u2618\ufe0f","f":"It hosts the All-Ireland hurling and football finals, and is named after Archbishop Thomas Croke, an early patron of the GAA.","s":{"accepted":["Dublin","Baile \u00c1tha Cliath","Baile Atha Cliath"]}},{"k":"choice","i":"Which university's football stadium is nicknamed 'The Big House'?","t":"College football","e":"\ud83c\udfc8","f":"Located in Ann Arbor, it officially seats more than 107,000 fans.","o":["University of Michigan","Ohio State University","Penn State University","University of Texas"],"s":{"index":0}},{"k":"choice","i":"Twickenham Stadium, renamed Allianz Stadium in a 2024 naming deal, is the home of England's national team in which sport?","t":"Venues","e":"\ud83c\udfdf\ufe0f","f":"Nicknamed 'HQ', it hosted its first international match in 1910, England against Wales.","o":["Cricket","Rugby union","Rugby league","Football"],"s":{"index":1}},{"k":"choice","i":"In which Indian city is the famous Eden Gardens cricket ground?","t":"Cricket","e":"\ud83c\udfcf","f":"It hosted the 1987 Cricket World Cup final, in which Australia beat England.","o":["Mumbai","Delhi","Chennai","Kolkata"],"s":{"index":3}},{"k":"choice","i":"The Daytona 500, 'The Great American Race', is the most famous event in which motorsport series?","t":"Motorsport","e":"\ud83c\udfc1","f":"Run at Daytona International Speedway in Florida since 1959, it is the first points race of the NASCAR Cup season.","o":["NASCAR Cup Series","IndyCar Series","Formula One","MotoGP"],"s":{"index":0}},{"k":"multi","i":"Select all the venues located in London.","t":"Venues","e":"\ud83d\udccd","f":"Old Trafford is in Greater Manchester, and Murrayfield, home of Scottish rugby, is in Edinburgh.","o":["Lord's","Old Trafford","Twickenham (Allianz Stadium)","Murrayfield","Wimbledon's Centre Court"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these venues by when they first opened, from oldest to newest.","t":"History","e":"\ud83d\udcc5","f":"Lord's moved to its current site in 1814, the MCG dates from 1853, Fenway from 1912 and Daytona from 1959.","o":["Lord's (current ground)","Melbourne Cricket Ground","Fenway Park","Daytona International Speedway"]}]},{"slug":"football-firsts-and-oddities","title":"Football Firsts & Oddities","tagline":"Victorian pioneers, freak scorelines and unlikely heroes: football's quirkiest history.","emoji":"\ud83c\udfa9","gradient":["#0d9488","#4c1d95"],"categories":["football","sports","history"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":364,"items":[{"k":"number","i":"In what year was the first official international football match, Scotland v England, played?","t":"Internationals","e":"\ud83d\udcc5","f":"It was played on a cricket ground, Hamilton Crescent in Partick, in front of around 4,000 fans.","s":{"value":1872,"tolerance":0,"min":1850,"max":1900,"unit":""}},{"k":"truefalse","i":"The first official international football match ended in a 0\u20130 draw.","t":"Internationals","e":"\ud83e\udd1d","f":"Scotland's entire team was made up of players from the Queen's Park club.","a":true},{"k":"choice","i":"Sheffield FC, recognised by FIFA as the world's oldest football club, was founded in which year?","t":"Clubs","e":"\ud83c\udfda\ufe0f","f":"The club also helped shape the 'Sheffield Rules', an early code of football.","o":["1847","1857","1863","1878"],"s":{"index":1}},{"k":"choice","i":"In which city was the Football Association (the FA) founded in 1863?","t":"Governing bodies","e":"\ud83c\udfdb\ufe0f","f":"The first meeting took place at the Freemasons' Tavern on Great Queen Street.","o":["London","Sheffield","Manchester","Nottingham"],"s":{"index":0}},{"k":"text","i":"Which Irish goalkeeper is credited with inventing the penalty kick, adopted in 1891?","t":"Rules","e":"\ud83e\udd45","f":"McCrum came from the village of Milford in County Armagh.","s":{"accepted":["William McCrum","McCrum","Willie McCrum"]}},{"k":"choice","i":"Which ground hosted what is widely regarded as the first floodlit football match, in October 1878?","t":"Floodlights","e":"\ud83d\udca1","f":"The pitch was lit by lamps on wooden towers, powered by steam-driven generators.","o":["Kennington Oval","Hampden Park","Bramall Lane","Anfield"],"s":{"index":2}},{"k":"choice","i":"Which team won the very first FA Cup final?","t":"Cup finals","e":"\ud83c\udfc6","f":"The only goal was scored by Morton Betts, playing under the pseudonym 'A. H. Chequer'.","o":["Royal Engineers","Old Etonians","Queen's Park","Wanderers"],"s":{"index":3}},{"k":"truefalse","i":"Everton went the whole first Football League season, 1888-89, without losing a league match.","t":"Leagues","e":"\ud83d\udee1\ufe0f","f":"That was Preston North End, who also won the FA Cup without conceding a goal, earning the nickname 'The Invincibles'.","a":false},{"k":"number","i":"How many clubs took part in the first Football League season in 1888-89?","t":"Leagues","e":"\ud83d\udd22","f":"The league was the idea of William McGregor, a director of Aston Villa.","s":{"value":12,"tolerance":0,"min":4,"max":24,"unit":"clubs"}},{"k":"choice","i":"In March 1966, the stolen World Cup trophy was found under a hedge in London by whom?","t":"Oddities","e":"\ud83d\udd0d","f":"The trophy had been stolen from an exhibition in Westminster just months before England hosted the tournament.","o":["A schoolboy on his way home","A dog named Pickles","A taxi driver","A police officer on patrol"],"s":{"index":1}},{"k":"truefalse","i":"In 2002, a league match in Madagascar finished 149\u20130 because one team kept scoring own goals in protest.","t":"Oddities","e":"\ud83d\ude2e","f":"SO l'Emyrne were protesting against refereeing decisions in an earlier match.","a":true},{"k":"number","i":"How many goals did Australia score against American Samoa in a 2001 World Cup qualifier?","t":"Scorelines","e":"\ud83e\udd45","f":"Archie Thompson scored 13 of them, and American Samoa didn't score at all.","s":{"value":31,"tolerance":0,"min":10,"max":40,"unit":"goals"}},{"k":"order","i":"Order these football milestones from earliest to latest.","t":"Timeline","e":"\ud83d\udcdc","f":"Charlton's Keith Peacock became the first Football League substitute in August 1965.","o":["FIFA founded in Paris","Wembley's 'White Horse' FA Cup final","First World Cup, in Uruguay","First Match of the Day on BBC television","First substitute used in the English Football League"]},{"k":"multi","i":"Select all the clubs founded before 1880.","t":"Clubs","e":"\ud83c\udfdb\ufe0f","f":"Notts County, founded in 1862, is often called the world's oldest professional football club.","o":["Aston Villa","Nottingham Forest","Liverpool","Arsenal","Notts County","Chelsea"],"s":{"indices":[0,1,4]}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '9fce56887001590de2ff5f4c348ac76b' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 18'; end $q$;
do $q$ declare d text := $d$[{"slug":"name-that-franchise","title":"Name That Franchise","tagline":"Packers, Yankees, Canadiens and more: match North America's big teams to their homes.","emoji":"\ud83c\udfdf\ufe0f","gradient":["#0d9488","#4338ca"],"categories":["sports","geo"],"countries":["US","CA"],"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":365,"items":[{"k":"choice","i":"Which small Wisconsin city is home to the NFL's Packers?","t":"NFL","e":"\ud83e\uddc0","f":"The Packers are owned by their fans as a community-owned non-profit, unique among major US pro teams.","o":["Green Bay","Milwaukee","Madison","Kenosha"],"s":{"index":0}},{"k":"choice","i":"The New York Yankees play in which New York City borough?","t":"MLB","e":"\ud83d\uddfd","f":"New York's other MLB team, the Mets, plays in Queens.","o":["Brooklyn","The Bronx","Queens","Manhattan"],"s":{"index":1}},{"k":"choice","i":"Which city's NBA team is called the Bulls?","t":"NBA","e":"\ud83d\udc02","f":"A bronze statue of Michael Jordan has stood at the team's United Center arena since 1994.","o":["Detroit","Milwaukee","Chicago","Cleveland"],"s":{"index":2}},{"k":"truefalse","i":"Before moving to Los Angeles in 1960, the Lakers were based in Detroit.","t":"NBA","e":"\ud83c\udf0a","f":"They were the Minneapolis Lakers, a name that suits Minnesota, the 'Land of 10,000 Lakes', and they kept it after moving west.","a":false},{"k":"choice","i":"Which sport do the Montreal Canadiens play?","t":"Canada","e":"\ud83c\udf41","f":"Founded in 1909, the Canadiens are older than the NHL itself.","o":["Baseball","Basketball","Canadian football","Ice hockey"],"s":{"index":3}},{"k":"text","i":"Which Canadian NBA team, which played its first season in 1995, is named after a dinosaur?","t":"Team names","e":"\ud83e\udd96","f":"The name was picked in a 1994 name-the-team contest, soon after Jurassic Park became a hit.","s":{"accepted":["Raptors","Toronto Raptors","Raptor","The Raptors"]}},{"k":"multi","i":"Select all the teams based in Boston.","t":"Cities","e":"\ud83e\udd9e","f":"The Bruins became the NHL's first US-based team when they joined the league in 1924.","o":["Celtics","Knicks","Red Sox","Flyers","Bruins","Cubs"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which city's NFL team, the Steelers, is named after the city's famous industry?","t":"NFL","e":"\u2699\ufe0f","f":"With its huge mills, the city was long nicknamed the 'Steel City'.","o":["Pittsburgh","Detroit","Cleveland","Baltimore"],"s":{"index":0}},{"k":"order","i":"Order these North American leagues from oldest to youngest.","t":"Leagues","e":"\ud83d\udcc5","f":"The NFL began in 1920 under the name American Professional Football Association.","o":["Baseball's National League","NHL","NFL","NBA"]},{"k":"number","i":"In what year did Toronto's NBA team win its first championship?","t":"NBA","e":"\ud83c\udfc6","f":"They beat the Golden State Warriors in six games, with Kawhi Leonard named Finals MVP.","s":{"value":2019,"tolerance":0,"min":1995,"max":2024,"unit":""}},{"k":"truefalse","i":"The New York Giants and New York Jets both play their home games in New Jersey.","t":"NFL","e":"\ud83c\udfc8","f":"The two teams share MetLife Stadium in East Rutherford, just outside New York City.","a":true},{"k":"choice","i":"The Utah Jazz took their name from their original home city. Which city was it?","t":"Team names","e":"\ud83c\udfb7","f":"The team moved to Salt Lake City in 1979 but kept a name that fits New Orleans' music scene.","o":["Memphis","New Orleans","Chicago","Kansas City"],"s":{"index":1}},{"k":"text","i":"The NHL's Canucks play in which Canadian city on the Pacific coast?","t":"Cities","e":"\ud83c\udf32","f":"The same city hosted the 2010 Winter Olympics.","s":{"accepted":["Vancouver","Vancouver BC"]}},{"k":"choice","i":"Which MLB team plays its home games at Wrigley Field?","t":"MLB","e":"\ud83c\udf3f","f":"Wrigley Field's outfield walls are famously covered in ivy.","o":["Chicago White Sox","St. Louis Cardinals","Chicago Cubs","Milwaukee Brewers"],"s":{"index":2}}]},{"slug":"tour-de-france","title":"Grand Tour Glory","tagline":"Jerseys, mountain legends and three great stage races: saddle up!","emoji":"\ud83d\udeb4","gradient":["#d97706","#be185d"],"categories":["sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":366,"items":[{"k":"number","i":"In what year was the first Tour de France held?","t":"Origins","e":"\ud83d\udcc5","f":"It was created by the sports newspaper L'Auto to boost its sales.","s":{"value":1903,"tolerance":0,"min":1880,"max":1950,"unit":""}},{"k":"text","i":"Which rider won the very first Tour de France?","t":"Origins","e":"\ud83e\udd47","f":"Garin, an Italian-born Frenchman, won by almost three hours over six huge stages.","s":{"accepted":["Maurice Garin","Garin"]}},{"k":"choice","i":"What does the green jersey reward at the Tour de France?","t":"Jerseys","e":"\ud83d\udc9a","f":"It was introduced to mark 50 years since the first Tour.","o":["The points classification, usually won by sprinters","The best young rider","The best climber","The most aggressive rider"],"s":{"index":0}},{"k":"choice","i":"What does the Tour de France's King of the Mountains wear?","t":"Jerseys","e":"\u26f0\ufe0f","f":"The mountains prize dates back to 1933, long before the spotted jersey arrived in 1975.","o":["A red jersey with white stripes","A blue jersey with yellow stars","A black jersey with white checks","A white jersey with red polka dots"],"s":{"index":3}},{"k":"truefalse","i":"The white jersey at the Tour de France goes to the best-placed young rider.","t":"Jerseys","e":"\ud83e\udd0d","f":"Several riders have won the white and yellow jerseys in the same Tour, including Egan Bernal in 2019.","a":true},{"k":"choice","i":"On which famous Paris avenue does the Tour de France traditionally finish?","t":"The Finish","e":"\ud83c\udfc1","f":"In 2024 the Tour finished in Nice instead, because Paris was preparing to host the Olympics.","o":["Boulevard Saint-Germain","Champs-\u00c9lys\u00e9es","Avenue Foch","Rue de Rivoli"],"s":{"index":1}},{"k":"choice","i":"Which Belgian rider, nicknamed 'The Cannibal', won five Tours de France?","t":"Legends","e":"\ud83e\udd81","f":"Merckx also won the Giro d'Italia five times.","o":["Eddy Merckx","Lucien Van Impe","Freddy Maertens","Roger De Vlaeminck"],"s":{"index":0}},{"k":"text","i":"Which Spanish rider won five Tours de France in a row, from 1991 to 1995?","t":"Legends","e":"\ud83d\udd90\ufe0f","f":"He also won the Giro d'Italia twice, in 1992 and 1993.","s":{"accepted":["Miguel Indur\u00e1in","Indur\u00e1in","Miguel Indurain","Indurain"]}},{"k":"choice","i":"What colour is the race leader's jersey in the Giro d'Italia?","t":"Giro d'Italia","e":"\ud83c\udf38","f":"It matches the pages of La Gazzetta dello Sport, the newspaper that founded the race in 1909.","o":["Red","Blue","Pink","Orange"],"s":{"index":2}},{"k":"choice","i":"Since 2010, what colour jersey has the overall leader of the Vuelta a Espa\u00f1a worn?","t":"Vuelta a Espa\u00f1a","e":"\ud83c\udf36\ufe0f","f":"Before red, the leader wore a gold jersey for about a decade; Alejandro Valverde was its last winner, in 2009.","o":["Gold","Orange","Blue","Red"],"s":{"index":3}},{"k":"order","i":"Order these races by the year they were first held, from earliest to latest.","t":"Race History","e":"\ud83d\uddd3\ufe0f","f":"Paris\u2013Roubaix, nicknamed 'the Hell of the North', is famous for its bone-shaking cobbled sections.","o":["Paris\u2013Roubaix","Tour de France","Giro d'Italia","Vuelta a Espa\u00f1a"]},{"k":"multi","i":"Select all the riders who won the Tour de France five times.","t":"Legends","e":"\ud83c\udfc6","f":"LeMond won three Tours, while Fignon and Coppi each won two.","o":["Jacques Anquetil","Greg LeMond","Bernard Hinault","Laurent Fignon","Fausto Coppi"],"s":{"indices":[0,2]}},{"k":"truefalse","i":"Laurent Fignon won the 1989 Tour de France by just 8 seconds over Greg LeMond.","t":"Close Finishes","e":"\u23f1\ufe0f","f":"It was the other way round: LeMond overturned a 50-second deficit in the final-day time trial into Paris to win by 8 seconds.","a":false},{"k":"order","i":"Order these riders by the year of their first Tour de France win, from earliest to latest.","t":"Champions","e":"\ud83d\udcdc","f":"In 1949 Coppi became the first rider to win the Giro and the Tour in the same year.","o":["Fausto Coppi","Jacques Anquetil","Eddy Merckx","Bernard Hinault","Greg LeMond"]}]},{"slug":"track-and-field","title":"On Your Marks","tagline":"Sub-four miles, flops and flying leaps: test your track and field smarts.","emoji":"\ud83c\udfc3","gradient":["#4f46e5","#db2777"],"categories":["sports","olympics"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":367,"items":[{"k":"number","i":"In what year did Roger Bannister run the first mile in under four minutes?","t":"Milestones","e":"\u23f1\ufe0f","f":"Bannister clocked 3:59.4 at Oxford's Iffley Road track, paced by Chris Brasher and Chris Chataway.","s":{"value":1954,"tolerance":0,"min":1920,"max":1980,"unit":""}},{"k":"choice","i":"In which city did Usain Bolt run his 9.58-second 100 m world record in 2009?","t":"Sprinting","e":"\u26a1","f":"At the same championships he also set a 200 m world record of 19.19 seconds.","o":["Beijing","Berlin","London","Rome"],"s":{"index":1}},{"k":"choice","i":"How far did Bob Beamon leap to win long jump gold at the 1968 Mexico City Olympics?","t":"Long jump","e":"\ud83e\udd98","f":"Beamon smashed the world record by 55 cm, and his mark stood for almost 23 years.","o":["8.35 m","9.25 m","8.90 m","8.13 m"],"s":{"index":2}},{"k":"choice","i":"The 'Fosbury Flop', made famous at the 1968 Olympics, is a technique in which event?","t":"Techniques","e":"\ud83d\udd04","f":"Dick Fosbury won gold by clearing the bar head-first and on his back, and the style soon took over.","o":["Pole vault","Long jump","Triple jump","High jump"],"s":{"index":3}},{"k":"multi","i":"Select all the events that are part of the heptathlon.","t":"Combined events","e":"\ud83c\udfc5","f":"The heptathlon's seven events are spread over two days, finishing with the 800 m.","o":["Pole vault","100 m hurdles","High jump","Discus","400 m","Javelin"],"s":{"indices":[1,2,5]}},{"k":"order","i":"Order the first-day events of the men's decathlon as they are held, from first to last.","t":"Combined events","e":"\ud83d\udccb","f":"Day two brings the 110 m hurdles, discus, pole vault and javelin, ending with the 1500 m.","o":["100 m","Long jump","Shot put","High jump","400 m"]},{"k":"truefalse","i":"In the 3000 m steeplechase, runners clear the water jump seven times.","t":"Steeplechase","e":"\ud83d\udca6","f":"Runners also clear 28 barriers, which, unlike hurdles, are sturdy enough to step on.","a":true},{"k":"text","i":"What do relay runners pass to each other inside a marked changeover zone?","t":"Relays","e":"\ud83c\udfc3","f":"If it is dropped, the runner who dropped it must pick it up for the team to carry on.","s":{"accepted":["Baton","A baton","The baton","Relay baton"]}},{"k":"choice","i":"How tall are the hurdles in the men's 110 m hurdles?","t":"Hurdles","e":"\ud83d\udea7","f":"Both the men's 110 m and the women's 100 m hurdles races have ten flights of hurdles.","o":["1.067 m","0.914 m","0.838 m","1.200 m"],"s":{"index":0}},{"k":"multi","i":"Select all the field events.","t":"Field events","e":"\ud83c\udfaf","f":"The men's hammer and shot both weigh 7.26 kg, matching the old 16-pound standard.","o":["Hammer throw","Steeplechase","Triple jump","110 m hurdles","Pole vault","10,000 m"],"s":{"indices":[0,2,4]}},{"k":"number","i":"How many laps of a standard 400 m track make up the 10,000 m race?","t":"Distance running","e":"\ud83d\udd01","f":"It is the longest race held entirely on the track on the current Olympic programme.","s":{"value":25,"tolerance":0,"min":5,"max":50,"unit":"laps"}},{"k":"choice","i":"Which runner won the marathon at the 1960 Rome Olympics while running barefoot?","t":"Legends","e":"\ud83c\udfc3","f":"The Ethiopian retained his title at Tokyo 1964, this time wearing shoes, only weeks after an operation to remove his appendix.","o":["Mamo Wolde","Abebe Bikila","Kip Keino","Frank Shorter"],"s":{"index":1}},{"k":"truefalse","i":"Modern pole vaulters must use poles made of bamboo.","t":"Pole vault","e":"\ud83c\udfc5","f":"Bamboo gave way to metal and then bendy fibreglass and carbon-fibre poles, which fling vaulters far higher.","a":false},{"k":"choice","i":"In which throwing event do athletes sprint down a runway before releasing?","t":"Throws","e":"\ud83c\udfaf","f":"The men's javelin was redesigned in 1986 because the best throws were flying beyond 100 m.","o":["Shot put","Discus","Javelin","Hammer throw"],"s":{"index":2}}]},{"slug":"little-champions","title":"Little Champions","tagline":"Easy sports questions for young fans: balls, bats, goals and medals!","emoji":"\ud83c\udfc6","gradient":["#db2777","#f59e0b"],"categories":["sports","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":368,"items":[{"k":"choice","i":"What shape is a rugby ball?","t":"Ball shapes","e":"\ud83c\udfdf\ufe0f","f":"Its shape makes the ball bounce in surprising directions.","o":["Round","Square","Oval","Triangle"],"s":{"index":2}},{"k":"choice","i":"In which sport do players hit a fuzzy yellow ball over a net with rackets?","t":"Ball sports","e":"\ud83d\udfe1","f":"Most tennis balls are filled with pressurised air to help them bounce.","o":["Volleyball","Tennis","Basketball","Golf"],"s":{"index":1}},{"k":"multi","i":"Select all the sports where players hit a ball with a bat.","t":"Bats","e":"\ud83d\udca5","f":"Cricket bats are flat and made of willow, while baseball bats are round.","o":["Baseball","Basketball","Cricket","Swimming","Volleyball"],"s":{"indices":[0,2]}},{"k":"choice","i":"What do cricket batters score by running between the wickets?","t":"Scoring","e":"\ud83c\udfcf","f":"Hitting the ball over the boundary without it bouncing scores six in one go.","o":["Goals","Points","Tries","Runs"],"s":{"index":3}},{"k":"truefalse","i":"In football (soccer), the goalkeeper may pick up the ball with their hands anywhere on the pitch.","t":"Rules","e":"\ud83e\udde4","f":"Goalkeepers may only handle the ball inside their own penalty area; outside it they must play like everyone else.","a":false},{"k":"choice","i":"What colour medal does the winner of an Olympic event receive?","t":"Olympics","e":"\ud83c\udf89","f":"Second place earns silver and third place earns bronze.","o":["Gold","Silver","Bronze","Blue"],"s":{"index":0}},{"k":"order","i":"Order these races from shortest to longest.","t":"Running","e":"\ud83c\udfc3","f":"A marathon is more than 400 times longer than a 100 m sprint.","o":["100 m sprint","400 m","1500 m","Marathon"]},{"k":"number","i":"How many players are on a tennis court during a doubles match?","t":"Tennis","e":"\ud83c\udfbe","f":"In doubles the court gets wider, because the side strips called 'alleys' or 'tramlines' are in play.","s":{"value":4,"tolerance":0,"min":1,"max":10,"unit":"players"}},{"k":"text","i":"What is the name of the race where athletes swim, then cycle, then run?","t":"Multi-sport","e":"\ud83c\udfca","f":"The Olympic version is a 1.5 km swim, a 40 km bike ride and a 10 km run.","s":{"accepted":["Triathlon","Triathalon","A triathlon"]}},{"k":"choice","i":"In which sport do you roll a ball to knock down ten pins?","t":"Pins","e":"\ud83d\udd1f","f":"The pins are set up in a triangle with four rows.","o":["Golf","Bowling","Billiards","Croquet"],"s":{"index":1}},{"k":"choice","i":"How many points is a free throw worth in basketball?","t":"Basketball","e":"\ud83c\udfc0","f":"Free throws are taken from a line 15 feet (about 4.6 m) from the backboard.","o":["1","2","3","4"],"s":{"index":0}},{"k":"text","i":"What do we call the official who makes sure players follow the rules in a football match?","t":"Rules","e":"\ud83d\udfe8","f":"Football referees show a yellow card as a warning and a red card to send a player off.","s":{"accepted":["Referee","Ref","The referee"]}},{"k":"truefalse","i":"A golf ball is bigger than a basketball.","t":"Ball sizes","e":"\u26f3","f":"A golf ball is about 4.3 cm across, while a basketball is about 24 cm.","a":false},{"k":"number","i":"How many holes are played in a standard round of golf?","t":"Golf","e":"\u26f3","f":"Getting the ball into the hole with your very first shot is called a hole-in-one.","s":{"value":18,"tolerance":0,"min":1,"max":30,"unit":"holes"}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'eff1dc49f7c4e2bdbff25bf779087745' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 19'; end $q$;
do $q$ declare d text := $d$[{"slug":"sporting-rivalries","title":"Great Sporting Rivalries","tagline":"Ali and Frazier, Borg and McEnroe, Celtic and Rangers: who wins your quiz duel?","emoji":"\u2694\ufe0f","gradient":["#ea580c","#6d28d9"],"categories":["sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":369,"items":[{"k":"choice","i":"Which British runner won 800 m gold at the 1980 Moscow Olympics, beating his great rival Sebastian Coe?","t":"Athletics","e":"\ud83c\udfc3","f":"Coe hit back six days later to win the 1,500 m, in which Ovett took the bronze medal.","o":["Steve Cram","Daley Thompson","Brendan Foster","Steve Ovett"],"s":{"index":3}},{"k":"truefalse","i":"Bj\u00f6rn Borg beat John McEnroe in the 1980 Wimbledon final, a match featuring a famous 18\u201316 tiebreak.","t":"Tennis","e":"\ud83c\udfbe","f":"McEnroe won that tiebreak, but Borg took the fifth set for his fifth straight title; McEnroe ended the run a year later.","a":true},{"k":"choice","i":"Roger Federer and Rafael Nadal met in nine Grand Slam finals, but never in the final of which major?","t":"Tennis","e":"\ud83c\udfc6","f":"Fittingly, Federer's last professional match was a doubles match alongside Nadal at the 2022 Laver Cup.","o":["Australian Open","US Open","French Open","Wimbledon"],"s":{"index":1}},{"k":"choice","i":"Magic Johnson and Larry Bird led which two NBA teams in their 1980s rivalry?","t":"NBA","e":"\ud83c\udfc0","f":"Their rivalry began in the 1979 college final, and they met three times in the NBA Finals, in 1984, 1985 and 1987.","o":["Chicago Bulls and Detroit Pistons","New York Knicks and Miami Heat","Los Angeles Lakers and Boston Celtics","Philadelphia 76ers and Milwaukee Bucks"],"s":{"index":2}},{"k":"choice","i":"At which circuit did Alain Prost and Ayrton Senna collide to decide the world title in both 1989 and 1990?","t":"Formula One","e":"\ud83c\udfce\ufe0f","f":"The 1989 crash handed the title to Prost, and the 1990 first-corner collision sealed it for Senna.","o":["Monaco","Interlagos","Suzuka","Monza"],"s":{"index":2}},{"k":"number","i":"How many times did Chris Evert and Martina Navratilova play each other in their careers?","t":"Tennis","e":"\ud83d\udd22","f":"Navratilova edged the head-to-head 43\u201337, and 60 of their meetings came in finals.","s":{"value":80,"tolerance":0,"min":20,"max":120,"unit":"matches"}},{"k":"choice","i":"In which city is the 'Old Firm' derby between Celtic and Rangers played?","t":"Football","e":"\u26bd","f":"The clubs first met in 1888; Celtic play at Celtic Park and Rangers at Ibrox.","o":["Glasgow","Edinburgh","Aberdeen","Dundee"],"s":{"index":0}},{"k":"text","i":"What Spanish name is given to matches between Real Madrid and Barcelona?","t":"Football","e":"\ud83d\udd25","f":"Their first meeting came in 1902, and they are the two most successful clubs in Spanish football.","s":{"accepted":["El Cl\u00e1sico","El Clasico","Cl\u00e1sico","Clasico"]}},{"k":"choice","i":"In Argentina's Supercl\u00e1sico, which club is nicknamed 'Los Millonarios' (The Millionaires)?","t":"Football","e":"\ud83c\udde6\ud83c\uddf7","f":"Boca fans are called 'Xeneizes', a nod to the Genoese immigrants of the club's La Boca neighbourhood.","o":["Boca Juniors","River Plate","Racing Club","Independiente"],"s":{"index":1}},{"k":"choice","i":"Arsenal's fiercest local rivalry, the North London derby, is against which club?","t":"Derbies","e":"\ud83d\udd34","f":"The rivalry took off after Arsenal moved north from Woolwich to Highbury in 1913, close to Tottenham's ground.","o":["Chelsea","West Ham United","Fulham","Tottenham Hotspur"],"s":{"index":3}},{"k":"number","i":"How many times did Magic Johnson and Larry Bird meet in the NBA Finals?","t":"Basketball","e":"\ud83c\udfc0","f":"Their duels are widely credited with reviving the NBA's popularity in the 1980s.","s":{"value":3,"tolerance":0,"min":0,"max":10,"unit":""}},{"k":"truefalse","i":"Real Madrid and Barcelona have never met in a Champions League semi-final.","t":"Football","e":"\u26bd","f":"They met in the semi-finals in 2002 and 2011: Real Madrid went through in 2002 and Barcelona in 2011.","a":false},{"k":"multi","i":"Select all the rivalries between teams from the same city.","t":"Derbies","e":"\ud83c\udfd9\ufe0f","f":"Boca and River both come from Buenos Aires, while the other rivalries pit different cities against each other.","o":["Celtic v Rangers","Real Madrid v Barcelona","Boca Juniors v River Plate","New York Yankees v Boston Red Sox","Los Angeles Lakers v Boston Celtics"],"s":{"indices":[0,2]}},{"k":"order","i":"Order these rivalry moments from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"Ali\u2013Frazier I was in 1971, the college final in 1979, Prost and Senna paired up in 1988 and the Wimbledon epic came in 2008.","o":["Ali and Frazier's first fight at Madison Square Garden","Magic and Bird meet in the college final","Prost and Senna become McLaren teammates","Federer and Nadal's epic Wimbledon final"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '952e3d09f8fa70e9fd6c51f60bbcd6d3' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 20'; end $q$;
